var e=Object.defineProperty,t=(t,n)=>{let r={};for(var i in t)e(r,i,{get:t[i],enumerable:!0});return n||e(r,Symbol.toStringTag,{value:`Module`}),r};(function(){let e=document.createElement(`link`).relList;if(e&&e.supports&&e.supports(`modulepreload`))return;for(let e of document.querySelectorAll(`link[rel="modulepreload"]`))n(e);new MutationObserver(e=>{for(let t of e)if(t.type===`childList`)for(let e of t.addedNodes)e.tagName===`LINK`&&e.rel===`modulepreload`&&n(e)}).observe(document,{childList:!0,subtree:!0});function t(e){let t={};return e.integrity&&(t.integrity=e.integrity),e.referrerPolicy&&(t.referrerPolicy=e.referrerPolicy),t.credentials=e.crossOrigin===`use-credentials`?`include`:e.crossOrigin===`anonymous`?`omit`:`same-origin`,t}function n(e){if(e.ep)return;e.ep=!0;let n=t(e);fetch(e.href,n)}})();var n={"Na boca do poço mais fundo do rio tem um flutuante. É o Boca do Poço, a nossa casa e o nosso restaurante.":`At the mouth of the deepest pool on the river there is a floating diner. It's the Boca do Poço, our home and our restaurant.`,"O meu Raimundo mergulhava e trazia o peixe. Eu cozinhava. De noite, não passava barco que não encostasse.":`My Raimundo would dive and bring up the fish. I did the cooking. At night, not a single boat passed without pulling in.`,"Ele dizia que, de madrugada, o fundo do poço acendia. Eu achava que era conversa de pescador.":`He used to say that, before dawn, the bottom of the pool lit up. I thought it was just fishermen's talk.`,"Numa noite de cheia, ele desceu com a lamparina e não voltou.":`One night of high water, he went down with the lantern and never came back.`,"Ficaram a brasa acesa, o balcão vazio e uma dívida no caderno do Seu Agenor, o Regatão. Do tamanho do flutuante.":`What was left: the embers still glowing, the empty counter, and a debt in the ledger of Seu Agenor, the River Trader. As big as the diner itself.`,"Foi aí que o Tuca, nosso neto, voltou da cidade. Veio me ajudar a tocar o restaurante.":`That's when Tuca, our grandson, came back from the city. He came to help me run the restaurant.`,"Sem peixe não tem prato. Então, todo dia, ele desce o poço e traz o pescado. De noite, eu cozinho e ele serve. Cada noite boa paga um pedaço da dívida.":`No fish, no dish. So every day he dives down the pool and brings up the catch. At night, I cook and he serves. Every good night pays off a piece of the debt.`,"E lá embaixo, o rio ainda guarda o que aconteceu com o Raimundo.":`And down below, the river still keeps what happened to Raimundo.`,"Saco de urucum":`Urucum pouch`,"Chamariz de pano":`Cloth decoy`,"Rondando você":`Circling you`,"Vai dar o bote: rebata com a faca!":`He's about to lunge: parry with your knife!`,"Rebata agora!":`Parry now!`,"Tonto: arpão e faca agora!":`Dazed: harpoon and knife now!`,"Ela está acordando…":`She's waking up…`,"Vai dar o bote: saia da frente!":`She's about to strike: move!`,"Saia da frente!":`Get out of the way!`,"Boca aberta: atire agora!":`Mouth open: shoot now!`,"Cuidado com a cauda!":`Watch the tail!`,"Ela desistiu de você":`She gave up on you`,"Amanheceu: dia {dia}":`Dawn: day {dia}`,"A tarde chegou":`Afternoon's here`,"Anoiteceu: o Boca do Poço pode abrir":`Nightfall: the Boca do Poço can open`,"Peixe forte! Aperte espaço (ou clique) bem rápido para cansá-lo.":`Strong fish! Mash Space (or click) to tire it out.`,"Peixe forte! Alterne A e D bem rápido.":`Strong fish! Alternate A and D fast.`,"Peixe forte! Aperte as setas na ordem, antes que o tempo acabe.":`Strong fish! Press the arrows in order before time runs out.`,"Peixe forte! Aperte espaço quando o marcador passar no verde.":`Strong fish! Press Space when the marker hits the green.`,"Levar o barco até o Boca do Poço, que abre agora.":`Sail to the Boca do Poço. It's opening now.`,"na escada":`at the ladder`,"Levar o barco pelo rio. O Boca do Poço abre à noite.":`Sail the river. The Boca do Poço opens at night.`,"no leme":`at the helm`,"Melhorar o tanque, o traje, a carga e as armas.":`Upgrade your tank, suit, haul, and weapons.`,"na bancada":`at the workbench`,"Deixar o turno passar sem mergulhar.":`Let this turn pass without diving.`,"no banco da proa":`on the bow bench`,"Antes do primeiro mergulho":`Before the first dive`,"De volta ao barco":`Back on the boat`,"Barco ancorado no igapó. O mergulho daqui é entre as árvores.":`Boat anchored at the flooded forest. From here you dive among the trees.`,"Barco ancorado no poço.":`Boat anchored at the pool.`,"{destino}: {motivo}":`{destino}: {motivo}`,"{destino} · {rotulo}":`{destino} · {rotulo}`,Final:`Finale`,"Capítulo {numero}":`Chapter {numero}`,"Abrir o cardápio":`Open the menu`,"{escalados} de {vagas} na noite":`{escalados} of {vagas} on shift`,limpeza:`cleaning`,pilão:`mortar`,tacacá:`tacacá`,"serve os pratos":`serves dishes`,"Um freguês":`A customer`,"Primeira noite":`First night`,"Primeira noite · {numero} de {total}":`First night · {numero} of {total}`,"Cansei de esperar!":`I'm done waiting!`,"Um freguês cansou de esperar e foi embora":`A customer got tired of waiting and left`,"{prato} acabou":`{prato}: sold out`,"Um prato":`A dish`,"Tacacá na marca: ele paga 30% a mais":`Tacacá right on the line: they pay 30% more`,"Passou da marca: derramou o tacacá":`Over the line: the tacacá spilled`,"Faltou tacacá na cuia":`The bowl came up short`,"Acabou a farinha: a cozinha parou. Soque o pilão!":`Out of flour: the kitchen stopped. Pound the mortar!`,"Um peixe-boi! Ele deixou você chegar perto. Presente do igapó: {ouro} moedas.":`A manatee! It let you come close. A gift from the flooded forest: {ouro} coins.`,"Encomenda do flutuante: {encomendas}":`Diner order: {encomendas}`,"A porta dos encantados te espera no fundo. O Tição também.":`The door of the enchanted ones awaits you below. So does Tição.`,"Tutorial concluído. Agora abra o Boca do Poço e sirva o que pescou!":`Tutorial complete. Now open the Boca do Poço and serve what you caught!`,"Primeiro mergulho · {numero} de {total}":`First dive · {numero} of {total}`,"Carga cheia! Volte ao barco.":`Haul full! Head back to the boat.`,"Encomenda cumprida: {encomenda} (+{premio})":`Order filled: {encomenda} (+{premio})`,"Soltou {nome}":`Dropped {nome}`,"Espécie nova! {peixe}":`New species! {peixe}`,"Espécie nova no caderno: {peixe} · +{moedas} moedas":`New species in the logbook: {peixe} · +{moedas} coins`,"Abatido!":`Down!`,"Falta {n}":{one:`{n} more`,other:`{n} more`},"Rebateu!":`Parried!`,"O Tição está tonto: agora o arpão e a faca ferem!":`Tição is dazed: now the harpoon and knife can hurt him!`,"A porta dos encantados":`The door of the enchanted ones`,"O Tição afunda na escuridão e não volta. A porta se abre devagar, e a água do fundo acende como o avô dizia: luzes que cantam. Lá em cima, um estrondo: a draga do Doutor Brandão adernou e foi ao fundo, longe do poço. Uma voz conhecida chama o teu nome.":`Tição sinks into the dark and doesn't come back. The door opens slowly, and the water below lights up just as Grandpa said: lights that sing. Up above, a crash: Doctor Brandão's dredge keeled over and sank, far from the pool. A familiar voice calls your name.`,"Presente dos encantados: {ouro} moedas. Volte ao balcão: tem alguém esperando.":`A gift from the enchanted ones: {ouro} coins. Go back to the counter: someone is waiting.`,"Boia de resgate: {peixe} {marca} a caminho do barco":`Rescue buoy: {peixe} {marca} on its way to the boat`,"{peixe} {marca} · {peso} kg":`{peixe} {marca} · {peso} kg`,"Este {peixe} está doente: Dona Naná não vai cozinhar.":`This {peixe} is sick: Dona Naná won't cook it.`,"O couro do jacaré não fura. Só o rebate de faca o afasta.":`The caiman's hide won't pierce. Only a knife parry drives it off.`,"O couro dela não fura. Espere o bote: cansada, ela abre a boca.":`Her hide won't pierce. Wait for her to strike: once she's tired, she opens her mouth.`,"A Cobra-Grande se recolheu e deixou uma escama: +{valor}":`The Great Serpent retreated and left a scale behind: +{valor}`,"Uma posta de {peixe} · +{valor}":{one:`One {peixe} steak · +{valor}`,other:`{n} {peixe} steaks · +{valor}`},"Tanque cheio: o cilindro fica aí para quando faltar ar.":`Tank full: the cylinder stays here for when you run low.`,"+{ar} de ar":`+{ar} air`,"Já leva {caixas} caixas de munição guardadas: esta fica para depois.":`Already carrying {caixas} spare ammo boxes: this one stays for later.`,"{arma}: +{tiros} de munição":`{arma}: +{tiros} ammo`,"+{tiros} munição":`+{tiros} ammo`,"Caixa de munição guardada ({caixas}): entra quando a arma esvaziar.":`Ammo box stored ({caixas}): loads when the weapon runs empty.`,"Caixa de munição guardada ({caixas}): serve para a arma que você achar num caixote.":`Ammo box stored ({caixas}): for the weapon you find in a crate.`,"Caixa guardada":`Box stored`,"{item} para o barco":`{item} to the boat`,"Peças de {arma} para o Barco (+1)":`Parts of {arma} for the Boat (+1)`,"Projeto liberado: {arma}. Dá para construir no Barco.":`Blueprint unlocked: {arma}. You can build it on the Boat.`,"{apetrecho} no cinto · {tecla} para usar":`{apetrecho} on your belt · {tecla} to use`,"Tarrafa: +{lances} lances":`Cast net: +{lances} casts`,"+{lances} lances":`+{lances} casts`,"Punhado de moedas":`Handful of coins`,"Moedas +{valor}":`Coins +{valor}`,"Boia de resgate: leva um peixe grande direto para o barco":`Rescue buoy: sends a big fish straight to the boat`,"+1 boia":`+1 buoy`,"Nuvem de urucum: os bichos perderam você de vista":`Urucum cloud: the creatures lost sight of you`,"Chamariz solto: os bichos vão atrás dele":`Decoy out: the creatures go after it`,"O Tição levou {peixe} da sua carga!":`Tição snatched the {peixe} from your catch!`,"{bicho} enrolou você! Aperte espaço bem rápido para se soltar.":`{bicho} wrapped around you! Mash Space to break free.`,"{bicho} investiu!":`{bicho} lunged!`,"O veneno derrubou o peixe: ele fica boiando e vale 1 estrela.":`The poison took the fish down: it floats and is worth 1 star.`,"{bicho} bateu na pedra e ficou tonta!":`{bicho} hit the rock and is dazed!`,"Ferroada de arraia!":`Stingray sting!`,"A Cobra-Grande acordou!":`The Great Serpent woke up!`,"O bote da Cobra-Grande pegou você!":`The Great Serpent's strike hit you!`,"A cauda dela pegou você!":`Her tail hit you!`,"Ela cansou e abriu a boca: atire na cabeça agora!":`She's tired and her mouth is open: shoot the head now!`,"A Cobra-Grande voltou a dormir. O que ela perdeu de vida, continua perdido.":`The Great Serpent went back to sleep. The health she lost stays lost.`,"O Tição saiu da porta!":`Tição came out of the door!`,"O bote do Tição pegou você!":`Tição's lunge got you!`,"O Tição voltou para a porta. O que ele perdeu de vida, continua perdido.":`Tição went back to the door. The health he lost stays lost.`,"O boto achou um caixote: vá atrás dele!":`The river dolphin found a crate: follow it!`,"Dormiu!":`Asleep!`,"Peixe grande demais para a linha: chegue perto para mandá-lo de boia ao barco.":`Too big for the line: swim close to send it up by buoy.`,"Peixe grande demais para a linha: chegue perto para recolher.":`Too big for the line: swim close to collect it.`,"Fisgou!":`Hooked!`,"Atordoado!":`Stunned!`,Envenenado:`Poisoned`,"Cansou!":`Worn out!`,"A linha cedeu — o peixe escapou!":`The line gave way — the fish got away!`,"Você se soltou!":`You broke free!`,"{bicho} cansou e soltou você.":`{bicho} got tired and let you go.`,"{arma}: a caixa guardada entrou, +{tiros} de munição":`{arma}: spare box loaded, +{tiros} ammo`,"{arma} sem munição: ficou para trás.":`{arma} out of ammo: left behind.`,"Adormecido, o peixe fica parado: chegue perto para recolher. Vem vivo, com 3 estrelas.":`Asleep, the fish stays still: swim close to collect it. It comes up alive, with 3 stars.`,"Grogue! Mais um dardo":`Groggy! One more dart`,"Abatido a tiro, o peixe fica boiando: chegue perto para recolher. Vale 1 estrela.":`Shot down, the fish floats: swim close to collect it. Worth 1 star.`,"{presos} na rede!":`{presos} in the net!`,"Forte demais para a tarrafa: esse é no arpão.":`Too strong for the cast net: this one needs the harpoon.`,Zzz:`Zzz`,"Choque do poraquê!":`Electric eel shock!`,"Bolsão de ar: tanque cheio":`Air pocket: tank full`,"Tem alguma coisa brilhando no chão, aqui perto.":`Something's glinting on the bottom nearby.`,Tição:`Tição`,"Pouco ar! Volte ao barco.":`Low air! Head back to the boat.`,"Fundo demais para este traje ({limite} m): o ar acaba {fator}× mais rápido. No barco tem um melhor.":`Too deep for this suit ({limite} m): air runs out {fator}× faster. There's a better one on the boat.`,"Subir no barco":`Climb aboard`,"Subir pela boia":`Ride the buoy up`,"Abrir o caixote":`Open the crate`,"Arrancar o minério com a faca":`Pry the ore loose with the knife`,"Tirar postas com a faca":`Cut steaks with the knife`,"Boca do Poço":`Boca do Poço`,"PEIXE NA BRASA  •  TACACÁ":`GRILLED FISH  •  TACACÁ`,HOJE:`TODAY`,"peixe fresco":`fresh fish`,"{nome} (doente)":`{nome} (sick)`,"Posta de {peixe}":`{peixe} steak`,Leme:`Helm`,Bancada:`Workbench`,Escada:`Ladder`,"Banco da proa":`Bow bench`,"Mapa do rio":`River map`,Equipamento:`Gear`,"Descer de madrugada":`Dive before dawn`,Mergulhar:`Dive`,"O rio descansa à noite":`The river rests at night`,"Dormir sem abrir a casa":`Sleep without opening`,"Dormir até de manhã":`Sleep until morning`,"Descansar até a tarde":`Rest until afternoon`,"Descansar até a noite":`Rest until night`,Madrugada:`Before dawn`,Manhã:`Morning`,Tarde:`Afternoon`,Noite:`Night`,"Pasta devagar entre as raízes do igapó. Deixou o Tuca chegar perto e não teve medo.":`Grazes slowly among the roots of the flooded forest. It let Tuca come close and wasn't afraid.`,peixe:`fish`,"Descer ao igapó e pescar. Gasta este turno.":`Dive into the flooded forest and fish. Uses this turn.`,"Madrugada do dia {dia}: o igapó está escuro":`Before dawn, day {dia}: the flooded forest is dark`,Galhada:`Branches`,"Ar preso entre as raízes: entre nele para encher o tanque.":`Air trapped among the roots: swim into it to refill your tank.`,"Você no igapó · barco no alto · pontos claros: bolsões de ar":`You in the flooded forest · boat up top · bright dots: air pockets`,"Descer ao poço e pescar. Gasta este turno.":`Go down into the pool and fish. Uses this turn.`,"Madrugada do dia {dia}: o poço está escuro":`Before dawn, day {dia}: the pool is dark`,Paredões:`Cliffs`,"Ar preso no teto da gruta: entre nele para encher o tanque.":`Air trapped under the cave roof: swim into it to refill your tank.`,"Você no poço · barco no alto · pontos claros: bolsões de ar":`You in the pool · boat up top · bright dots: air pockets`,"Poço do Raimundo":`Raimundo's Pool`,Igapó:`Igapó (flooded forest)`,"Voltar ao convés":`Back to deck`,"Ancorar no poço":`Anchor at the pool`,"Ancorar no igapó":`Anchor at the flooded forest`,"Abrir o Boca do Poço":`Open the Boca do Poço`,"Abre à noite":`Opens at night`,"Nade para o fundo":`Swim down`,"Desça alguns metros. Segure Shift para arrancar, mas gasta mais ar.":`Go down a few meters. Hold Shift to dash, but it uses more air.`,"O ar é a sua vida":`Air is your life`,"Este medidor é o ar do tanque. Ele cai com o tempo, mais rápido no fundo e a cada ferida.":`This gauge is the air in your tank. It drops over time, faster in the deep and with every wound.`,"Se o ar acabar, você desmaia, é puxado de volta ao barco e perde metade do pescado. Volte antes!":`If the air runs out, you pass out, get pulled back to the boat and lose half your catch. Head back in time!`,"Pesque um peixe":`Catch a fish`,Mouse:`Mouse`,"Segure o botão do mouse para mirar e solte para atirar. Peixe forte: aperte Espaço para cansá-lo.":`Hold the mouse button to aim, release to shoot. Strong fish: press Space to tire it out.`,"O peso da carga":`The weight of the haul`,"A barra mostra o peso que você leva e o máximo que aguenta. Cheia, não cabe mais nada.":`The bar shows the weight you carry and the most you can take. When it's full, nothing else fits.`,"Aperte C para ver a carga e solte o peixe que vale menos. Na bancada do barco dá para aumentar a capacidade.":`Press C to see your haul and drop the fish worth the least. At the boat's workbench you can increase capacity.`,"Abra e pegue com a faca":`Open and grab with the knife`,"Perto de um caixote, de uma caixa ou de um achado, aperte F.":`Near a crate, a box, or a find, press F.`,"Volte ao barco":`Head back to the boat`,"Suba até o barco (ou uma boia) e aperte E. O peixe que sobe vai para a cozinha.":`Swim up to the boat (or a buoy) and press E. Fish you bring up go to the kitchen.`,"Metade do ar. Vá pensando na volta.":`Half the air. Start thinking about the way back.`,"Só um quarto do ar! Volte ao barco ou ache um bolsão de ar.":`Only a quarter of the air left! Return to the boat or find an air pocket.`,"Por que o Tuca mergulha":`Why Tuca dives`,"Meu neto, sem peixe não tem prato. De dia você desce o poço e traz o pescado; de noite a gente abre o Boca do Poço, e cada noite boa paga um pedaço da dívida do seu avô.":`My grandson, no fish, no dish. By day you go down the pool and bring up the catch; at night we open the Boca do Poço, and every good night pays off a piece of your grandfather's debt.`,"O barco":`The boat`,"Ande pelo convés com A e D e aperte E em cima de um ponto.":`Walk along the deck with A and D and press E on a spot.`,"leva o barco pelo rio; de noite, até o Boca do Poço":`takes the boat along the river; at night, to the Boca do Poço`,"melhora o tanque, o traje, a carga e as armas":`upgrades the tank, the suit, the haul and the weapons`,"desce ao poço para pescar":`goes down the pool to fish`,"descansa e deixa o turno passar":`rests and lets the shift pass`,"O caderno de bordo":`The logbook`,'Aperte Tab para abrir o caderno. Na aba "Espécies" ficam os peixes que você já pescou e onde cada um vive.':`Press Tab to open the logbook. The "Species" tab holds the fish you've already caught and where each one lives.`,"A primeira noite":`The first night`,"A e D andam pelo balcão. Os fregueses chegam, pedem, comem e pagam: cada prato servido vira moeda.":`A and D walk you along the counter. Customers arrive, order, eat and pay: every dish served turns into coins.`,"O pedido":`The order`,"O balão em cima do freguês mostra o prato que ele quer.":`The bubble above the customer shows the dish they want.`,"O passa-prato":`The serving hatch`,"Os pratos saem prontos aqui. Vá até o passa-prato e aperte E para pegar.":`Dishes come out ready here. Go to the hatch and press E to pick them up.`,"Entregue o prato":`Deliver the dish`,"Leve o prato até quem pediu e aperte E na frente dele.":`Take the dish to whoever ordered it and press E in front of them.`,"A louça":`The dirty dishes`,"Quem comeu deixa a louça no balcão. Aperte E em cima dela para limpar o lugar para o próximo freguês.":`Whoever ate leaves the dishes on the counter. Press E on them to clear the spot for the next customer.`,"O tacacá":`The tacacá`,"Tacacá se serve na hora: segure E para encher a cuia e solte na marca.":`Tacacá is served on the spot: hold E to fill the gourd bowl and release at the mark.`,"Quem espera, cansa":`Waiting wears them out`,"Quem espera demais vai embora sem pagar, e a fama cai. Sirva primeiro quem chegou antes.":`Customers who wait too long leave without paying, and fame drops. Serve whoever came first.`,"O caderno do Regatão":`The River Trader's ledger`,"Fechada a casa, o Regatão anota a noite: o que vendeu, o que gastou e a fama. O lucro de cada noite boa paga um pedaço da dívida do avô.":`When the house closes, the River Trader writes down the night: what sold, what was spent and the fame. The profit from every good night pays off a piece of grandpa's debt.`,Pular:`Skip`,Raso:`Shallows`,Abismo:`Abyss`,Espaço:`Space`,"{distancia} m":`{distancia} m`,"Liga e desliga o som (tecla M)":`Sound on/off (M key)`,Volume:`Volume`,"Ar no tanque":`Air in tank`,"{metros} m · {faixa}":`{metros} m · {faixa}`,"pressão!":`pressure!`,"{peso}/{capacidade} kg":`{peso}/{capacidade} kg`,"Ver o que você pegou (tecla C)":`See your haul (C key)`,Carga:`Haul`,"{peso} kg · {valor} moedas":`{peso} kg · {valor} coins`,Arpão:`Harpoon`,"Mouse 1":`Mouse 1`,"Tarrafa: traz vivos os peixes pequenos":`Cast net: brings small fish up alive`,Faca:`Knife`,"Lanterna (acende sozinha no escuro)":`Flashlight (turns on by itself in the dark)`,"<kbd>Tab</kbd> troca":`<kbd>Tab</kbd> switch`,"<kbd>WASD</kbd> nada · <kbd>Shift</kbd> arrancada · <kbd>Mouse 1</kbd> segure para mirar, solte para atirar · <kbd>Tab</kbd> troca a arma · <kbd>F</kbd> faca · <kbd>C</kbd> carga · <kbd>Q</kbd> apetrecho":`<kbd>WASD</kbd> swim · <kbd>Shift</kbd> dash · <kbd>Mouse 1</kbd> hold to aim, release to shoot · <kbd>Tab</kbd> switch weapon · <kbd>F</kbd> knife · <kbd>C</kbd> haul · <kbd>Q</kbd> gear`,"Pular o tutorial":`Skip the tutorial`,pular:`skip`,"Nada pescado ainda":`Nothing caught yet`,"{peso} kg":`{peso} kg`,"Soltar um (libera o peso)":`Drop one (frees weight)`,"Arpão · {ponta}":`Harpoon · {ponta}`,"{arma} (achada num caixote: vale só neste mergulho)":`{arma} (found in a crate: this dive only)`,"Arpão sem ponta":`Plain harpoon`,"{ponta} · tarrafa {lances} · boias {boias} · {arma} {municao}":`{ponta} · net {lances} · buoys {boias} · {arma} {municao}`,"{ponta} · tarrafa {lances} · boias {boias}":`{ponta} · net {lances} · buoys {boias}`,Baixo:`Low`,"Para computador fraco: sem brilho nas luzes e menos partículas.":`For weak computers: no glow on the lights and fewer particles.`,Médio:`Medium`,"Resolução um pouco menor, brilho mais leve e menos partículas.":`Slightly lower resolution, softer glow and fewer particles.`,Alto:`High`,"O rio com tudo o que ele tem.":`The river with everything it has.`,"Opções (Esc)":`Options (Esc)`,Opções:`Options`,"Fechar (Esc)":`Close (Esc)`,Som:`Sound`,"Volume geral":`Master volume`,Música:`Music`,Efeitos:`Effects`,"Interface e voz":`Interface and voice`,Mudo:`Mute`,Gráficos:`Graphics`,Interface:`Interface`,Tamanho:`Size`,"Tamanho da interface":`Interface size`,Idioma:`Language`,"Trocar de idioma recarrega o jogo. O progresso fica salvo.":`Changing the language reloads the game. Your progress is saved.`,Continuar:`Continue`,"Sem som":`No sound`,"Som ligado":`Sound on`,"Voltar mesmo? O que não foi guardado se perde.":`Really go back? Anything not saved will be lost.`,"Voltar ao título":`Back to title`,"<kbd>A</kbd><kbd>D</kbd> andar pelo convés · <kbd>E</kbd> usar · <kbd>Tab</kbd> caderno de bordo":`<kbd>A</kbd><kbd>D</kbd> walk the deck · <kbd>E</kbd> use · <kbd>Tab</kbd> logbook`,"<kbd>A</kbd><kbd>D</kbd> escolher o lugar · <kbd>E</kbd> navegar até lá · <kbd>Esc</kbd> voltar ao convés":`<kbd>A</kbd><kbd>D</kbd> pick a spot · <kbd>E</kbd> sail there · <kbd>Esc</kbd> back to deck`,"Dia {dia}":`Day {dia}`,"Caderno de bordo (Tab)":`Logbook (Tab)`,Caderno:`Logbook`,Tab:`Tab`,"Caderno de bordo":`Logbook`,"Dia {dia} · {turno}":`Day {dia} · {turno}`,"O que fazer":`What to do`,"Como jogar":`How to play`,Espécies:`Species`,"O progresso fica salvo.":`Your progress is saved.`,"Sair do jogo":`Quit game`,"O dia":`The day`,"<b>Manhã e tarde</b>um mergulho em cada turno":`<b>Morning and afternoon</b>one dive each`,"<b>No barco</b>o peixe que sobe vai para a despensa":`<b>On the boat</b>fish you bring up go to the pantry`,"<b>Noite</b>o Boca do Poço abre e você serve no balcão":`<b>Night</b>the Boca do Poço opens and you work the counter`,"<b>Com o ouro</b>mais ar, mais carga e mais fundo":`<b>With your coins</b>more air, bigger haul, deeper dives`,"No mergulho":`Diving`,"<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> arrancada":`<kbd>WASD</kbd> swim · <kbd>Shift</kbd> dash`,"<kbd>Mouse</kbd> segure para mirar, solte para atirar":`<kbd>Mouse</kbd> hold to aim, release to shoot`,"<kbd>F</kbd> faca: abre caixote, pega achado":`<kbd>F</kbd> knife: open crates, grab finds`,"<kbd>Tab</kbd> troca a arma · <kbd>C</kbd> carga":`<kbd>Tab</kbd> switch weapon · <kbd>C</kbd> haul`,"<kbd>E</kbd> subir no barco ou pela boia":`<kbd>E</kbd> climb aboard or ride a buoy up`,"No restaurante":`At the diner`,"<kbd>A</kbd><kbd>D</kbd> andar pelo balcão":`<kbd>A</kbd><kbd>D</kbd> move along the counter`,"<kbd>E</kbd> pegar, servir, limpar e socar":`<kbd>E</kbd> grab, serve, clean, and pound`,"segure <kbd>E</kbd> para encher a cuia de tacacá":`hold <kbd>E</kbd> to fill the tacacá bowl`,Lembranças:`Memories`,"<kbd>A</kbd><kbd>D</kbd> escolher · <kbd>E</kbd> ou <kbd>Enter</kbd> fazer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> ou <kbd>Esc</kbd> fechar":`<kbd>A</kbd><kbd>D</kbd> choose · <kbd>E</kbd> or <kbd>Enter</kbd> do it · <kbd>C</kbd> pages · <kbd>Tab</kbd> or <kbd>Esc</kbd> close`,"Fama <b>{fama}</b>":`Fame <b>{fama}</b>`,"Despensa <b>{n}</b> peixe":{one:`Pantry <b>{n}</b> fish`,other:`Pantry <b>{n}</b> fish`},"<b>{n}</b> de {total} espécies no caderno":`<b>{n}</b> of {total} species in the log`,"{n} pescado":{one:`{n} caught`,other:`{n} caught`},"maior: {peso} kg":`biggest: {peso} kg`,"Vive entre {min} e {max} m":`Lives between {min} and {max} m`,"3★ rende {corte}":`3★ gives {corte}`,"Encontro anotado":`Encounter noted`,"Fama no rio · {grau}":`River fame · {grau}`,Canoa:`Canoe`,farinha:`flour`,"<kbd>A</kbd><kbd>D</kbd> andar · <kbd>E</kbd> ou <kbd>espaço</kbd> pegar, servir, limpar e socar · segure para encher a cuia":`<kbd>A</kbd><kbd>D</kbd> move · <kbd>E</kbd> or <kbd>Space</kbd> grab, serve, clean, pound · hold to fill the bowl`,limpar:`clean`,"{n} moeda":{one:`{n} coin`,other:`{n} coins`},"hora de abrir o Boca do Poço":`time to open the Boca do Poço`,"descer no escuro ou dormir até de manhã":`dive in the dark or sleep until morning`,"dois mergulhos até a noite":`two dives before night`,"último mergulho antes da noite":`last dive before night`,"Primeiro mergulho":`First dive`,"{n} mergulho":{one:`{n} dive`,other:`{n} dives`},"Melhor mergulho: {moedas} · {vezes}":`Best dive: {moedas} · {vezes}`,"no máximo":`maxed out`,"Ache esta arma nos caixotes para liberar o projeto: {achadas} de {precisa}.":`Find this weapon in crates to unlock the blueprint: {achadas} of {precisa}.`,"✓ Levando":`✓ Bringing`,Levar:`Bring`,"{n} peça · −{desconto}% de ouro":{one:`{n} part · −{desconto}% coins`,other:`{n} parts · −{desconto}% coins`},"O rio está acordando":`The river is waking up`,"Ainda dá um mergulho":`Still time for a dive`,"A noite é do Boca do Poço":`The night belongs to the Boca do Poço`,"De dia, o poço · de noite, o balcão":`By day, the pool · by night, the counter`,"O Tuca pesca no fundo do poço para abastecer o balcão do <strong>restaurante flutuante</strong> da Dona Naná.":`Tuca fishes the depths of the pool to stock the counter of Dona Naná's <strong>floating diner</strong>.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa enche o balcão da Dona Naná.":`What Tuca brings up from the river becomes the night's dish, and every good night fills Dona Naná's counter.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa paga um pedaço da dívida do avô.":`What Tuca brings up from the river becomes the night's dish, and every good night pays off a piece of his grandfather's debt.`,"No barco":`On the boat`,Começar:`Start`,"Como o jogo funciona":`How the game works`,"<b>Mergulhe</b>Pesque e junte achados enquanto o ar durar.":`<b>Dive</b>Fish and gather finds while your air lasts.`,"<b>Volte ao barco</b>O peixe que sobe vai para a despensa do restaurante.":`<b>Return to the boat</b>Fish you bring up go to the diner's pantry.`,"<b>À noite, abra o Boca do Poço</b>Monte o cardápio e sirva os fregueses no balcão.":`<b>At night, open the Boca do Poço</b>Set the menu and serve customers at the counter.`,"<b>Melhore o barco</b>Com o ouro, mais ar, mais carga e mais fundo.":`<b>Upgrade the boat</b>Spend coins on more air, a bigger haul, and deeper dives.`,"O dia tem dois mergulhos, um de manhã e um de tarde; à noite o restaurante abre com o que você pescou. A nota da noite e a fama crescem com o capricho no serviço.":`Each day has two dives, one in the morning and one in the afternoon; at night the diner opens with what you caught. The night's rating and your fame grow with good service.`,"<kbd>WASD</kbd> nadar":`<kbd>WASD</kbd> swim`,"<kbd>Mouse 1</kbd> segure para mirar, solte para atirar":`<kbd>Mouse 1</kbd> hold to aim, release to shoot`,"<kbd>Shift</kbd> arrancada (gasta mais ar)":`<kbd>Shift</kbd> dash (uses more air)`,"<kbd>Tab</kbd> arpão · arma · tarrafa · faca":`<kbd>Tab</kbd> harpoon · weapon · cast net · knife`,"<kbd>F</kbd> faca: abre caixote e caixa de munição, pega achado e arranca minério":`<kbd>F</kbd> knife: open crates and ammo boxes, grab finds, pry ore`,"<kbd>Espaço</kbd> contra peixe forte":`<kbd>Space</kbd> against strong fish`,"<kbd>C</kbd> carga":`<kbd>C</kbd> haul`,"<kbd>E</kbd> subir (barco ou boia)":`<kbd>E</kbd> go up (boat or buoy)`,"<kbd>Q</kbd> apetrecho de defesa: nuvem de urucum ou chamariz de pano":`<kbd>Q</kbd> defense gear: urucum cloud or cloth decoy`,"<kbd>M</kbd> som":`<kbd>M</kbd> sound`,"Volte ao barco antes que o ar acabe: o peixe que sobe vai para a cozinha.":`Get back to the boat before your air runs out: fish you bring up go to the kitchen.`,"<kbd>E</kbd> ou <kbd>Espaço</kbd> pegar o prato, servir, limpar e socar o pilão":`<kbd>E</kbd> or <kbd>Space</kbd> grab dishes, serve, clean, and pound the mortar`,"Sirva a cada freguês o prato que ele pediu antes que a paciência acabe.":`Serve each customer the dish they ordered before their patience runs out.`,"Com controle":`With a controller`,"<kbd>Analógico esquerdo</kbd> nadar e andar · <kbd>LT</kbd> arrancada":`<kbd>Left stick</kbd> swim and walk · <kbd>LT</kbd> dash`,"<kbd>RT</kbd> segure para mirar com o <kbd>analógico direito</kbd>, solte para atirar":`<kbd>RT</kbd> hold to aim with the <kbd>right stick</kbd>, release to shoot`,"<kbd>A</kbd> usar · <kbd>B</kbd> voltar · <kbd>X</kbd> faca · <kbd>Y</kbd> troca a arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> apetrecho":`<kbd>A</kbd> use · <kbd>B</kbd> back · <kbd>X</kbd> knife · <kbd>Y</kbd> switch weapon · <kbd>LB</kbd> haul · <kbd>R3</kbd> gear`,Entendi:`Got it`,"Fim do mergulho":`Dive over`,"Você desmaiou":`You passed out`,"Subiu pela boia":`Rode the buoy up`,"Você foi puxado para o barco às pressas e só conseguiu segurar a metade mais leve da carga.":`You were hauled up to the boat in a hurry and only held on to the lighter half of your haul.`,"Você voltou de mãos vazias. O rio continua lá.":`You came back empty-handed. The river's still there.`,"Tudo o que você pescou e achou chegou ao barco.":`Everything you caught and found made it to the boat.`,"Ficou para trás":`Left behind`,"Guardado no barco para construir armas: {itens}":`Stored on the boat for building weapons: {itens}`,"Para a despensa do Boca do Poço (não entra no total): {porcoes}":`For the Boca do Poço pantry (not in the total): {porcoes}`,"<b>{n}</b> porção de {peixe}":{one:`<b>{n}</b> serving of {peixe}`,other:`<b>{n}</b> servings of {peixe}`},"Cortes nobres para a cozinha: {cortes}":`Prime cuts for the kitchen: {cortes}`,"<b>{n}</b> porção de {corte}":{one:`<b>{n}</b> serving of {corte}`,other:`<b>{n}</b> servings of {corte}`},'Seu Agenor levou <b>{n}</b> peixe doente: +{ouro}. "Não pergunto de onde veio."':{one:`Agenor took <b>{n}</b> sick fish: +{ouro}. "I don't ask where it came from."`,other:`Agenor took <b>{n}</b> sick fish: +{ouro}. "I don't ask where they came from."`},"Novas no caderno de espécies: {peixes}":`New in the species log: {peixes}`,"Encomendas do flutuante":`Diner orders`,"Total com encomendas":`Total with orders`,Total:`Total`,"Novo recorde!":`New record!`,"Voltar ao barco":`Back to the boat`,"{preco} o prato · {n} porção na despensa":{one:`{preco} a dish · {n} serving in the pantry`,other:`{preco} a dish · {n} servings in the pantry`},"Boca do Poço · fama {grau}":`Boca do Poço · fame: {grau}`,"O cardápio da noite":`Tonight's menu`,"Escolha até {vagas} pratos. Hoje vêm {fregueses} fregueses; o que sobrar volta para a despensa.":`Pick up to {vagas} dishes. {fregueses} customers are coming tonight; leftovers go back to the pantry.`,"Abrir com {n} porção":{one:`Open with {n} serving`,other:`Open with {n} servings`},"Abrir só com cafezinho":`Open with just coffee`,"Equipe · {equipe}":`Staff · {equipe}`,Equipe:`Staff`,"A casa":`The diner`,"Vender a despensa ao Regatão · {moedas}":`Sell pantry to the River Trader · {moedas}`,Voltar:`Back`,"Você achou":`You found`,"Guardar e continuar":`Keep and continue`,"<strong>{ouro}</strong> moedas":`<strong>{ouro}</strong> coins`,"Cada melhoria aparece no flutuante e vale em todas as noites.":`Each upgrade shows up on the diner and lasts for every night.`,"Voltar ao cardápio":`Back to the menu`,"Contratar · {preco}":`Hire · {preco}`,"Na noite ✓":`On shift ✓`,"Pôr na noite":`Put on shift`,"Sem vaga":`No room`,"diária de {valor}":`{valor} a night`,"Com a fama {grau} ainda não cabe ajudante atrás do balcão.":`At {grau} fame, there's no room for help behind the counter yet.`,"Com a fama {grau} cabe {n} ajudante por noite.":{one:`At {grau} fame, you can have {n} helper a night.`,other:`At {grau} fame, you can have {n} helpers a night.`},"Na fama {grau} abre a primeira vaga.":{one:`At {grau} fame, the first spot opens up.`,other:`At {grau} fame, there's room for {n}.`},"A equipe":`The staff`,"O contrato se paga uma vez; a diária sai do lucro da noite.":`You pay to hire just once; wages come out of each night's profit.`,"Na noite: <b>{escalados} de {vagas}</b> · diárias de {moedas}":`On shift: <b>{escalados} of {vagas}</b> · wages {moedas}`,"Na noite: <b>{escalados} de {vagas}</b>":`On shift: <b>{escalados} of {vagas}</b>`,hoje:`today`,"dia {dia}":`day {dia}`,"De tirar o chapéu":`Hats off`,"Casa elogiada":`Well praised`,"Deu para o gasto":`Good enough`,"Noite atrapalhada":`Messy night`,"Noite para esquecer":`One to forget`,"{n} freguês foi embora sem comer":{one:`{n} customer left without eating`,other:`{n} customers left without eating`},"{n} prato foi parar na banqueta errada":{one:`{n} dish landed at the wrong seat`,other:`{n} dishes landed at the wrong seat`},"os pratos demoraram a chegar":`dishes were slow to arrive`,"As lamparinas se apagam. Seu Agenor abre o caderno só para somar o que a casa fez.":`The lamps go out. Seu Agenor opens his ledger just to add up what the house did.`,"As lamparinas se apagam. Seu Agenor abre o caderno e faz as contas da casa.":`The lamps go out. Seu Agenor opens his ledger and tallies up the night.`,"Caderno da casa":`The House Ledger`,"Caderno do Regatão":`The River Trader's Ledger`,"Noite do dia {dia}":`Night of day {dia}`,"Saiu da cozinha":`From the kitchen`,"{n} prato":{one:`{n} dish`,other:`{n} dishes`},"O mais pedido foi o <b>{prato}</b>: {fatia}% do que entrou.":`Top seller: <b>{prato}</b>, {fatia}% of the take.`,"Nenhum prato saiu hoje.":`No dishes went out tonight.`,"As últimas noites":`Recent nights`,"o que ficou em caixa":`what stayed in the till`,"A melhor noite que este caderno já viu!":`The best night this ledger has ever seen!`,"Fama no rio: <b>{grau}</b> <em>subiu!</em>":`River fame: <b>{grau}</b> <em>up!</em>`,"Fama no rio: <b>{grau}</b>":`River fame: <b>{grau}</b>`,"{ganho} nesta noite, com +{premio} pelo capricho":`{ganho} tonight, with +{premio} for good service`,"{ganho} nesta noite":`{ganho} tonight`,"faltam {faltam} para {grau}":`{faltam} more to {grau}`,"Contas da noite":`Tonight's books`,"{n} freguês servido":{one:`{n} customer served`,other:`{n} customers served`},Pratos:`Dishes`,Gorjetas:`Tips`,"Despesa da casa":`House expenses`,"Diárias da equipe":`Staff wages`,"Faltou no caixa":`Came up short`,"Ficou em caixa":`In the till`,"conceito da noite":`tonight's rating`,"{nota} de 5":`{nota} of 5`,"Ninguém saiu reclamando.":`Nobody left complaining.`,"Conferido por <b>Seu Agenor, o Regatão</b>":`Checked by <b>Seu Agenor, the River Trader</b>`,"Dormir · amanhã é dia {dia}":`Sleep · tomorrow is day {dia}`,Barco:`Boat`,Armas:`Weapons`,"Achar a mesma arma duas vezes nos caixotes libera o projeto. O material do poço fica guardado aqui, e a arma construída desce com você em todo mergulho.":`Find the same weapon twice in crates to unlock its blueprint. Materials from the pool are stored here, and a built weapon goes down with you on every dive.`,Zarabatana:`Blowgun`,"6 dardos com timbó: o peixe dorme e vem vivo":`6 timbó darts: the fish falls asleep and comes up alive`,"Espingarda de pressão":`Air gun`,"6 tiros de três chumbos, para perto":`6 three-pellet shots, for close range`,Balestra:`Crossbow`,"4 setas pesadas, que atravessam":`4 heavy bolts that pierce through`,"A noite da cheia":`The night of the flood`,"Na boca do poço mais fundo do rio há um flutuante. Seu Raimundo mergulhava, Dona Naná cozinhava, e não passava barco que não encostasse.":`At the mouth of the deepest pool on the river, there's a floating diner. Seu Raimundo dove, Dona Naná cooked, and no boat ever passed by without pulling up.`,"Tuca, o neto, voltou da cidade com uma mala e o fôlego do avô. De dia ele desce o poço. De noite, o Boca do Poço abre.":`Tuca, his grandson, came back from the city with one suitcase and his grandfather's lungs. By day, he dives the pool. By night, the Boca do Poço opens.`,"O dia tem dois mergulhos, um de manhã e um de tarde. O peixe que sobe ao barco vira o prato da noite, e cada noite bem servida paga um pedaço da dívida. O rio está esperando.":`Each day has two dives, one in the morning and one in the afternoon. The fish that comes up to the boat becomes the night's dish, and every night well served pays off a piece of the debt. The river is waiting.`,"O Tição":`Tição`,"A volta do avô":`Grandpa's return`,"Cobra-Grande":`Great Serpent`,"Escama da Cobra-Grande":`Great Serpent Scale`,Tuca:`Tuca`,"Dona Naná":`Dona Naná`,"Seu Agenor, o Regatão":`Seu Agenor, the River Trader`,Curimatã:`Curimatã`,Jaci:`Jaci`,"Seu Bené":`Seu Bené`,Piaba:`Piaba`,"Seu Raimundo":`Raimundo`,"Seu Takeshi":`Seu Takeshi`,Kauê:`Kauê`,"Dona Zefa":`Dona Zefa`,"Seu Juvenal":`Seu Juvenal`,Ingrid:`Ingrid`,Tião:`Tião`,"Seu Dico":`Seu Dico`,"Dois tucunarés":`Two peacock bass`,"Um tambaqui":`One tambaqui`,"Três piranhas":`Three piranhas`,"Dois pacus vivos":`Two live pacus`,"Uma arraia":`One stingray`,"Um poraquê":`One electric eel`,"Um pirarucu":`One pirarucu`,"Cinco jaraquis":`Five jaraquis`,"Duas matrinxãs":`Two matrinchãs`,"Três frutos da mata":`Three forest fruits`,"Dois minérios":`Two ores`,"Duas conchas":`Two shells`,Pacu:`Pacu`,Aracu:`Aracu`,"Acará-disco":`Discus`,Piranha:`Piranha`,Tucunaré:`Peacock bass`,Tambaqui:`Tambaqui`,Arraia:`Stingray`,Traíra:`Trahira`,Sucuri:`Anaconda`,Surubim:`Surubim`,Pirarara:`Redtail catfish`,Candiru:`Candiru`,Poraquê:`Electric eel`,"Peixe-cachorro":`Payara`,Pirarucu:`Pirarucu`,Jaú:`Jaú`,Piraíba:`Piraíba`,Aruanã:`Arowana`,Jaraqui:`Jaraqui`,Matrinxã:`Matrinchã`,Tamuatá:`Tamuatá catfish`,"Peixe-boi":`Manatee`,Acari:`Acari pleco`,Mandi:`Mandi catfish`,Ituí:`Ituí knifefish`,Jacaré:`Caiman`,"A volta":`The Return`,"Tu cresceu, menino. E voltou magro. Senta, que conversa de barriga vazia não presta.":`Look how you've grown, boy. And you came back skinny. Sit down, no good talk ever happened on an empty stomach.`,"Vó, que caderno é esse em cima do balcão?":`Grandma, what's that notebook on the counter?`,"É do Seu Agenor, o Regatão. Teu avô comprou fiado nele a vida toda. Agora ele diz que a conta é do tamanho do flutuante.":`It's Seu Agenor's, the River Trader. Your grandpa bought on credit from him his whole life. Now he says the tab is as big as the diner.`,"Do tamanho do flutuante e mais a canoa, Dona Naná. Mas eu sou homem de paciência: pagando a parcela, eu espero.":`As big as the diner, plus the canoe, Dona Naná. But I'm a patient man: keep up the payments and I'll wait.`,"Então a gente paga. Eu trago o peixe do poço, a senhora cozinha.":`Then we'll pay. I'll bring the fish up from the pool, and you'll cook.`,"Teu avô dizia a mesma coisa, com essa mesma cara. Anda, abre a casa.":`Your grandpa used to say the same thing, with that same face. Go on, open up.`,"O arpão do avô":`Grandpa's Harpoon`,"Primeira parcela, contadinha. Quem diria: o balcão voltou a encher.":`First payment, every coin counted. Who'd have thought: the counter's filling up again.`,"Anota aí que pagou, Agenor. De caneta, que lápis teu apaga sozinho.":`Write down that we paid, Agenor. In pen. Your pencil has a way of erasing itself.`,"Tuca, teu avô perdeu o arpão dele no raso, na última cheia. Ele amarrava as receitas no cabo, para não molhar na canoa.":`Tuca, your grandpa lost his harpoon in the shallows during the last flood. He tied his recipes to the shaft so they wouldn't get wet in the canoe.`,"Receita amarrada em arpão?":`Recipes tied to a harpoon?`,"Ele pescava pensando no prato. Se tu achar, traz. Tem coisa naquele caderno que nem eu sei fazer.":`He fished with the dish in mind. If you find it, bring it back. There's stuff in that notebook even I don't know how to make.`,"O arpão do avô está em algum canto do raso, fincado no chão.":`Grandpa's harpoon is stuck in the riverbed somewhere in the shallows.`,"Arraia não se pesca com pressa nem se cozinha com pressa. Leite de coco, coentro do quintal e fogo baixo. Naná diz que não gosta. Naná repete o prato.":`You don't rush catching a stingray, and you don't rush cooking one. Coconut milk, cilantro from the yard, and a low flame. Naná says she doesn't like it. Naná always goes back for seconds.`,"Receita nova no Boca do Poço: moqueca de arraia. As arraias que você pescar agora vão para a despensa.":`New recipe at the Boca do Poço: stingray moqueca. Any stingrays you catch now go to the pantry.`,"As luzes do fundo":`The lights below`,"Parcela paga, Dona Naná. Casa cheia, caderno em dia: assim que eu gosto.":`Installment paid, Dona Naná. Full house, ledger up to date: just how I like it.`,"Anota e vai embora, Agenor.":`Write it down and go, Agenor.`,"Já vou. Só um aviso de amigo: subiu uma draga pelo rio. Gente de fora, gente de dinheiro. Andam perguntando do poço.":`I'm going. Just a friendly warning: a dredge came up the river. Outsiders, people with money. They've been asking about the pool.`,"Perguntando o quê?":`Asking what?`,"Quanto ele tem de fundo. E de quem é este flutuante.":`How deep it goes. And who owns this floating house.`,"Teu avô descia de madrugada, sabia? Depois de fechar a casa. Levava a lamparina e dizia que, no escuro, o fundo do poço acendia.":`Your grandpa used to dive before dawn, did you know? After closing up. He took his oil lamp and said that, in the dark, the bottom of the pool lit up.`,"Eu achava que era cachaça. Na noite da cheia ele desceu com ela e não voltou.":`I thought it was the cachaça talking. On the night of the flood he went down with it and never came back.`,"Então hoje, quando a casa fechar, eu desço.":`Then tonight, when we close, I'm going down.`,"Leva o casaco. E volta, que eu não tenho mais idade para esperar ninguém na beira.":`Take your coat. And come back: I'm too old to wait for anyone on the shore again.`,"A lamparina do avô":`Grandpa's oil lamp`,"A lamparina do avô está no fundo, onde ele descia de madrugada.":`Grandpa's oil lamp lies at the bottom, where he used to dive before dawn.`,"Eles cantam lá embaixo, Naná. Tu não acredita, mas eu vi as luzes. O jacaré velho fugiu do igarapé: a draga revirou o fundo de lá e ele veio parar no nosso poço, com raiva. A draga vem vindo. Hoje eu desço para avisar os do fundo. Se eu demorar, guarda a brasa acesa.":`They sing down there, Naná. You don't believe me, but I saw the lights. The old caiman fled the creek: the dredge tore up the bottom there and he ended up in our pool, angry. The dredge is coming. Tonight I'm going down to warn the ones below. If I'm late, keep the embers burning.`,"A lamparina agora é tua: a lanterna alcança mais longe. E no caderno, duas receitas novas: acari assado e caldo de mandi.":`The lamp is yours now: your flashlight reaches farther. And in the notebook, two new recipes: roasted acari and mandi broth.`,"O homem da draga":`The dredge man`,"Dona Naná, trouxe uma visita. Gente importante, de fora.":`Dona Naná, I brought a visitor. An important man, from out of town.`,"Doutor Brandão, minha senhora. Bonito o seu flutuante. Bem na boca do poço.":`Doctor Brandão, ma'am. Lovely floating house you have. Right at the mouth of the pool.`,"Se veio comer, senta. Se veio olhar, a vista é de graça.":`If you came to eat, sit down. If you came to look, the view is free.`,"Vim fazer negócio. Pago o dobro da dívida, à vista. A senhora descansa e eu ancoro a minha draga aqui.":`I came to do business. I'll pay double the debt, in cash. You get to rest, and I anchor my dredge here.`,"Este flutuante não está à venda. Nem pelo dobro, nem pelo triplo.":`This floating house is not for sale. Not for double, not for triple.`,"Tudo no rio tem preço, minha senhora. Às vezes quem cobra é o rio.":`Everything on the river has a price, ma'am. Sometimes it's the river that collects.`,"Vó, de madrugada tem um jacaré enorme rondando a tona. Os olhos parecem brasa.":`Grandma, before dawn there's a huge caiman prowling near the surface. Its eyes look like embers.`,"É o Tição. Teu avô falava dele. Desce com a faca na mão, menino.":`That's Tição. Your grandpa used to talk about him. Go down with your knife in hand, boy.`,"A faca do avô":`Grandpa's knife`,"A faca do avô ficou no meio do poço, onde ele brigou com o Tição.":`Grandpa's knife lies in the middle of the pool, where he fought Tição.`,'Riscado no cabo, com a ponta da própria faca: "O Tição veio da draga. Bati nele três vezes e ele não largou. Se tu achar esta faca, Tuca, é tua. Não vai atrás dele: deixa ele vir, e bate na hora do bote."':`Scratched into the handle with the tip of the knife itself: "Tição came with the dredge. I hit him three times and he wouldn't let go. If you find this knife, Tuca, it's yours. Don't go after him: let him come, and strike when he lunges."`,"A faca do avô é tua: o rebate fica mais fácil e o golpe, mais forte.":`Grandpa's knife is yours: parrying gets easier and your strikes hit harder.`,"A porta":`The door`,"Dona Naná... preciso contar uma coisa antes que a senhora saiba por outro.":`Dona Naná... I need to tell you something before you hear it from someone else.`,"Fala, Agenor. Mas fala de pé, que sentado tu mente melhor.":`Talk, Agenor. But standing up: you lie better sitting down.`,"Eu vendi a dívida do Raimundo para o Doutor Brandão. Ele quer o poço. A draga desce na próxima cheia.":`I sold Raimundo's debt to Doctor Brandão. He wants the pool. The dredge comes down with the next flood.`,"O senhor vendeu a gente.":`You sold us out.`,"Vendi papel. Achei que era só papel. O Raimundo dizia que no fundo tinha uma porta, e eu ri dele.":`I sold paper. I thought it was just paper. Raimundo used to say there was a door down below, and I laughed at him.`,"Sai do meu balcão, Agenor. A despensa tu ainda compra, que eu não sou boba. Mas cafezinho aqui tu não toma mais.":`Get away from my counter, Agenor. You can still buy the pantry, I'm no fool. But you'll never drink coffee here again.`,"Uma porta no fundo do poço, vó?":`A door at the bottom of the pool, Grandma?`,"Teu avô usava uma pedra verde no pescoço, um sapinho. Dizia que era a chave. Sumiu no dia da cheia, junto com ele.":`Your grandpa wore a green stone around his neck, a little frog. He said it was the key. It vanished on the day of the flood, along with him.`,"O muiraquitã do avô":`Grandpa's muiraquitã`,"O muiraquitã do avô está no fundo mais fundo, onde só se chega de madrugada.":`Grandpa's muiraquitã lies in the deepest depths, reachable only before dawn.`,'Amarrado no cordão do muiraquitã, um papel dobrado: "A Cobra-Grande guarda o caminho e não deixa a draga passar. A porta abre para quem leva o sapinho. Se a draga descer, os do fundo vão lutar. Eu vou com eles."':`Tied to the muiraquitã cord, a folded note: "The Great Serpent guards the way and won't let the dredge through. The door opens for whoever carries the little frog. If the dredge comes down, the ones below will fight. I'm going with them."`,"O muiraquitã é teu. No fundo, a porta dos encantados já te espera.":`The muiraquitã is yours. Down below, the door of the enchanted ones is waiting for you.`,"A cheia":`The flood`,"O rio subiu dois palmos desde ontem. A cheia chegou.":`The river rose two hands since yesterday. The flood is here.`,"Recado do Doutor Brandão: a draga desce amanhã. Quem estiver no caminho, que saia.":`A message from Doctor Brandão: the dredge comes down tomorrow. Whoever's in the way had better move.`,"Hoje de madrugada eu abro a porta, vó. O Tição vai estar lá.":`Tonight before dawn I'm opening the door, Grandma. Tição will be there.`,"Teu avô disse a mesma coisa, nesta mesma noite. Volta, Tuca. Volta com ele.":`Your grandpa said the same thing, on this very night. Come back, Tuca. Come back with him.`,"Tuca! Tem um homem subindo a escada do flutuante. Molhado, de barba branca.":`Tuca! There's a man climbing the ladder of the floating house. Soaking wet, with a white beard.`,"Naná. A brasa ainda está acesa?":`Naná. Are the embers still burning?`,"Nunca apagou, velho teimoso. Nunca.":`They never went out, you stubborn old man. Never.`,"Os do fundo me guardaram até alguém abrir a porta. Não imaginei que ia ser o menino.":`The ones below kept me safe until someone opened the door. I never imagined it would be the boy.`,"A draga afundou, vô. O Tição não volta.":`The dredge sank, Grandpa. Tição isn't coming back.`,"E o Doutor Brandão sumiu rio abaixo. Com ele, o contrato. A dívida... a dívida não existe mais.":`And Doctor Brandão vanished downriver. The contract went with him. The debt... the debt is gone.`,"Então senta, Raimundo. E tu também, Agenor. Hoje o cafezinho é por conta da casa.":`Then sit down, Raimundo. You too, Agenor. Tonight the coffee's on the house.`,"Doutor Brandão":`Doctor Brandão`,"Cilindro de ar":`Air cylinder`,"Caixa de munição":`Ammo box`,"Anel de ouro":`Gold ring`,Muiraquitã:`Muiraquitã`,"Baú perdido":`Lost chest`,"Cuia de prata":`Silver gourd bowl`,"Brinco de esmeralda":`Emerald earring`,"Garrafa antiga":`Old bottle`,"Moeda antiga":`Old coin`,"Pérola de rio":`River pearl`,Diamante:`Diamond`,Opala:`Opal`,Ametista:`Amethyst`,Estanho:`Tin`,Ferro:`Iron`,Cobre:`Copper`,"Cacho de açaí":`Açaí bunch`,"Ouriço de castanha":`Brazil nut pod`,"Concha de mexilhão":`Mussel shell`,"Casca de caramujo":`Snail shell`,"Fragmento de arpão":`Harpoon fragment`,Sucata:`Scrap metal`,"Caco de vidro":`Glass shard`,Corda:`Rope`,Madeira:`Wood`,"Tanque de ar":`Air tank`,"Mais ar para ficar mais tempo lá embaixo.":`More air to stay down there longer.`,"de ar":`air`,Traje:`Suit`,"Aguenta a pressão até mais fundo. Passou do limite, o ar acaba bem mais rápido.":`Handles the pressure deeper down. Past the limit, air runs out much faster.`,m:`m`,Samburá:`Fish basket`,"Cabe mais peixe e mais achado antes de pesar.":`Holds more fish and finds before it gets too heavy.`,kg:`kg`,"Tiro mais forte: peixe resistente vem com menos disparos.":`Stronger shots: tough fish go down in fewer hits.`,"de dano":`damage`,"Golpe mais forte, para o que chega perto demais.":`A stronger stab, for whatever gets too close.`,Tarrafa:`Cast net`,"Mais lances de rede por mergulho. Peixe de tarrafa vem vivo e vale mais.":`More net casts per dive. Net-caught fish come up alive and are worth more.`,lances:`casts`,"Boia de resgate":`Rescue buoy`,"Leva o peixe grande direto para o barco, sem pesar no samburá.":`Sends a big fish straight to the boat without weighing down your basket.`,"por mergulho":`per dive`,"Ponta de aço":`Steel tip`,"+1 de dano":`+1 damage`,"Ponta farpada":`Barbed tip`,"não solta: aperte Espaço na hora certa":`holds fast: press Space at the right moment`,"Ponta elétrica":`Electric tip`,"+1 de dano · atordoa o peixe · alterne A e D":`+1 damage · stuns the fish · alternate A and D`,"Ponta de timbó":`Timbó tip`,"adormece o peixe: ele vem vivo · siga as setas":`puts the fish to sleep: it comes up alive · follow the arrows`,"Ponta de curare":`Curare tip`,"veneno: tira vida aos poucos · aperte bem rápido":`poison: drains health over time · mash fast`,"O que tem de bom hoje?":`What's good today?`,"Estou varado de fome...":`I'm starving...`,"Hum, que cheiro!":`Mmm, smells great!`,"Capricha aí!":`Make it a good one!`,"Isso é que é comida!":`Now that's food!`,"Hum... que beleza.":`Mmm... beautiful.`,"Égua, que tá bom demais!":`Man, this is so good!`,"Cheirou, chegou!":`Smelled it, came running!`,"Ô garçom!":`Hey, waiter!`,"Vai demorar?":`Gonna be long?`,"Esqueceram de mim?":`Forget about me?`,"Faz tempo que eu não comia um {prato} assim. Volto amanhã e trago a família.":`Haven't had {prato} like this in ages. I'll be back tomorrow with the family.`,"Mal sentei e o prato já estava na minha frente. Isso é que é casa bem tocada!":`I'd barely sat down and the dish was already in front of me. Now that's a well-run place!`,"O {prato} da Dona Naná continua o melhor deste rio. Podem escrever.":`Dona Naná's {prato} is still the best on this river. Mark my words.`,"Vim de longe só pelo {prato}. Valeu cada remada.":`Came a long way just for the {prato}. Worth every paddle stroke.`,"A comida é boa, mas hoje a espera foi comprida.":`The food's good, but the wait was long tonight.`,"Gostei do {prato}. Só achei o balcão meio atrapalhado.":`Liked the {prato}. The counter was a bit of a mess, though.`,"Dá para voltar. Com mais ligeireza no serviço, eu voltava toda noite.":`I'd come back. With quicker service, I'd come every night.`,"Esperei, esperei e fui embora de barriga vazia. Assim não dá.":`I waited and waited and left on an empty stomach. That won't do.`,"Vi gente levantando sem comer. A casa precisa de mais braço no balcão.":`Saw folks get up without eating. This place needs more hands at the counter.`,"Me trouxeram o prato do vizinho. Hoje não foi a noite de vocês.":`They brought me my neighbor's dish. Not your night, folks.`,"Calado e atento: limpa a banqueta antes de você notar que sujou.":`Quiet and sharp: wipes the seat before you notice it's dirty.`,"Soca o pilão cantando: a farinha não acaba mais.":`Sings while pounding the mortar: the flour never runs out.`,"Devagar e certeiro: nunca erra a marca da cuia.":`Slow and steady: never misses the line on the bowl.`,"Ligeira no balcão: pega o prato pronto e leva a quem pediu.":`Quick at the counter: grabs the ready dish and takes it to whoever ordered.`,"Fogão de duas bocas":`Two-burner stove`,"A cozinha prepara cada prato mais rápido.":`The kitchen cooks each dish faster.`,"s por prato":`s per dish`,"Banquetas estofadas":`Padded stools`,"Sentado no macio, o freguês espera mais antes de desistir.":`On a comfy seat, customers wait longer before giving up.`,"s de paciência":`s of patience`,"Pilão grande":`Big mortar`,"Cabe mais farinha antes de precisar socar de novo.":`Holds more flour before you need to pound again.`,"de farinha":`flour`,"Lamparinas e flores":`Lamps and flowers`,"Casa bonita: mais fregueses deixam gorjeta.":`A pretty place: more customers leave tips.`,"% dão gorjeta":`% tip`,"Placa iluminada":`Lit-up sign`,"A casa se vê de longe: vêm mais fregueses por noite.":`Seen from afar: more customers come each night.`,"fregueses a mais":`extra customers`,Cafezinho:`Coffee`,"Costela de tambaqui":`Tambaqui ribs`,"Filé de tucunaré":`Peacock bass fillet`,"Ventrecha de pirarucu":`Pirarucu belly`,Rabeta:`Longtail`,Voadeira:`Speedboat`,Batelão:`Barge`,Recreio:`Riverboat`,Gaiola:`Steamboat`,"Peixe frito":`Fried fish`,"Caldo de piranha":`Piranha broth`,"Tucunaré na brasa":`Grilled peacock bass`,"Tambaqui assado":`Roasted tambaqui`,Caldeirada:`Caldeirada`,"Pirarucu de casaca":`Pirarucu de casaca`,"Aruanã assada na folha":`Leaf-roasted arowana`,"Moqueca de arraia":`Stingray moqueca`,"Acari assado":`Roasted acari`,"Caldo de mandi":`Mandi broth`,"Costela de tambaqui assada":`Roasted tambaqui ribs`,"Filé de tucunaré no tucupi":`Peacock bass fillet in tucupi`},r={"Na boca do poço mais fundo do rio tem um flutuante. É o Boca do Poço, a nossa casa e o nosso restaurante.":`En la boca del pozo más hondo del río hay un restaurante flotante. Es el Boca do Poço, nuestra casa y nuestro restaurante.`,"O meu Raimundo mergulhava e trazia o peixe. Eu cozinhava. De noite, não passava barco que não encostasse.":`Mi Raimundo se zambullía y traía el pescado. Yo cocinaba. De noche, no pasaba barco que no se arrimara.`,"Ele dizia que, de madrugada, o fundo do poço acendia. Eu achava que era conversa de pescador.":`Decía que, de madrugada, el fondo del pozo se encendía. Yo pensaba que eran cuentos de pescador.`,"Numa noite de cheia, ele desceu com a lamparina e não voltou.":`Una noche de crecida, bajó con el farol y no volvió.`,"Ficaram a brasa acesa, o balcão vazio e uma dívida no caderno do Seu Agenor, o Regatão. Do tamanho do flutuante.":`Quedaron las brasas encendidas, la barra vacía y una deuda en la libreta de Seu Agenor, el mercader del río. Tan grande como el restaurante flotante.`,"Foi aí que o Tuca, nosso neto, voltou da cidade. Veio me ajudar a tocar o restaurante.":`Fue entonces cuando Tuca, nuestro nieto, volvió de la ciudad. Vino a ayudarme a sacar adelante el restaurante.`,"Sem peixe não tem prato. Então, todo dia, ele desce o poço e traz o pescado. De noite, eu cozinho e ele serve. Cada noite boa paga um pedaço da dívida.":`Sin pescado no hay plato. Así que, todos los días, baja al pozo y trae la pesca. De noche, yo cocino y él sirve. Cada buena noche paga un pedazo de la deuda.`,"E lá embaixo, o rio ainda guarda o que aconteceu com o Raimundo.":`Y allá abajo, el río todavía guarda lo que le pasó a Raimundo.`,"Saco de urucum":`Saco de urucum`,"Chamariz de pano":`Señuelo de tela`,"Rondando você":`Te está rondando`,"Vai dar o bote: rebata com a faca!":`Va a embestir: ¡desvía con el cuchillo!`,"Rebata agora!":`¡Desvía ahora!`,"Tonto: arpão e faca agora!":`Aturdido: ¡arpón y cuchillo ahora!`,"Ela está acordando…":`Está despertando…`,"Vai dar o bote: saia da frente!":`Va a atacar: ¡apártate!`,"Saia da frente!":`¡Apártate!`,"Boca aberta: atire agora!":`Boca abierta: ¡dispara ya!`,"Cuidado com a cauda!":`¡Cuidado con la cola!`,"Ela desistiu de você":`Te dejó en paz`,"Amanheceu: dia {dia}":`Amaneció: día {dia}`,"A tarde chegou":`Llegó la tarde`,"Anoiteceu: o Boca do Poço pode abrir":`Anocheció: el Boca do Poço puede abrir`,"Peixe forte! Aperte espaço (ou clique) bem rápido para cansá-lo.":`¡Pez fuerte! Pulsa espacio (o haz clic) muy rápido para cansarlo.`,"Peixe forte! Alterne A e D bem rápido.":`¡Pez fuerte! Alterna A y D muy rápido.`,"Peixe forte! Aperte as setas na ordem, antes que o tempo acabe.":`¡Pez fuerte! Pulsa las flechas en orden antes de que se acabe el tiempo.`,"Peixe forte! Aperte espaço quando o marcador passar no verde.":`¡Pez fuerte! Pulsa espacio cuando el marcador pase por el verde.`,"Levar o barco até o Boca do Poço, que abre agora.":`Llevar el barco al Boca do Poço, que abre ya.`,"na escada":`en la escalera`,"Levar o barco pelo rio. O Boca do Poço abre à noite.":`Llevar el barco por el río. El Boca do Poço abre de noche.`,"no leme":`en el timón`,"Melhorar o tanque, o traje, a carga e as armas.":`Mejorar el tanque, el traje, la carga y las armas.`,"na bancada":`en el taller`,"Deixar o turno passar sem mergulhar.":`Dejar pasar el turno sin bucear.`,"no banco da proa":`en el banco de proa`,"Antes do primeiro mergulho":`Antes de la primera inmersión`,"De volta ao barco":`De vuelta al barco`,"Barco ancorado no igapó. O mergulho daqui é entre as árvores.":`Barco anclado en el igapó. Desde aquí se bucea entre los árboles.`,"Barco ancorado no poço.":`Barco anclado en el pozo.`,"{destino}: {motivo}":`{destino}: {motivo}`,"{destino} · {rotulo}":`{destino} · {rotulo}`,Final:`Final`,"Capítulo {numero}":`Capítulo {numero}`,"Abrir o cardápio":`Abrir el menú`,"{escalados} de {vagas} na noite":`{escalados} de {vagas} esta noche`,limpeza:`limpieza`,pilão:`pilón`,tacacá:`tacacá`,"serve os pratos":`sirve los platos`,"Um freguês":`Un cliente`,"Primeira noite":`Primera noche`,"Primeira noite · {numero} de {total}":`Primera noche · {numero} de {total}`,"Cansei de esperar!":`¡Me cansé de esperar!`,"Um freguês cansou de esperar e foi embora":`Un cliente se cansó de esperar y se fue`,"{prato} acabou":`Se acabó: {prato}`,"Um prato":`Un plato`,"Tacacá na marca: ele paga 30% a mais":`Tacacá justo en la marca: paga un 30% más`,"Passou da marca: derramou o tacacá":`Te pasaste de la marca: se derramó el tacacá`,"Faltou tacacá na cuia":`Faltó tacacá en la jícara`,"Acabou a farinha: a cozinha parou. Soque o pilão!":`Se acabó la harina: la cocina paró. ¡Dale al pilón!`,"Um peixe-boi! Ele deixou você chegar perto. Presente do igapó: {ouro} moedas.":`¡Un manatí! Te dejó acercarte. Regalo del igapó: {ouro} monedas.`,"Encomenda do flutuante: {encomendas}":`Encargo del restaurante: {encomendas}`,"A porta dos encantados te espera no fundo. O Tição também.":`La puerta de los encantados te espera en el fondo. El Tizón también.`,"Tutorial concluído. Agora abra o Boca do Poço e sirva o que pescou!":`Tutorial completado. ¡Ahora abre el Boca do Poço y sirve lo que pescaste!`,"Primeiro mergulho · {numero} de {total}":`Primer buceo · {numero} de {total}`,"Carga cheia! Volte ao barco.":`¡Carga llena! Vuelve al barco.`,"Encomenda cumprida: {encomenda} (+{premio})":`Encargo cumplido: {encomenda} (+{premio})`,"Soltou {nome}":`Soltado: {nome}`,"Espécie nova! {peixe}":`¡Especie nueva! {peixe}`,"Espécie nova no caderno: {peixe} · +{moedas} moedas":`Especie nueva en el cuaderno: {peixe} · +{moedas} monedas`,"Abatido!":`¡Abatido!`,"Falta {n}":{one:`Falta {n}`,many:`Faltan {n}`,other:`Faltan {n}`},"Rebateu!":`¡Rechazado!`,"O Tição está tonto: agora o arpão e a faca ferem!":`El Tizón está aturdido: ¡ahora el arpón y el cuchillo lo hieren!`,"A porta dos encantados":`La puerta de los encantados`,"O Tição afunda na escuridão e não volta. A porta se abre devagar, e a água do fundo acende como o avô dizia: luzes que cantam. Lá em cima, um estrondo: a draga do Doutor Brandão adernou e foi ao fundo, longe do poço. Uma voz conhecida chama o teu nome.":`El Tizón se hunde en la oscuridad y no vuelve. La puerta se abre despacio, y el agua del fondo se enciende como decía el abuelo: luces que cantan. Allá arriba, un estruendo: la draga del Doctor Brandão escoró y se fue al fondo, lejos del pozo. Una voz conocida dice tu nombre.`,"Presente dos encantados: {ouro} moedas. Volte ao balcão: tem alguém esperando.":`Regalo de los encantados: {ouro} monedas. Vuelve al mostrador: alguien te espera.`,"Boia de resgate: {peixe} {marca} a caminho do barco":`Boya de rescate: {peixe} {marca} va al barco`,"{peixe} {marca} · {peso} kg":`{peixe} {marca} · {peso} kg`,"Este {peixe} está doente: Dona Naná não vai cozinhar.":`Este {peixe} está enfermo: Doña Naná no lo va a cocinar.`,"O couro do jacaré não fura. Só o rebate de faca o afasta.":`El cuero del yacaré no se perfora. Solo el contraataque con el cuchillo lo aleja.`,"O couro dela não fura. Espere o bote: cansada, ela abre a boca.":`Su piel no se perfora. Espera su ataque: cansada, abre la boca.`,"A Cobra-Grande se recolheu e deixou uma escama: +{valor}":`La Gran Serpiente se retiró y dejó una escama: +{valor}`,"Uma posta de {peixe} · +{valor}":{one:`Una rodaja de {peixe} · +{valor}`,many:`{n} rodajas de {peixe} · +{valor}`,other:`{n} rodajas de {peixe} · +{valor}`},"Tanque cheio: o cilindro fica aí para quando faltar ar.":`Tanque lleno: el cilindro se queda ahí para cuando falte aire.`,"+{ar} de ar":`+{ar} de aire`,"Já leva {caixas} caixas de munição guardadas: esta fica para depois.":`Ya llevas {caixas} cajas de munición guardadas: esta queda para después.`,"{arma}: +{tiros} de munição":`{arma}: +{tiros} de munición`,"+{tiros} munição":`+{tiros} munición`,"Caixa de munição guardada ({caixas}): entra quando a arma esvaziar.":`Caja de munición guardada ({caixas}): entra cuando el arma se vacíe.`,"Caixa de munição guardada ({caixas}): serve para a arma que você achar num caixote.":`Caja de munición guardada ({caixas}): sirve para el arma que encuentres en un cajón.`,"Caixa guardada":`Caja guardada`,"{item} para o barco":`{item} al barco`,"Peças de {arma} para o Barco (+1)":`Piezas de {arma} para el Barco (+1)`,"Projeto liberado: {arma}. Dá para construir no Barco.":`Plano desbloqueado: {arma}. Puedes construirla en el Barco.`,"{apetrecho} no cinto · {tecla} para usar":`{apetrecho} en el cinturón · {tecla} para usar`,"Tarrafa: +{lances} lances":`Atarraya: +{lances} lances`,"+{lances} lances":`+{lances} lances`,"Punhado de moedas":`Puñado de monedas`,"Moedas +{valor}":`Monedas +{valor}`,"Boia de resgate: leva um peixe grande direto para o barco":`Boya de rescate: lleva un pez grande directo al barco`,"+1 boia":`+1 boya`,"Nuvem de urucum: os bichos perderam você de vista":`Nube de urucum: los bichos te perdieron de vista`,"Chamariz solto: os bichos vão atrás dele":`Señuelo suelto: los bichos van tras él`,"O Tição levou {peixe} da sua carga!":`¡El Tizón se llevó tu {peixe} de la carga!`,"{bicho} enrolou você! Aperte espaço bem rápido para se soltar.":`¡{bicho} te enroscó! Pulsa espacio muy rápido para soltarte.`,"{bicho} investiu!":`¡{bicho} embistió!`,"O veneno derrubou o peixe: ele fica boiando e vale 1 estrela.":`El veneno tumbó al pez: queda flotando y vale 1 estrella.`,"{bicho} bateu na pedra e ficou tonta!":`¡{bicho} chocó con la roca y quedó aturdida!`,"Ferroada de arraia!":`¡Picadura de raya!`,"A Cobra-Grande acordou!":`¡La Gran Serpiente despertó!`,"O bote da Cobra-Grande pegou você!":`¡El ataque de la Gran Serpiente te alcanzó!`,"A cauda dela pegou você!":`¡Su cola te alcanzó!`,"Ela cansou e abriu a boca: atire na cabeça agora!":`Se cansó y abrió la boca: ¡dispara a la cabeza ya!`,"A Cobra-Grande voltou a dormir. O que ela perdeu de vida, continua perdido.":`La Gran Serpiente volvió a dormir. La vida que perdió sigue perdida.`,"O Tição saiu da porta!":`¡El Tizón salió de la puerta!`,"O bote do Tição pegou você!":`¡La embestida del Tizón te alcanzó!`,"O Tição voltou para a porta. O que ele perdeu de vida, continua perdido.":`El Tizón volvió a la puerta. La vida que perdió, perdida está.`,"O boto achou um caixote: vá atrás dele!":`El bufeo encontró un cajón: ¡síguelo!`,"Dormiu!":`¡Dormido!`,"Peixe grande demais para a linha: chegue perto para mandá-lo de boia ao barco.":`Pez demasiado grande para la línea: acércate para mandarlo en boya al barco.`,"Peixe grande demais para a linha: chegue perto para recolher.":`Pez demasiado grande para la línea: acércate para recogerlo.`,"Fisgou!":`¡Enganchado!`,"Atordoado!":`¡Aturdido!`,Envenenado:`Envenenado`,"Cansou!":`¡Cansado!`,"A linha cedeu — o peixe escapou!":`La línea cedió — ¡el pez escapó!`,"Você se soltou!":`¡Te soltaste!`,"{bicho} cansou e soltou você.":`{bicho} se cansó y te soltó.`,"{arma}: a caixa guardada entrou, +{tiros} de munição":`{arma}: entró la caja guardada, +{tiros} de munición`,"{arma} sem munição: ficou para trás.":`{arma} sin munición: se quedó atrás.`,"Adormecido, o peixe fica parado: chegue perto para recolher. Vem vivo, com 3 estrelas.":`Dormido, el pez se queda quieto: acércate para recogerlo. Llega vivo, con 3 estrellas.`,"Grogue! Mais um dardo":`¡Grogui! Un dardo más`,"Abatido a tiro, o peixe fica boiando: chegue perto para recolher. Vale 1 estrela.":`Abatido a tiros, el pez queda flotando: acércate para recogerlo. Vale 1 estrella.`,"{presos} na rede!":`¡{presos} en la red!`,"Forte demais para a tarrafa: esse é no arpão.":`Demasiado fuerte para la atarraya: este va con arpón.`,Zzz:`Zzz`,"Choque do poraquê!":`¡Descarga eléctrica!`,"Bolsão de ar: tanque cheio":`Bolsa de aire: tanque lleno`,"Tem alguma coisa brilhando no chão, aqui perto.":`Hay algo brillando en el fondo, aquí cerca.`,Tição:`Tizón`,"Pouco ar! Volte ao barco.":`¡Poco aire! Vuelve al barco.`,"Fundo demais para este traje ({limite} m): o ar acaba {fator}× mais rápido. No barco tem um melhor.":`Demasiado hondo para este traje ({limite} m): el aire se gasta {fator}× más rápido. En el barco hay uno mejor.`,"Subir no barco":`Subir al barco`,"Subir pela boia":`Subir por la boya`,"Abrir o caixote":`Abrir el cajón`,"Arrancar o minério com a faca":`Arrancar el mineral con el cuchillo`,"Tirar postas com a faca":`Cortar rodajas con el cuchillo`,"Boca do Poço":`Boca do Poço`,"PEIXE NA BRASA  •  TACACÁ":`PESCADO A LA BRASA  •  TACACÁ`,HOJE:`HOY`,"peixe fresco":`pescado fresco`,"{nome} (doente)":`{nome} (enfermo)`,"Posta de {peixe}":`Rodaja de {peixe}`,Leme:`Timón`,Bancada:`Taller`,Escada:`Escalera`,"Banco da proa":`Banco de proa`,"Mapa do rio":`Mapa del río`,Equipamento:`Equipamiento`,"Descer de madrugada":`Bajar de madrugada`,Mergulhar:`Bucear`,"O rio descansa à noite":`El río descansa de noche`,"Dormir sem abrir a casa":`Dormir sin abrir la casa`,"Dormir até de manhã":`Dormir hasta la mañana`,"Descansar até a tarde":`Descansar hasta la tarde`,"Descansar até a noite":`Descansar hasta la noche`,Madrugada:`Madrugada`,Manhã:`Mañana`,Tarde:`Tarde`,Noite:`Noche`,"Pasta devagar entre as raízes do igapó. Deixou o Tuca chegar perto e não teve medo.":`Pasta despacio entre las raíces del igapó. Dejó que Tuca se acercara y no tuvo miedo.`,peixe:`pescado`,"Descer ao igapó e pescar. Gasta este turno.":`Bajar al igapó a pescar. Gasta este turno.`,"Madrugada do dia {dia}: o igapó está escuro":`Madrugada del día {dia}: el igapó está oscuro`,Galhada:`Ramaje`,"Ar preso entre as raízes: entre nele para encher o tanque.":`Aire atrapado entre las raíces: entra en él para llenar el tanque.`,"Você no igapó · barco no alto · pontos claros: bolsões de ar":`Tú en el igapó · barco arriba · puntos claros: bolsas de aire`,"Descer ao poço e pescar. Gasta este turno.":`Bajar al pozo a pescar. Gasta este turno.`,"Madrugada do dia {dia}: o poço está escuro":`Madrugada del día {dia}: el pozo está oscuro`,Paredões:`Paredones`,"Ar preso no teto da gruta: entre nele para encher o tanque.":`Aire atrapado en el techo de la gruta: entra en él para llenar el tanque.`,"Você no poço · barco no alto · pontos claros: bolsões de ar":`Tú en el pozo · barco arriba · puntos claros: bolsas de aire`,"Poço do Raimundo":`Pozo de Raimundo`,Igapó:`Igapó (bosque inundado)`,"Voltar ao convés":`Volver a cubierta`,"Ancorar no poço":`Anclar en el pozo`,"Ancorar no igapó":`Anclar en el igapó`,"Abrir o Boca do Poço":`Abrir el Boca do Poço`,"Abre à noite":`Abre de noche`,"Nade para o fundo":`Nada hacia el fondo`,"Desça alguns metros. Segure Shift para arrancar, mas gasta mais ar.":`Baja unos metros. Mantén Shift para acelerar, pero gasta más aire.`,"O ar é a sua vida":`El aire es tu vida`,"Este medidor é o ar do tanque. Ele cai com o tempo, mais rápido no fundo e a cada ferida.":`Este medidor es el aire del tanque. Baja con el tiempo, más rápido en lo profundo y con cada herida.`,"Se o ar acabar, você desmaia, é puxado de volta ao barco e perde metade do pescado. Volte antes!":`Si se acaba el aire, te desmayas, te suben de vuelta al barco y pierdes la mitad de la pesca. ¡Vuelve antes!`,"Pesque um peixe":`Pesca un pez`,Mouse:`Ratón`,"Segure o botão do mouse para mirar e solte para atirar. Peixe forte: aperte Espaço para cansá-lo.":`Mantén el botón del ratón para apuntar y suéltalo para disparar. Pez fuerte: pulsa Espacio para cansarlo.`,"O peso da carga":`El peso de la carga`,"A barra mostra o peso que você leva e o máximo que aguenta. Cheia, não cabe mais nada.":`La barra muestra el peso que llevas y el máximo que aguantas. Llena, ya no cabe nada más.`,"Aperte C para ver a carga e solte o peixe que vale menos. Na bancada do barco dá para aumentar a capacidade.":`Pulsa C para ver la carga y suelta el pez que menos vale. En el taller del barco puedes aumentar la capacidad.`,"Abra e pegue com a faca":`Abre y recoge con el cuchillo`,"Perto de um caixote, de uma caixa ou de um achado, aperte F.":`Cerca de un cajón, una caja o un hallazgo, pulsa F.`,"Volte ao barco":`Vuelve al barco`,"Suba até o barco (ou uma boia) e aperte E. O peixe que sobe vai para a cozinha.":`Sube al barco (o a una boya) y pulsa E. El pescado que sube va a la cocina.`,"Metade do ar. Vá pensando na volta.":`La mitad del aire. Ve pensando en la vuelta.`,"Só um quarto do ar! Volte ao barco ou ache um bolsão de ar.":`¡Solo queda un cuarto del aire! Vuelve al barco o busca una bolsa de aire.`,"Por que o Tuca mergulha":`Por qué Tuca se zambulle`,"Meu neto, sem peixe não tem prato. De dia você desce o poço e traz o pescado; de noite a gente abre o Boca do Poço, e cada noite boa paga um pedaço da dívida do seu avô.":`Nieto mío, sin pescado no hay plato. De día bajas al pozo y traes la pesca; de noche abrimos el Boca do Poço, y cada buena noche paga un pedazo de la deuda de tu abuelo.`,"O barco":`El barco`,"Ande pelo convés com A e D e aperte E em cima de um ponto.":`Camina por la cubierta con A y D y pulsa E sobre un punto.`,"leva o barco pelo rio; de noite, até o Boca do Poço":`lleva el barco por el río; de noche, hasta el Boca do Poço`,"melhora o tanque, o traje, a carga e as armas":`mejora el tanque, el traje, la carga y las armas`,"desce ao poço para pescar":`baja al pozo a pescar`,"descansa e deixa o turno passar":`descansa y deja pasar el turno`,"O caderno de bordo":`La bitácora`,'Aperte Tab para abrir o caderno. Na aba "Espécies" ficam os peixes que você já pescou e onde cada um vive.':`Pulsa Tab para abrir la bitácora. En la pestaña "Especies" están los peces que ya pescaste y dónde vive cada uno.`,"A primeira noite":`La primera noche`,"A e D andam pelo balcão. Os fregueses chegam, pedem, comem e pagam: cada prato servido vira moeda.":`A y D te mueven por la barra. Los clientes llegan, piden, comen y pagan: cada plato servido se vuelve moneda.`,"O pedido":`El pedido`,"O balão em cima do freguês mostra o prato que ele quer.":`El globo sobre el cliente muestra el plato que quiere.`,"O passa-prato":`El pasaplatos`,"Os pratos saem prontos aqui. Vá até o passa-prato e aperte E para pegar.":`Los platos salen listos aquí. Ve al pasaplatos y pulsa E para recogerlos.`,"Entregue o prato":`Entrega el plato`,"Leve o prato até quem pediu e aperte E na frente dele.":`Lleva el plato a quien lo pidió y pulsa E frente a esa persona.`,"A louça":`La vajilla`,"Quem comeu deixa a louça no balcão. Aperte E em cima dela para limpar o lugar para o próximo freguês.":`Quien comió deja la vajilla en la barra. Pulsa E sobre ella para despejar el sitio para el siguiente cliente.`,"O tacacá":`El tacacá`,"Tacacá se serve na hora: segure E para encher a cuia e solte na marca.":`El tacacá se sirve al momento: mantén E para llenar la jícara y suelta en la marca.`,"Quem espera, cansa":`Quien espera, se cansa`,"Quem espera demais vai embora sem pagar, e a fama cai. Sirva primeiro quem chegou antes.":`Quien espera demasiado se va sin pagar, y la fama cae. Sirve primero a quien llegó antes.`,"O caderno do Regatão":`La libreta del mercader`,"Fechada a casa, o Regatão anota a noite: o que vendeu, o que gastou e a fama. O lucro de cada noite boa paga um pedaço da dívida do avô.":`Cerrada la casa, el mercader anota la noche: lo que vendió, lo que gastó y la fama. La ganancia de cada buena noche paga un pedazo de la deuda del abuelo.`,Pular:`Saltar`,Raso:`Bajío`,Abismo:`Abismo`,Espaço:`Espacio`,"{distancia} m":`{distancia} m`,"Liga e desliga o som (tecla M)":`Activa y desactiva el sonido (tecla M)`,Volume:`Volumen`,"Ar no tanque":`Aire en el tanque`,"{metros} m · {faixa}":`{metros} m · {faixa}`,"pressão!":`¡presión!`,"{peso}/{capacidade} kg":`{peso}/{capacidade} kg`,"Ver o que você pegou (tecla C)":`Ver lo que llevas (tecla C)`,Carga:`Carga`,"{peso} kg · {valor} moedas":`{peso} kg · {valor} monedas`,Arpão:`Arpón`,"Mouse 1":`Ratón 1`,"Tarrafa: traz vivos os peixes pequenos":`Atarraya: trae vivos los peces pequeños`,Faca:`Cuchillo`,"Lanterna (acende sozinha no escuro)":`Linterna (se enciende sola en la oscuridad)`,"<kbd>Tab</kbd> troca":`<kbd>Tab</kbd> cambia`,"<kbd>WASD</kbd> nada · <kbd>Shift</kbd> arrancada · <kbd>Mouse 1</kbd> segure para mirar, solte para atirar · <kbd>Tab</kbd> troca a arma · <kbd>F</kbd> faca · <kbd>C</kbd> carga · <kbd>Q</kbd> apetrecho":`<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> acelerar · <kbd>Ratón 1</kbd> mantén para apuntar, suelta para disparar · <kbd>Tab</kbd> cambiar arma · <kbd>F</kbd> cuchillo · <kbd>C</kbd> carga · <kbd>Q</kbd> utensilio`,"Pular o tutorial":`Saltar el tutorial`,pular:`saltar`,"Nada pescado ainda":`Nada pescado aún`,"{peso} kg":`{peso} kg`,"Soltar um (libera o peso)":`Soltar uno (libera peso)`,"Arpão · {ponta}":`Arpón · {ponta}`,"{arma} (achada num caixote: vale só neste mergulho)":`{arma} (hallada en un cajón: solo para este buceo)`,"Arpão sem ponta":`Arpón sin punta`,"{ponta} · tarrafa {lances} · boias {boias} · {arma} {municao}":`{ponta} · atarraya {lances} · boyas {boias} · {arma} {municao}`,"{ponta} · tarrafa {lances} · boias {boias}":`{ponta} · atarraya {lances} · boyas {boias}`,Baixo:`Bajo`,"Para computador fraco: sem brilho nas luzes e menos partículas.":`Para ordenadores flojos: sin brillo en las luces y menos partículas.`,Médio:`Medio`,"Resolução um pouco menor, brilho mais leve e menos partículas.":`Resolución algo menor, brillo más suave y menos partículas.`,Alto:`Alto`,"O rio com tudo o que ele tem.":`El río con todo lo que tiene.`,"Opções (Esc)":`Opciones (Esc)`,Opções:`Opciones`,"Fechar (Esc)":`Cerrar (Esc)`,Som:`Sonido`,"Volume geral":`Volumen general`,Música:`Música`,Efeitos:`Efectos`,"Interface e voz":`Interfaz y voz`,Mudo:`Silencio`,Gráficos:`Gráficos`,Interface:`Interfaz`,Tamanho:`Tamaño`,"Tamanho da interface":`Tamaño de la interfaz`,Idioma:`Idioma`,"Trocar de idioma recarrega o jogo. O progresso fica salvo.":`Cambiar de idioma recarga el juego. El progreso queda guardado.`,Continuar:`Continuar`,"Sem som":`Sin sonido`,"Som ligado":`Sonido activado`,"Voltar mesmo? O que não foi guardado se perde.":`¿Volver de verdad? Lo que no se guardó se pierde.`,"Voltar ao título":`Volver al título`,"<kbd>A</kbd><kbd>D</kbd> andar pelo convés · <kbd>E</kbd> usar · <kbd>Tab</kbd> caderno de bordo":`<kbd>A</kbd><kbd>D</kbd> moverte por cubierta · <kbd>E</kbd> usar · <kbd>Tab</kbd> bitácora`,"<kbd>A</kbd><kbd>D</kbd> escolher o lugar · <kbd>E</kbd> navegar até lá · <kbd>Esc</kbd> voltar ao convés":`<kbd>A</kbd><kbd>D</kbd> elegir lugar · <kbd>E</kbd> navegar hasta allí · <kbd>Esc</kbd> volver a cubierta`,"Dia {dia}":`Día {dia}`,"Caderno de bordo (Tab)":`Bitácora (Tab)`,Caderno:`Bitácora`,Tab:`Tab`,"Caderno de bordo":`Bitácora`,"Dia {dia} · {turno}":`Día {dia} · {turno}`,"O que fazer":`Qué hacer`,"Como jogar":`Cómo jugar`,Espécies:`Especies`,"O progresso fica salvo.":`Tu progreso queda guardado.`,"Sair do jogo":`Salir del juego`,"O dia":`El día`,"<b>Manhã e tarde</b>um mergulho em cada turno":`<b>Mañana y tarde</b>un buceo en cada turno`,"<b>No barco</b>o peixe que sobe vai para a despensa":`<b>En el barco</b>el pescado que sube va a la despensa`,"<b>Noite</b>o Boca do Poço abre e você serve no balcão":`<b>Noche</b>el Boca do Poço abre y tú sirves en la barra`,"<b>Com o ouro</b>mais ar, mais carga e mais fundo":`<b>Con el oro</b>más aire, más carga y más hondo`,"No mergulho":`Al bucear`,"<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> arrancada":`<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> acelerar`,"<kbd>Mouse</kbd> segure para mirar, solte para atirar":`<kbd>Ratón</kbd> mantén para apuntar, suelta para disparar`,"<kbd>F</kbd> faca: abre caixote, pega achado":`<kbd>F</kbd> cuchillo: abre cajones, recoge hallazgos`,"<kbd>Tab</kbd> troca a arma · <kbd>C</kbd> carga":`<kbd>Tab</kbd> cambiar arma · <kbd>C</kbd> carga`,"<kbd>E</kbd> subir no barco ou pela boia":`<kbd>E</kbd> subir al barco o por la boya`,"No restaurante":`En el restaurante`,"<kbd>A</kbd><kbd>D</kbd> andar pelo balcão":`<kbd>A</kbd><kbd>D</kbd> moverte por la barra`,"<kbd>E</kbd> pegar, servir, limpar e socar":`<kbd>E</kbd> recoger, servir, limpiar y majar`,"segure <kbd>E</kbd> para encher a cuia de tacacá":`mantén <kbd>E</kbd> para llenar la jícara de tacacá`,Lembranças:`Recuerdos`,"<kbd>A</kbd><kbd>D</kbd> escolher · <kbd>E</kbd> ou <kbd>Enter</kbd> fazer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> ou <kbd>Esc</kbd> fechar":`<kbd>A</kbd><kbd>D</kbd> elegir · <kbd>E</kbd> o <kbd>Enter</kbd> hacer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> o <kbd>Esc</kbd> cerrar`,"Fama <b>{fama}</b>":`Fama <b>{fama}</b>`,"Despensa <b>{n}</b> peixe":{one:`Despensa <b>{n}</b> pescado`,many:`Despensa <b>{n}</b> pescados`,other:`Despensa <b>{n}</b> pescados`},"<b>{n}</b> de {total} espécies no caderno":`<b>{n}</b> de {total} especies en el cuaderno`,"{n} pescado":{one:`{n} pescado`,other:`{n} pescados`},"maior: {peso} kg":`mayor: {peso} kg`,"Vive entre {min} e {max} m":`Vive entre {min} y {max} m`,"3★ rende {corte}":`3★ da {corte}`,"Encontro anotado":`Encuentro anotado`,"Fama no rio · {grau}":`Fama en el río · {grau}`,Canoa:`Canoa`,farinha:`harina`,"<kbd>A</kbd><kbd>D</kbd> andar · <kbd>E</kbd> ou <kbd>espaço</kbd> pegar, servir, limpar e socar · segure para encher a cuia":`<kbd>A</kbd><kbd>D</kbd> moverte · <kbd>E</kbd> o <kbd>espacio</kbd> recoger, servir, limpiar y majar · mantén para llenar la jícara`,limpar:`limpiar`,"{n} moeda":{one:`{n} moneda`,many:`{n} monedas`,other:`{n} monedas`},"hora de abrir o Boca do Poço":`hora de abrir el Boca do Poço`,"descer no escuro ou dormir até de manhã":`bajar a oscuras o dormir hasta la mañana`,"dois mergulhos até a noite":`dos buceos antes de la noche`,"último mergulho antes da noite":`último buceo antes de la noche`,"Primeiro mergulho":`Primer buceo`,"{n} mergulho":{one:`{n} buceo`,many:`{n} buceos`,other:`{n} buceos`},"Melhor mergulho: {moedas} · {vezes}":`Mejor buceo: {moedas} · {vezes}`,"no máximo":`al máximo`,"Ache esta arma nos caixotes para liberar o projeto: {achadas} de {precisa}.":`Encuentra esta arma en los cajones para desbloquear el plano: {achadas} de {precisa}.`,"✓ Levando":`✓ Llevando`,Levar:`Llevar`,"{n} peça · −{desconto}% de ouro":{one:`{n} pieza · −{desconto}% de monedas`,other:`{n} piezas · −{desconto}% de monedas`},"O rio está acordando":`El río está despertando`,"Ainda dá um mergulho":`Aún da para un buceo`,"A noite é do Boca do Poço":`La noche es del Boca do Poço`,"De dia, o poço · de noite, o balcão":`De día, el pozo · de noche, la barra`,"O Tuca pesca no fundo do poço para abastecer o balcão do <strong>restaurante flutuante</strong> da Dona Naná.":`Tuca pesca en el fondo del pozo para abastecer la barra del <strong>restaurante flotante</strong> de Doña Naná.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa enche o balcão da Dona Naná.":`Lo que Tuca trae del río se vuelve el plato de la noche, y cada buena noche llena la barra de Doña Naná.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa paga um pedaço da dívida do avô.":`Lo que Tuca trae del río se vuelve el plato de la noche, y cada buena noche paga un pedazo de la deuda del abuelo.`,"No barco":`En el barco`,Começar:`Empezar`,"Como o jogo funciona":`Cómo funciona el juego`,"<b>Mergulhe</b>Pesque e junte achados enquanto o ar durar.":`<b>Bucea</b>Pesca y junta hallazgos mientras dure el aire.`,"<b>Volte ao barco</b>O peixe que sobe vai para a despensa do restaurante.":`<b>Vuelve al barco</b>El pescado que sube va a la despensa del restaurante.`,"<b>À noite, abra o Boca do Poço</b>Monte o cardápio e sirva os fregueses no balcão.":`<b>De noche, abre el Boca do Poço</b>Arma el menú y atiende a los clientes en la barra.`,"<b>Melhore o barco</b>Com o ouro, mais ar, mais carga e mais fundo.":`<b>Mejora el barco</b>Con el oro, más aire, más carga y más hondo.`,"O dia tem dois mergulhos, um de manhã e um de tarde; à noite o restaurante abre com o que você pescou. A nota da noite e a fama crescem com o capricho no serviço.":`El día tiene dos buceos, uno por la mañana y otro por la tarde; de noche el restaurante abre con lo que pescaste. La nota de la noche y la fama crecen con el esmero en el servicio.`,"<kbd>WASD</kbd> nadar":`<kbd>WASD</kbd> nadar`,"<kbd>Mouse 1</kbd> segure para mirar, solte para atirar":`<kbd>Ratón 1</kbd> mantén para apuntar, suelta para disparar`,"<kbd>Shift</kbd> arrancada (gasta mais ar)":`<kbd>Shift</kbd> acelerar (gasta más aire)`,"<kbd>Tab</kbd> arpão · arma · tarrafa · faca":`<kbd>Tab</kbd> arpón · arma · atarraya · cuchillo`,"<kbd>F</kbd> faca: abre caixote e caixa de munição, pega achado e arranca minério":`<kbd>F</kbd> cuchillo: abre cajones y cajas de munición, recoge hallazgos y arranca mineral`,"<kbd>Espaço</kbd> contra peixe forte":`<kbd>Espacio</kbd> contra pez fuerte`,"<kbd>C</kbd> carga":`<kbd>C</kbd> carga`,"<kbd>E</kbd> subir (barco ou boia)":`<kbd>E</kbd> subir (barco o boya)`,"<kbd>Q</kbd> apetrecho de defesa: nuvem de urucum ou chamariz de pano":`<kbd>Q</kbd> utensilio de defensa: nube de urucum o señuelo de tela`,"<kbd>M</kbd> som":`<kbd>M</kbd> sonido`,"Volte ao barco antes que o ar acabe: o peixe que sobe vai para a cozinha.":`Vuelve al barco antes de que se acabe el aire: el pescado que sube va a la cocina.`,"<kbd>E</kbd> ou <kbd>Espaço</kbd> pegar o prato, servir, limpar e socar o pilão":`<kbd>E</kbd> o <kbd>Espacio</kbd> recoger el plato, servir, limpiar y majar en el pilón`,"Sirva a cada freguês o prato que ele pediu antes que a paciência acabe.":`Sirve a cada cliente el plato que pidió antes de que se le acabe la paciencia.`,"Com controle":`Con mando`,"<kbd>Analógico esquerdo</kbd> nadar e andar · <kbd>LT</kbd> arrancada":`<kbd>Stick izquierdo</kbd> nadar y caminar · <kbd>LT</kbd> acelerar`,"<kbd>RT</kbd> segure para mirar com o <kbd>analógico direito</kbd>, solte para atirar":`<kbd>RT</kbd> mantén para apuntar con el <kbd>stick derecho</kbd>, suelta para disparar`,"<kbd>A</kbd> usar · <kbd>B</kbd> voltar · <kbd>X</kbd> faca · <kbd>Y</kbd> troca a arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> apetrecho":`<kbd>A</kbd> usar · <kbd>B</kbd> volver · <kbd>X</kbd> cuchillo · <kbd>Y</kbd> cambiar arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> utensilio`,Entendi:`Entendido`,"Fim do mergulho":`Fin del buceo`,"Você desmaiou":`Te desmayaste`,"Subiu pela boia":`Subiste por la boya`,"Você foi puxado para o barco às pressas e só conseguiu segurar a metade mais leve da carga.":`Te subieron al barco a toda prisa y solo pudiste salvar la mitad más ligera de la carga.`,"Você voltou de mãos vazias. O rio continua lá.":`Volviste con las manos vacías. El río sigue ahí.`,"Tudo o que você pescou e achou chegou ao barco.":`Todo lo que pescaste y encontraste llegó al barco.`,"Ficou para trás":`Se quedó atrás`,"Guardado no barco para construir armas: {itens}":`Guardado en el barco para construir armas: {itens}`,"Para a despensa do Boca do Poço (não entra no total): {porcoes}":`Para la despensa del Boca do Poço (no cuenta en el total): {porcoes}`,"<b>{n}</b> porção de {peixe}":{one:`<b>{n}</b> porción de {peixe}`,many:`<b>{n}</b> porciones de {peixe}`,other:`<b>{n}</b> porciones de {peixe}`},"Cortes nobres para a cozinha: {cortes}":`Cortes nobles para la cocina: {cortes}`,"<b>{n}</b> porção de {corte}":{one:`<b>{n}</b> porción de {corte}`,other:`<b>{n}</b> porciones de {corte}`},'Seu Agenor levou <b>{n}</b> peixe doente: +{ouro}. "Não pergunto de onde veio."':{one:`Don Agenor se llevó <b>{n}</b> pez enfermo: +{ouro}. "No pregunto de dónde salió."`,other:`Don Agenor se llevó <b>{n}</b> peces enfermos: +{ouro}. "No pregunto de dónde salieron."`},"Novas no caderno de espécies: {peixes}":`Nuevas en el cuaderno de especies: {peixes}`,"Encomendas do flutuante":`Encargos del restaurante`,"Total com encomendas":`Total con encargos`,Total:`Total`,"Novo recorde!":`¡Nuevo récord!`,"Voltar ao barco":`Volver al barco`,"{preco} o prato · {n} porção na despensa":{one:`{preco} el plato · {n} porción en la despensa`,many:`{preco} el plato · {n} porciones en la despensa`,other:`{preco} el plato · {n} porciones en la despensa`},"Boca do Poço · fama {grau}":`Boca do Poço · fama {grau}`,"O cardápio da noite":`El menú de la noche`,"Escolha até {vagas} pratos. Hoje vêm {fregueses} fregueses; o que sobrar volta para a despensa.":`Elige hasta {vagas} platos. Hoy vienen {fregueses} clientes; lo que sobre vuelve a la despensa.`,"Abrir com {n} porção":{one:`Abrir con {n} porción`,many:`Abrir con {n} porciones`,other:`Abrir con {n} porciones`},"Abrir só com cafezinho":`Abrir solo con cafecito`,"Equipe · {equipe}":`Equipo · {equipe}`,Equipe:`Equipo`,"A casa":`La casa`,"Vender a despensa ao Regatão · {moedas}":`Vender la despensa al mercader · {moedas}`,Voltar:`Volver`,"Você achou":`Encontraste`,"Guardar e continuar":`Guardar y continuar`,"<strong>{ouro}</strong> moedas":`<strong>{ouro}</strong> monedas`,"Cada melhoria aparece no flutuante e vale em todas as noites.":`Cada mejora se ve en el restaurante y vale para todas las noches.`,"Voltar ao cardápio":`Volver al menú`,"Contratar · {preco}":`Contratar · {preco}`,"Na noite ✓":`Esta noche ✓`,"Pôr na noite":`Para esta noche`,"Sem vaga":`Sin plaza`,"diária de {valor}":`jornal de {valor}`,"Com a fama {grau} ainda não cabe ajudante atrás do balcão.":`Con la fama {grau} aún no cabe un ayudante tras la barra.`,"Com a fama {grau} cabe {n} ajudante por noite.":{one:`Con la fama {grau} cabe {n} ayudante por noche.`,many:`Con la fama {grau} caben {n} ayudantes por noche.`,other:`Con la fama {grau} caben {n} ayudantes por noche.`},"Na fama {grau} abre a primeira vaga.":{one:`Con la fama {grau} se abre la primera plaza.`,many:`Con la fama {grau} pasarán a caber {n}.`,other:`Con la fama {grau} pasarán a caber {n}.`},"A equipe":`El equipo`,"O contrato se paga uma vez; a diária sai do lucro da noite.":`El contrato se paga una vez; el jornal sale de la ganancia de la noche.`,"Na noite: <b>{escalados} de {vagas}</b> · diárias de {moedas}":`Esta noche: <b>{escalados} de {vagas}</b> · jornales de {moedas}`,"Na noite: <b>{escalados} de {vagas}</b>":`Esta noche: <b>{escalados} de {vagas}</b>`,hoje:`hoy`,"dia {dia}":`día {dia}`,"De tirar o chapéu":`Para quitarse el sombrero`,"Casa elogiada":`Casa elogiada`,"Deu para o gasto":`Para salir del paso`,"Noite atrapalhada":`Noche enredada`,"Noite para esquecer":`Noche para olvidar`,"{n} freguês foi embora sem comer":{one:`{n} cliente se fue sin comer`,many:`{n} clientes se fueron sin comer`,other:`{n} clientes se fueron sin comer`},"{n} prato foi parar na banqueta errada":{one:`{n} plato fue a parar al taburete equivocado`,many:`{n} platos fueron a parar al taburete equivocado`,other:`{n} platos fueron a parar al taburete equivocado`},"os pratos demoraram a chegar":`los platos tardaron en llegar`,"As lamparinas se apagam. Seu Agenor abre o caderno só para somar o que a casa fez.":`Los candiles se apagan. Don Agenor abre la libreta solo para sumar lo que hizo la casa.`,"As lamparinas se apagam. Seu Agenor abre o caderno e faz as contas da casa.":`Los candiles se apagan. Don Agenor abre la libreta y saca las cuentas de la casa.`,"Caderno da casa":`Libreta de la casa`,"Caderno do Regatão":`Libreta del mercader`,"Noite do dia {dia}":`Noche del día {dia}`,"Saiu da cozinha":`Salió de la cocina`,"{n} prato":{one:`{n} plato`,many:`{n} platos`,other:`{n} platos`},"O mais pedido foi o <b>{prato}</b>: {fatia}% do que entrou.":`El plato más pedido: <b>{prato}</b>, {fatia}% de lo que entró.`,"Nenhum prato saiu hoje.":`Hoy no salió ningún plato.`,"As últimas noites":`Las últimas noches`,"o que ficou em caixa":`lo que quedó en caja`,"A melhor noite que este caderno já viu!":`¡La mejor noche que ha visto esta libreta!`,"Fama no rio: <b>{grau}</b> <em>subiu!</em>":`Fama en el río: <b>{grau}</b> <em>¡subió!</em>`,"Fama no rio: <b>{grau}</b>":`Fama en el río: <b>{grau}</b>`,"{ganho} nesta noite, com +{premio} pelo capricho":`{ganho} esta noche, con +{premio} por el esmero`,"{ganho} nesta noite":`{ganho} esta noche`,"faltam {faltam} para {grau}":`faltan {faltam} para {grau}`,"Contas da noite":`Cuentas de la noche`,"{n} freguês servido":{one:`{n} cliente servido`,many:`{n} clientes servidos`,other:`{n} clientes servidos`},Pratos:`Platos`,Gorjetas:`Propinas`,"Despesa da casa":`Gastos de la casa`,"Diárias da equipe":`Jornales del equipo`,"Faltou no caixa":`Faltó en caja`,"Ficou em caixa":`Quedó en caja`,"conceito da noite":`veredicto de la noche`,"{nota} de 5":`{nota} de 5`,"Ninguém saiu reclamando.":`Nadie se fue quejándose.`,"Conferido por <b>Seu Agenor, o Regatão</b>":`Revisado por <b>Don Agenor, el mercader del río</b>`,"Dormir · amanhã é dia {dia}":`Dormir · mañana es el día {dia}`,Barco:`Barco`,Armas:`Armas`,"Achar a mesma arma duas vezes nos caixotes libera o projeto. O material do poço fica guardado aqui, e a arma construída desce com você em todo mergulho.":`Encontrar la misma arma dos veces en los cajones desbloquea el plano. El material del pozo se guarda aquí, y el arma construida baja contigo en cada buceo.`,Zarabatana:`Cerbatana`,"6 dardos com timbó: o peixe dorme e vem vivo":`6 dardos con timbó: el pez se duerme y llega vivo`,"Espingarda de pressão":`Escopeta de aire`,"6 tiros de três chumbos, para perto":`6 tiros de tres perdigones, para cerca`,Balestra:`Ballesta`,"4 setas pesadas, que atravessam":`4 virotes pesados que atraviesan`,"A noite da cheia":`La noche de la crecida`,"Na boca do poço mais fundo do rio há um flutuante. Seu Raimundo mergulhava, Dona Naná cozinhava, e não passava barco que não encostasse.":`En la boca del pozo más hondo del río hay un restaurante flotante. Don Raimundo buceaba, Doña Naná cocinaba, y no pasaba barco que no se arrimara.`,"Tuca, o neto, voltou da cidade com uma mala e o fôlego do avô. De dia ele desce o poço. De noite, o Boca do Poço abre.":`Tuca, el nieto, volvió de la ciudad con una maleta y el aliento del abuelo. De día baja al pozo. De noche, el Boca do Poço abre.`,"O dia tem dois mergulhos, um de manhã e um de tarde. O peixe que sobe ao barco vira o prato da noite, e cada noite bem servida paga um pedaço da dívida. O rio está esperando.":`El día tiene dos buceos, uno por la mañana y otro por la tarde. El pescado que sube al barco se vuelve el plato de la noche, y cada noche bien servida paga un pedazo de la deuda. El río está esperando.`,"O Tição":`El Tizón`,"A volta do avô":`El regreso del abuelo`,"Cobra-Grande":`Gran Serpiente`,"Escama da Cobra-Grande":`Escama de la Gran Serpiente`,Tuca:`Tuca`,"Dona Naná":`Doña Naná`,"Seu Agenor, o Regatão":`Don Agenor, el mercader del río`,Curimatã:`Curimatã`,Jaci:`Jaci`,"Seu Bené":`Don Bené`,Piaba:`Piaba`,"Seu Raimundo":`Don Raimundo`,"Seu Takeshi":`Don Takeshi`,Kauê:`Kauê`,"Dona Zefa":`Doña Zefa`,"Seu Juvenal":`Don Juvenal`,Ingrid:`Ingrid`,Tião:`Tião`,"Seu Dico":`Don Dico`,"Dois tucunarés":`Dos tucunarés`,"Um tambaqui":`Un tambaquí`,"Três piranhas":`Tres pirañas`,"Dois pacus vivos":`Dos pacús vivos`,"Uma arraia":`Una raya`,"Um poraquê":`Una anguila eléctrica`,"Um pirarucu":`Un pirarucu`,"Cinco jaraquis":`Cinco jaraquís`,"Duas matrinxãs":`Dos matrinchás`,"Três frutos da mata":`Tres frutos de la selva`,"Dois minérios":`Dos minerales`,"Duas conchas":`Dos conchas`,Pacu:`Pacú`,Aracu:`Aracú`,"Acará-disco":`Pez disco`,Piranha:`Piraña`,Tucunaré:`Tucunaré`,Tambaqui:`Tambaquí`,Arraia:`Raya`,Traíra:`Traíra`,Sucuri:`Anaconda`,Surubim:`Surubí`,Pirarara:`Pirarara`,Candiru:`Candirú`,Poraquê:`Anguila eléctrica`,"Peixe-cachorro":`Payara`,Pirarucu:`Pirarucu`,Jaú:`Jaú`,Piraíba:`Piraíba`,Aruanã:`Arawana`,Jaraqui:`Jaraquí`,Matrinxã:`Matrinchá`,Tamuatá:`Tamuatá`,"Peixe-boi":`Manatí`,Acari:`Acarí`,Mandi:`Mandí`,Ituí:`Ituí`,Jacaré:`Yacaré`,"A volta":`El regreso`,"Tu cresceu, menino. E voltou magro. Senta, que conversa de barriga vazia não presta.":`Cómo has crecido, muchacho. Y volviste flaco. Siéntate, que conversar con la barriga vacía no sirve.`,"Vó, que caderno é esse em cima do balcão?":`Abuela, ¿qué libreta es esa sobre la barra?`,"É do Seu Agenor, o Regatão. Teu avô comprou fiado nele a vida toda. Agora ele diz que a conta é do tamanho do flutuante.":`Es de Don Agenor, el mercader del río. Tu abuelo le compró fiado toda la vida. Ahora dice que la cuenta es del tamaño de la casa flotante.`,"Do tamanho do flutuante e mais a canoa, Dona Naná. Mas eu sou homem de paciência: pagando a parcela, eu espero.":`Del tamaño de la casa flotante y la canoa encima, Doña Naná. Pero soy hombre paciente: si me pagan la cuota, espero.`,"Então a gente paga. Eu trago o peixe do poço, a senhora cozinha.":`Entonces pagamos. Yo traigo el pescado del pozo y usted cocina.`,"Teu avô dizia a mesma coisa, com essa mesma cara. Anda, abre a casa.":`Tu abuelo decía lo mismo, con esa misma cara. Anda, abre la casa.`,"O arpão do avô":`El arpón del abuelo`,"Primeira parcela, contadinha. Quem diria: o balcão voltou a encher.":`Primera cuota, contadita. Quién lo diría: la barra volvió a llenarse.`,"Anota aí que pagou, Agenor. De caneta, que lápis teu apaga sozinho.":`Apunta que está pagado, Agenor. Con tinta, que tu lápiz se borra solo.`,"Tuca, teu avô perdeu o arpão dele no raso, na última cheia. Ele amarrava as receitas no cabo, para não molhar na canoa.":`Tuca, tu abuelo perdió su arpón en el bajío, en la última crecida. Ataba las recetas al mango para que no se mojaran en la canoa.`,"Receita amarrada em arpão?":`¿Recetas atadas a un arpón?`,"Ele pescava pensando no prato. Se tu achar, traz. Tem coisa naquele caderno que nem eu sei fazer.":`Pescaba pensando en el plato. Si lo encuentras, tráelo. Hay cosas en ese cuaderno que ni yo sé hacer.`,"O arpão do avô está em algum canto do raso, fincado no chão.":`El arpón del abuelo está en algún rincón del bajío, clavado en el fondo.`,"Arraia não se pesca com pressa nem se cozinha com pressa. Leite de coco, coentro do quintal e fogo baixo. Naná diz que não gosta. Naná repete o prato.":`La raya no se pesca con prisa ni se cocina con prisa. Leche de coco, cilantro del patio y fuego lento. Naná dice que no le gusta. Naná repite.`,"Receita nova no Boca do Poço: moqueca de arraia. As arraias que você pescar agora vão para a despensa.":`Receta nueva en el Boca do Poço: moqueca de raya. Las rayas que pesques ahora van a la despensa.`,"As luzes do fundo":`Las luces del fondo`,"Parcela paga, Dona Naná. Casa cheia, caderno em dia: assim que eu gosto.":`Cuota pagada, Doña Naná. Casa llena, cuaderno al día: así me gusta.`,"Anota e vai embora, Agenor.":`Anótalo y vete, Agenor.`,"Já vou. Só um aviso de amigo: subiu uma draga pelo rio. Gente de fora, gente de dinheiro. Andam perguntando do poço.":`Ya me voy. Solo un aviso de amigo: subió una draga por el río. Gente de fuera, gente con dinero. Andan preguntando por el pozo.`,"Perguntando o quê?":`¿Preguntando qué?`,"Quanto ele tem de fundo. E de quem é este flutuante.":`Cuánto tiene de fondo. Y de quién es esta casa flotante.`,"Teu avô descia de madrugada, sabia? Depois de fechar a casa. Levava a lamparina e dizia que, no escuro, o fundo do poço acendia.":`Tu abuelo bajaba de madrugada, ¿sabías? Después de cerrar la casa. Llevaba la lámpara de aceite y decía que, en la oscuridad, el fondo del pozo se encendía.`,"Eu achava que era cachaça. Na noite da cheia ele desceu com ela e não voltou.":`Yo creía que era la cachaza. La noche de la crecida bajó con ella y no volvió.`,"Então hoje, quando a casa fechar, eu desço.":`Entonces hoy, cuando cerremos, yo bajo.`,"Leva o casaco. E volta, que eu não tenho mais idade para esperar ninguém na beira.":`Llévate el abrigo. Y vuelve, que ya no tengo edad para esperar a nadie en la orilla.`,"A lamparina do avô":`La lámpara del abuelo`,"A lamparina do avô está no fundo, onde ele descia de madrugada.":`La lámpara del abuelo está en el fondo, donde él bajaba de madrugada.`,"Eles cantam lá embaixo, Naná. Tu não acredita, mas eu vi as luzes. O jacaré velho fugiu do igarapé: a draga revirou o fundo de lá e ele veio parar no nosso poço, com raiva. A draga vem vindo. Hoje eu desço para avisar os do fundo. Se eu demorar, guarda a brasa acesa.":`Cantan allá abajo, Naná. Tú no me crees, pero yo vi las luces. El yacaré viejo huyó del arroyo: la draga revolvió el fondo de allá y vino a parar a nuestro pozo, furioso. La draga se acerca. Hoy bajo para avisar a los del fondo. Si tardo, mantén la brasa encendida.`,"A lamparina agora é tua: a lanterna alcança mais longe. E no caderno, duas receitas novas: acari assado e caldo de mandi.":`La lámpara ahora es tuya: la linterna llega más lejos. Y en el cuaderno, dos recetas nuevas: acarí asado y caldo de mandí.`,"O homem da draga":`El hombre de la draga`,"Dona Naná, trouxe uma visita. Gente importante, de fora.":`Doña Naná, le traje una visita. Gente importante, de fuera.`,"Doutor Brandão, minha senhora. Bonito o seu flutuante. Bem na boca do poço.":`Doctor Brandão, señora. Bonita su casa flotante. Justo en la boca del pozo.`,"Se veio comer, senta. Se veio olhar, a vista é de graça.":`Si vino a comer, siéntese. Si vino a mirar, la vista es gratis.`,"Vim fazer negócio. Pago o dobro da dívida, à vista. A senhora descansa e eu ancoro a minha draga aqui.":`Vine a hacer negocios. Pago el doble de la deuda, al contado. Usted descansa y yo anclo mi draga aquí.`,"Este flutuante não está à venda. Nem pelo dobro, nem pelo triplo.":`Esta casa flotante no está en venta. Ni por el doble, ni por el triple.`,"Tudo no rio tem preço, minha senhora. Às vezes quem cobra é o rio.":`Todo en el río tiene precio, señora. A veces quien cobra es el río.`,"Vó, de madrugada tem um jacaré enorme rondando a tona. Os olhos parecem brasa.":`Abuela, de madrugada hay un yacaré enorme rondando la superficie. Los ojos parecen brasas.`,"É o Tição. Teu avô falava dele. Desce com a faca na mão, menino.":`Es el Tizón. Tu abuelo hablaba de él. Baja con el cuchillo en la mano, muchacho.`,"A faca do avô":`El cuchillo del abuelo`,"A faca do avô ficou no meio do poço, onde ele brigou com o Tição.":`El cuchillo del abuelo quedó en medio del pozo, donde peleó con el Tizón.`,'Riscado no cabo, com a ponta da própria faca: "O Tição veio da draga. Bati nele três vezes e ele não largou. Se tu achar esta faca, Tuca, é tua. Não vai atrás dele: deixa ele vir, e bate na hora do bote."':`Rayado en el mango, con la punta del propio cuchillo: "El Tizón vino con la draga. Le pegué tres veces y no soltó. Si encuentras este cuchillo, Tuca, es tuyo. No vayas tras él: déjalo venir y pega cuando embista."`,"A faca do avô é tua: o rebate fica mais fácil e o golpe, mais forte.":`El cuchillo del abuelo es tuyo: desviar es más fácil y el golpe, más fuerte.`,"A porta":`La puerta`,"Dona Naná... preciso contar uma coisa antes que a senhora saiba por outro.":`Doña Naná... tengo que contarle algo antes de que lo sepa por otro.`,"Fala, Agenor. Mas fala de pé, que sentado tu mente melhor.":`Habla, Agenor. Pero de pie, que sentado mientes mejor.`,"Eu vendi a dívida do Raimundo para o Doutor Brandão. Ele quer o poço. A draga desce na próxima cheia.":`Le vendí la deuda de Raimundo al Doctor Brandão. Quiere el pozo. La draga baja en la próxima crecida.`,"O senhor vendeu a gente.":`Usted nos vendió.`,"Vendi papel. Achei que era só papel. O Raimundo dizia que no fundo tinha uma porta, e eu ri dele.":`Vendí papel. Creí que era solo papel. Raimundo decía que en el fondo había una puerta, y yo me reía de él.`,"Sai do meu balcão, Agenor. A despensa tu ainda compra, que eu não sou boba. Mas cafezinho aqui tu não toma mais.":`Fuera de mi mostrador, Agenor. La despensa todavía la compras, que no soy tonta. Pero cafecito aquí no tomas más.`,"Uma porta no fundo do poço, vó?":`¿Una puerta en el fondo del pozo, abuela?`,"Teu avô usava uma pedra verde no pescoço, um sapinho. Dizia que era a chave. Sumiu no dia da cheia, junto com ele.":`Tu abuelo llevaba una piedra verde al cuello, un sapito. Decía que era la llave. Desapareció el día de la crecida, junto con él.`,"O muiraquitã do avô":`El muiraquitã del abuelo`,"O muiraquitã do avô está no fundo mais fundo, onde só se chega de madrugada.":`El muiraquitã del abuelo está en lo más hondo del fondo, adonde solo se llega de madrugada.`,'Amarrado no cordão do muiraquitã, um papel dobrado: "A Cobra-Grande guarda o caminho e não deixa a draga passar. A porta abre para quem leva o sapinho. Se a draga descer, os do fundo vão lutar. Eu vou com eles."':`Atado al cordón del muiraquitã, un papel doblado: "La Gran Serpiente guarda el camino y no deja pasar a la draga. La puerta se abre para quien lleve el sapito. Si la draga baja, los del fondo van a luchar. Yo voy con ellos."`,"O muiraquitã é teu. No fundo, a porta dos encantados já te espera.":`El muiraquitã es tuyo. En el fondo, la puerta de los encantados ya te espera.`,"A cheia":`La crecida`,"O rio subiu dois palmos desde ontem. A cheia chegou.":`El río subió dos palmos desde ayer. Llegó la crecida.`,"Recado do Doutor Brandão: a draga desce amanhã. Quem estiver no caminho, que saia.":`Recado del Doctor Brandão: la draga baja mañana. Quien esté en el camino, que se aparte.`,"Hoje de madrugada eu abro a porta, vó. O Tição vai estar lá.":`Esta madrugada abro la puerta, abuela. El Tizón va a estar ahí.`,"Teu avô disse a mesma coisa, nesta mesma noite. Volta, Tuca. Volta com ele.":`Tu abuelo dijo lo mismo, esta misma noche. Vuelve, Tuca. Vuelve con él.`,"Tuca! Tem um homem subindo a escada do flutuante. Molhado, de barba branca.":`¡Tuca! Hay un hombre subiendo la escalera de la casa flotante. Empapado, de barba blanca.`,"Naná. A brasa ainda está acesa?":`Naná. ¿La brasa sigue encendida?`,"Nunca apagou, velho teimoso. Nunca.":`Nunca se apagó, viejo terco. Nunca.`,"Os do fundo me guardaram até alguém abrir a porta. Não imaginei que ia ser o menino.":`Los del fondo me guardaron hasta que alguien abriera la puerta. No imaginé que sería el muchacho.`,"A draga afundou, vô. O Tição não volta.":`La draga se hundió, abuelo. El Tizón no vuelve.`,"E o Doutor Brandão sumiu rio abaixo. Com ele, o contrato. A dívida... a dívida não existe mais.":`Y el Doctor Brandão desapareció río abajo. Con él, el contrato. La deuda... la deuda ya no existe.`,"Então senta, Raimundo. E tu também, Agenor. Hoje o cafezinho é por conta da casa.":`Entonces siéntate, Raimundo. Y tú también, Agenor. Hoy el cafecito invita la casa.`,"Doutor Brandão":`Doctor Brandão`,"Cilindro de ar":`Cilindro de aire`,"Caixa de munição":`Caja de munición`,"Anel de ouro":`Anillo de oro`,Muiraquitã:`Muiraquitã`,"Baú perdido":`Baúl perdido`,"Cuia de prata":`Jícara de plata`,"Brinco de esmeralda":`Arete de esmeralda`,"Garrafa antiga":`Botella antigua`,"Moeda antiga":`Moneda antigua`,"Pérola de rio":`Perla de río`,Diamante:`Diamante`,Opala:`Ópalo`,Ametista:`Amatista`,Estanho:`Estaño`,Ferro:`Hierro`,Cobre:`Cobre`,"Cacho de açaí":`Racimo de asaí`,"Ouriço de castanha":`Coco de castaña`,"Concha de mexilhão":`Concha de mejillón`,"Casca de caramujo":`Concha de caracol`,"Fragmento de arpão":`Fragmento de arpón`,Sucata:`Chatarra`,"Caco de vidro":`Trozo de vidrio`,Corda:`Cuerda`,Madeira:`Madera`,"Tanque de ar":`Tanque de aire`,"Mais ar para ficar mais tempo lá embaixo.":`Más aire para quedarte más tiempo allá abajo.`,"de ar":`de aire`,Traje:`Traje`,"Aguenta a pressão até mais fundo. Passou do limite, o ar acaba bem mais rápido.":`Aguanta la presión hasta más hondo. Si pasas del límite, el aire se gasta mucho más rápido.`,m:`m`,Samburá:`Cesta`,"Cabe mais peixe e mais achado antes de pesar.":`Caben más peces y más hallazgos antes de que pese.`,kg:`kg`,"Tiro mais forte: peixe resistente vem com menos disparos.":`Tiro más fuerte: el pez resistente cae con menos disparos.`,"de dano":`de daño`,"Golpe mais forte, para o que chega perto demais.":`Golpe más fuerte, para lo que se acerca demasiado.`,Tarrafa:`Atarraya`,"Mais lances de rede por mergulho. Peixe de tarrafa vem vivo e vale mais.":`Más lances de red por buceo. El pez de atarraya llega vivo y vale más.`,lances:`lances`,"Boia de resgate":`Boya de rescate`,"Leva o peixe grande direto para o barco, sem pesar no samburá.":`Lleva el pez grande directo al barco, sin pesar en la cesta.`,"por mergulho":`por buceo`,"Ponta de aço":`Punta de acero`,"+1 de dano":`+1 de daño`,"Ponta farpada":`Punta dentada`,"não solta: aperte Espaço na hora certa":`no se suelta: pulsa Espacio en el momento justo`,"Ponta elétrica":`Punta eléctrica`,"+1 de dano · atordoa o peixe · alterne A e D":`+1 de daño · aturde al pez · alterna A y D`,"Ponta de timbó":`Punta de timbó`,"adormece o peixe: ele vem vivo · siga as setas":`duerme al pez: llega vivo · sigue las flechas`,"Ponta de curare":`Punta de curare`,"veneno: tira vida aos poucos · aperte bem rápido":`veneno: quita vida poco a poco · pulsa muy rápido`,"O que tem de bom hoje?":`¿Qué hay de bueno hoy?`,"Estou varado de fome...":`Estoy muerto de hambre...`,"Hum, que cheiro!":`¡Mmm, qué olor!`,"Capricha aí!":`¡Ponle cariño!`,"Isso é que é comida!":`¡Esto sí es comida!`,"Hum... que beleza.":`Mmm... qué maravilla.`,"Égua, que tá bom demais!":`¡Caray, qué bueno está!`,"Cheirou, chegou!":`¡Olió y llegó!`,"Ô garçom!":`¡Oiga, mozo!`,"Vai demorar?":`¿Va a tardar mucho?`,"Esqueceram de mim?":`¿Se olvidaron de mí?`,"Faz tempo que eu não comia um {prato} assim. Volto amanhã e trago a família.":`Hacía tiempo que no comía {prato} así. Vuelvo mañana y traigo a la familia.`,"Mal sentei e o prato já estava na minha frente. Isso é que é casa bem tocada!":`Apenas me senté y ya tenía el plato delante. ¡Eso es una casa bien llevada!`,"O {prato} da Dona Naná continua o melhor deste rio. Podem escrever.":`Como {prato} de Doña Naná no hay otro en este río. Apúntenlo.`,"Vim de longe só pelo {prato}. Valeu cada remada.":`Vine de lejos solo para probar {prato}. Valió cada remada.`,"A comida é boa, mas hoje a espera foi comprida.":`La comida es buena, pero hoy la espera fue larga.`,"Gostei do {prato}. Só achei o balcão meio atrapalhado.":`Comí {prato} y me gustó. Solo vi la barra algo desordenada.`,"Dá para voltar. Com mais ligeireza no serviço, eu voltava toda noite.":`Se puede volver. Con un servicio más ágil, vendría todas las noches.`,"Esperei, esperei e fui embora de barriga vazia. Assim não dá.":`Esperé y esperé, y me fui con la barriga vacía. Así no se puede.`,"Vi gente levantando sem comer. A casa precisa de mais braço no balcão.":`Vi gente levantarse sin comer. A la casa le faltan brazos en la barra.`,"Me trouxeram o prato do vizinho. Hoje não foi a noite de vocês.":`Me trajeron el plato del vecino. Hoy no era su noche.`,"Calado e atento: limpa a banqueta antes de você notar que sujou.":`Callado y atento: limpia el taburete antes de que notes que se ensució.`,"Soca o pilão cantando: a farinha não acaba mais.":`Maja en el pilón cantando: la harina ya no se acaba.`,"Devagar e certeiro: nunca erra a marca da cuia.":`Lento y certero: nunca falla la marca de la jícara.`,"Ligeira no balcão: pega o prato pronto e leva a quem pediu.":`Rápida en la barra: toma el plato listo y lo lleva a quien lo pidió.`,"Fogão de duas bocas":`Fogón de dos fuegos`,"A cozinha prepara cada prato mais rápido.":`La cocina prepara cada plato más rápido.`,"s por prato":`s por plato`,"Banquetas estofadas":`Taburetes acolchados`,"Sentado no macio, o freguês espera mais antes de desistir.":`Sentado en blandito, el cliente espera más antes de rendirse.`,"s de paciência":`s de paciencia`,"Pilão grande":`Pilón grande`,"Cabe mais farinha antes de precisar socar de novo.":`Cabe más harina antes de tener que majar otra vez.`,"de farinha":`de harina`,"Lamparinas e flores":`Candiles y flores`,"Casa bonita: mais fregueses deixam gorjeta.":`Casa bonita: más clientes dejan propina.`,"% dão gorjeta":`% dejan propina`,"Placa iluminada":`Letrero iluminado`,"A casa se vê de longe: vêm mais fregueses por noite.":`La casa se ve de lejos: vienen más clientes cada noche.`,"fregueses a mais":`clientes más`,Cafezinho:`Cafecito`,"Costela de tambaqui":`Costilla de tambaquí`,"Filé de tucunaré":`Filete de tucunaré`,"Ventrecha de pirarucu":`Ventresca de pirarucu`,Rabeta:`Peque-peque`,Voadeira:`Lancha`,Batelão:`Barcaza`,Recreio:`Motonave`,Gaiola:`Buque`,"Peixe frito":`Pescado frito`,"Caldo de piranha":`Caldo de piraña`,"Tucunaré na brasa":`Tucunaré a la brasa`,"Tambaqui assado":`Tambaquí asado`,Caldeirada:`Caldeirada`,"Pirarucu de casaca":`Pirarucu de casaca`,"Aruanã assada na folha":`Arawana asada en hoja`,"Moqueca de arraia":`Moqueca de raya`,"Acari assado":`Acarí asado`,"Caldo de mandi":`Caldo de mandí`,"Costela de tambaqui assada":`Costilla de tambaquí asada`,"Filé de tucunaré no tucupi":`Filete de tucunaré en tucupí`},i={"Na boca do poço mais fundo do rio tem um flutuante. É o Boca do Poço, a nossa casa e o nosso restaurante.":`在河里最深的那口深潭边，漂着一座水上餐馆。那就是Boca do Poço，是我们的家，也是我们的餐馆。`,"O meu Raimundo mergulhava e trazia o peixe. Eu cozinhava. De noite, não passava barco que não encostasse.":`我的雷蒙多潜下水去，把鱼带上来。我来做饭。到了夜里，过路的船没有一条不靠过来。`,"Ele dizia que, de madrugada, o fundo do poço acendia. Eu achava que era conversa de pescador.":`他常说，天快亮的时候，深潭底下会亮起来。我只当那是渔夫的闲话。`,"Numa noite de cheia, ele desceu com a lamparina e não voltou.":`涨水的一个夜晚，他提着油灯下去，就再也没有回来。`,"Ficaram a brasa acesa, o balcão vazio e uma dívida no caderno do Seu Agenor, o Regatão. Do tamanho do flutuante.":`留下的，是还烧着的炭火、空荡荡的柜台，还有记在河上商贩阿热诺尔大叔账本里的一笔债。大得跟这座水上餐馆一样。`,"Foi aí que o Tuca, nosso neto, voltou da cidade. Veio me ajudar a tocar o restaurante.":`就在那时，我们的孙子图卡从城里回来了。他回来帮我撑起这家餐馆。`,"Sem peixe não tem prato. Então, todo dia, ele desce o poço e traz o pescado. De noite, eu cozinho e ele serve. Cada noite boa paga um pedaço da dívida.":`没有鱼，就没有菜。所以他每天都潜进深潭，把鱼捞上来。夜里我下厨，他端菜。每一个好夜晚，都能还上一点债。`,"E lá embaixo, o rio ainda guarda o que aconteceu com o Raimundo.":`而在深深的水底，这条河还藏着雷蒙多的下落。`,"Saco de urucum":`胭脂树红粉袋`,"Chamariz de pano":`布偶诱饵`,"Rondando você":`在你周围打转`,"Vai dar o bote: rebata com a faca!":`它要扑过来了：用刀格挡！`,"Rebata agora!":`现在格挡！`,"Tonto: arpão e faca agora!":`它晕了：快用鱼叉和刀！`,"Ela está acordando…":`它要醒了……`,"Vai dar o bote: saia da frente!":`它要扑过来了：快闪开！`,"Saia da frente!":`快闪开！`,"Boca aberta: atire agora!":`嘴张开了：快射！`,"Cuidado com a cauda!":`小心尾巴！`,"Ela desistiu de você":`它放过你了`,"Amanheceu: dia {dia}":`天亮了：第{dia}天`,"A tarde chegou":`下午到了`,"Anoiteceu: o Boca do Poço pode abrir":`天黑了：Boca do Poço可以开门了`,"Peixe forte! Aperte espaço (ou clique) bem rápido para cansá-lo.":`鱼劲很大！快速连按空格（或点击）耗光它的力气。`,"Peixe forte! Alterne A e D bem rápido.":`鱼劲很大！快速交替按A和D。`,"Peixe forte! Aperte as setas na ordem, antes que o tempo acabe.":`鱼劲很大！在时间耗尽前按顺序按方向键。`,"Peixe forte! Aperte espaço quando o marcador passar no verde.":`鱼劲很大！指针经过绿色区域时按空格。`,"Levar o barco até o Boca do Poço, que abre agora.":`把船开到Boca do Poço，现在就开门。`,"na escada":`在梯子旁`,"Levar o barco pelo rio. O Boca do Poço abre à noite.":`沿河开船。Boca do Poço晚上开门。`,"no leme":`在船舵旁`,"Melhorar o tanque, o traje, a carga e as armas.":`升级气罐、潜水服、鱼篓和武器。`,"na bancada":`在工作台旁`,"Deixar o turno passar sem mergulhar.":`不潜水，让这个时段过去。`,"no banco da proa":`在船头长凳旁`,"Antes do primeiro mergulho":`第一次潜水之前`,"De volta ao barco":`回到船上`,"Barco ancorado no igapó. O mergulho daqui é entre as árvores.":`船停在淹没林了。从这里下潜，就是在树林间游。`,"Barco ancorado no poço.":`船停在深潭了。`,"{destino}: {motivo}":`{destino}：{motivo}`,"{destino} · {rotulo}":`{destino} · {rotulo}`,Final:`终章`,"Capítulo {numero}":`第{numero}章`,"Abrir o cardápio":`打开菜单`,"{escalados} de {vagas} na noite":`今晚上岗{escalados}/{vagas}`,limpeza:`清洁`,pilão:`捣臼`,tacacá:`tacacá`,"serve os pratos":`上菜`,"Um freguês":`一位客人`,"Primeira noite":`第一个夜晚`,"Primeira noite · {numero} de {total}":`第一个夜晚 · {numero} / {total}`,"Cansei de esperar!":`等不下去了！`,"Um freguês cansou de esperar e foi embora":`一位客人等烦了，走了`,"{prato} acabou":`{prato}卖完了`,"Um prato":`一道菜`,"Tacacá na marca: ele paga 30% a mais":`tacacá正好到线：他多付30%`,"Passou da marca: derramou o tacacá":`倒过线了：tacacá洒了`,"Faltou tacacá na cuia":`葫芦碗里的tacacá不够`,"Acabou a farinha: a cozinha parou. Soque o pilão!":`木薯粉用完了：厨房停工了。快去捣臼！`,"Um peixe-boi! Ele deixou você chegar perto. Presente do igapó: {ouro} moedas.":`是海牛！它让你靠近了。淹没林的礼物：{ouro}枚金币。`,"Encomenda do flutuante: {encomendas}":`水上餐馆的订单：{encomendas}`,"A porta dos encantados te espera no fundo. O Tição também.":`通往被施法者的门在潭底等着你。火炭也在等。`,"Tutorial concluído. Agora abra o Boca do Poço e sirva o que pescou!":`教程完成。现在打开Boca do Poço，把捕到的鱼端上桌吧！`,"Primeiro mergulho · {numero} de {total}":`第一次潜水 · {numero}/{total}`,"Carga cheia! Volte ao barco.":`装满了！回船上去。`,"Encomenda cumprida: {encomenda} (+{premio})":`订单完成：{encomenda}（+{premio}）`,"Soltou {nome}":`放掉了{nome}`,"Espécie nova! {peixe}":`新物种！{peixe}`,"Espécie nova no caderno: {peixe} · +{moedas} moedas":`图鉴新物种：{peixe} · +{moedas}金币`,"Abatido!":`击杀！`,"Falta {n}":{other:`还剩{n}`},"Rebateu!":`挡开了！`,"O Tição está tonto: agora o arpão e a faca ferem!":`火炭晕了：现在鱼叉和刀能伤到它！`,"A porta dos encantados":`被施法者之门`,"O Tição afunda na escuridão e não volta. A porta se abre devagar, e a água do fundo acende como o avô dizia: luzes que cantam. Lá em cima, um estrondo: a draga do Doutor Brandão adernou e foi ao fundo, longe do poço. Uma voz conhecida chama o teu nome.":`火炭沉入黑暗，再也没有回来。门慢慢打开，潭底的水亮了起来，正如爷爷说的：会唱歌的光。上面传来一声巨响：布兰当博士的采金船翻了，沉到了远离深潭的河底。一个熟悉的声音在叫你的名字。`,"Presente dos encantados: {ouro} moedas. Volte ao balcão: tem alguém esperando.":`被施法者的礼物：{ouro}枚金币。回柜台去吧：有人在等你。`,"Boia de resgate: {peixe} {marca} a caminho do barco":`救援浮标：{peixe} {marca}正送往船上`,"{peixe} {marca} · {peso} kg":`{peixe} {marca} · {peso} kg`,"Este {peixe} está doente: Dona Naná não vai cozinhar.":`这条{peixe}生病了：娜娜奶奶不会做它。`,"O couro do jacaré não fura. Só o rebate de faca o afasta.":`凯门鳄的皮刺不穿。只有用刀格挡才能逼退它。`,"O couro dela não fura. Espere o bote: cansada, ela abre a boca.":`它的皮刺不穿。等它扑过来：累了它就会张嘴。`,"A Cobra-Grande se recolheu e deixou uma escama: +{valor}":`大蛇退走了，留下一片鳞：+{valor}`,"Uma posta de {peixe} · +{valor}":{other:`{n}块{peixe} · +{valor}`},"Tanque cheio: o cilindro fica aí para quando faltar ar.":`气罐是满的：这个气瓶先留着，缺气时再用。`,"+{ar} de ar":`空气+{ar}`,"Já leva {caixas} caixas de munição guardadas: esta fica para depois.":`已经存了{caixas}箱弹药：这箱先留着。`,"{arma}: +{tiros} de munição":`{arma}：弹药+{tiros}`,"+{tiros} munição":`弹药+{tiros}`,"Caixa de munição guardada ({caixas}): entra quando a arma esvaziar.":`弹药箱已存（{caixas}）：武器打空时自动装填。`,"Caixa de munição guardada ({caixas}): serve para a arma que você achar num caixote.":`弹药箱已存（{caixas}）：给你在木箱里找到的武器用。`,"Caixa guardada":`已存起`,"{item} para o barco":`{item}送上船`,"Peças de {arma} para o Barco (+1)":`{arma}的零件已送往船上（+1）`,"Projeto liberado: {arma}. Dá para construir no Barco.":`图纸解锁：{arma}。可以在船上制作。`,"{apetrecho} no cinto · {tecla} para usar":`{apetrecho}已挂在腰带上 · 按{tecla}使用`,"Tarrafa: +{lances} lances":`抛网：+{lances}网`,"+{lances} lances":`+{lances}网`,"Punhado de moedas":`一把金币`,"Moedas +{valor}":`金币+{valor}`,"Boia de resgate: leva um peixe grande direto para o barco":`救援浮标：把大鱼直接送上船`,"+1 boia":`浮标+1`,"Nuvem de urucum: os bichos perderam você de vista":`胭脂树红雾：猛兽看不见你了`,"Chamariz solto: os bichos vão atrás dele":`诱饵已放出：猛兽都冲它去了`,"O Tição levou {peixe} da sua carga!":`火炭从你的渔获里叼走了{peixe}！`,"{bicho} enrolou você! Aperte espaço bem rápido para se soltar.":`{bicho}缠住了你！快速连按空格挣脱。`,"{bicho} investiu!":`{bicho}冲过来了！`,"O veneno derrubou o peixe: ele fica boiando e vale 1 estrela.":`毒倒了这条鱼：它会浮着，只值1星。`,"{bicho} bateu na pedra e ficou tonta!":`{bicho}撞上岩石，晕头转向！`,"Ferroada de arraia!":`被魟鱼蜇了！`,"A Cobra-Grande acordou!":`大蛇醒了！`,"O bote da Cobra-Grande pegou você!":`被大蛇扑中了！`,"A cauda dela pegou você!":`被它的尾巴扫中了！`,"Ela cansou e abriu a boca: atire na cabeça agora!":`它累得张开了嘴：快射它的头！`,"A Cobra-Grande voltou a dormir. O que ela perdeu de vida, continua perdido.":`大蛇又睡着了。它掉的血不会回来。`,"O Tição saiu da porta!":`火炭从门里冲出来了！`,"O bote do Tição pegou você!":`你被火炭扑中了！`,"O Tição voltou para a porta. O que ele perdeu de vida, continua perdido.":`火炭退回门里了。它掉的血不会回来。`,"O boto achou um caixote: vá atrás dele!":`河豚找到一个木箱：跟上它！`,"Dormiu!":`睡着了！`,"Peixe grande demais para a linha: chegue perto para mandá-lo de boia ao barco.":`鱼太大，线拉不动：靠近用浮标送上船。`,"Peixe grande demais para a linha: chegue perto para recolher.":`鱼太大，线拉不动：游过去收。`,"Fisgou!":`叉中了！`,"Atordoado!":`晕了！`,Envenenado:`中毒`,"Cansou!":`累了！`,"A linha cedeu — o peixe escapou!":`线断了——鱼跑了！`,"Você se soltou!":`你挣脱了！`,"{bicho} cansou e soltou você.":`{bicho}累了，松开了你。`,"{arma}: a caixa guardada entrou, +{tiros} de munição":`{arma}：用上了存的弹药箱，弹药+{tiros}`,"{arma} sem munição: ficou para trás.":`{arma}没弹药了：扔下了。`,"Adormecido, o peixe fica parado: chegue perto para recolher. Vem vivo, com 3 estrelas.":`鱼睡着了，不会动：游过去收。活捉，3星。`,"Grogue! Mais um dardo":`晕乎了！再来一镖`,"Abatido a tiro, o peixe fica boiando: chegue perto para recolher. Vale 1 estrela.":`鱼被打死后会浮着：游过去收。只值1星。`,"{presos} na rede!":`网住了{presos}条！`,"Forte demais para a tarrafa: esse é no arpão.":`这条抛网网不住：得用鱼叉。`,Zzz:`Zzz`,"Choque do poraquê!":`被电鳗电了！`,"Bolsão de ar: tanque cheio":`气穴：气罐充满`,"Tem alguma coisa brilhando no chão, aqui perto.":`附近的河底有东西在发光。`,Tição:`火炭`,"Pouco ar! Volte ao barco.":`空气不足！回船上去。`,"Fundo demais para este traje ({limite} m): o ar acaba {fator}× mais rápido. No barco tem um melhor.":`这身潜水服下不了这么深（{limite} m）：空气消耗快{fator}倍。船上有更好的。`,"Subir no barco":`上船`,"Subir pela boia":`从浮标上去`,"Abrir o caixote":`打开木箱`,"Arrancar o minério com a faca":`用刀撬下矿石`,"Tirar postas com a faca":`用刀切鱼块`,"Boca do Poço":`Boca do Poço`,"PEIXE NA BRASA  •  TACACÁ":`炭烤鱼  •  TACACÁ`,HOJE:`今日`,"peixe fresco":`鲜鱼`,"{nome} (doente)":`{nome}（生病）`,"Posta de {peixe}":`{peixe}块`,Leme:`船舵`,Bancada:`工作台`,Escada:`梯子`,"Banco da proa":`船头长凳`,"Mapa do rio":`河流地图`,Equipamento:`装备`,"Descer de madrugada":`凌晨下潜`,Mergulhar:`潜水`,"O rio descansa à noite":`河流夜里要歇息`,"Dormir sem abrir a casa":`不开店，直接睡觉`,"Dormir até de manhã":`睡到早上`,"Descansar até a tarde":`休息到下午`,"Descansar até a noite":`休息到晚上`,Madrugada:`凌晨`,Manhã:`上午`,Tarde:`下午`,Noite:`晚上`,"Pasta devagar entre as raízes do igapó. Deixou o Tuca chegar perto e não teve medo.":`在淹没林的树根间慢悠悠地吃草。它让图卡靠近，一点也不害怕。`,peixe:`鱼`,"Descer ao igapó e pescar. Gasta este turno.":`潜入淹没林捕鱼。会用掉这个时段。`,"Madrugada do dia {dia}: o igapó está escuro":`第{dia}天凌晨：淹没林一片漆黑`,Galhada:`枝杈区`,"Ar preso entre as raízes: entre nele para encher o tanque.":`树根间困着空气：游进去给气罐充气。`,"Você no igapó · barco no alto · pontos claros: bolsões de ar":`你在淹没林里 · 船在上方 · 亮点：气穴`,"Descer ao poço e pescar. Gasta este turno.":`下到深潭捕鱼。会用掉这个时段。`,"Madrugada do dia {dia}: o poço está escuro":`第{dia}天凌晨：深潭一片漆黑`,Paredões:`峭壁区`,"Ar preso no teto da gruta: entre nele para encher o tanque.":`洞顶困着空气：游进去给气罐充气。`,"Você no poço · barco no alto · pontos claros: bolsões de ar":`你在深潭里 · 船在上方 · 亮点：气穴`,"Poço do Raimundo":`雷蒙多深潭`,Igapó:`淹没林`,"Voltar ao convés":`回到甲板`,"Ancorar no poço":`在深潭下锚`,"Ancorar no igapó":`在淹没林下锚`,"Abrir o Boca do Poço":`打开Boca do Poço`,"Abre à noite":`晚上开门`,"Nade para o fundo":`往下游`,"Desça alguns metros. Segure Shift para arrancar, mas gasta mais ar.":`下潜几米。按住Shift冲刺，但更耗气。`,"O ar é a sua vida":`空气就是生命`,"Este medidor é o ar do tanque. Ele cai com o tempo, mais rápido no fundo e a cada ferida.":`这个量表是气瓶里的空气。它会随时间下降，越深降得越快，每受一次伤也会更快。`,"Se o ar acabar, você desmaia, é puxado de volta ao barco e perde metade do pescado. Volte antes!":`空气用完，你就会昏过去，被拉回船上，还会丢掉一半的鱼。要早点回来！`,"Pesque um peixe":`捕一条鱼`,Mouse:`鼠标`,"Segure o botão do mouse para mirar e solte para atirar. Peixe forte: aperte Espaço para cansá-lo.":`按住鼠标按键瞄准，松开发射。遇到力气大的鱼：按空格键把它耗累。`,"O peso da carga":`收获的重量`,"A barra mostra o peso que você leva e o máximo que aguenta. Cheia, não cabe mais nada.":`进度条显示你带着的重量和能承受的上限。满了，就再也装不下了。`,"Aperte C para ver a carga e solte o peixe que vale menos. Na bancada do barco dá para aumentar a capacidade.":`按 C 键查看收获，把最不值钱的鱼放掉。在船上的工作台还能提高容量。`,"Abra e pegue com a faca":`用刀撬开、拾取`,"Perto de um caixote, de uma caixa ou de um achado, aperte F.":`靠近木箱、盒子或宝物时，按F。`,"Volte ao barco":`回到船上`,"Suba até o barco (ou uma boia) e aperte E. O peixe que sobe vai para a cozinha.":`游到船边（或浮标）按E。带上来的鱼会送进厨房。`,"Metade do ar. Vá pensando na volta.":`空气剩一半了。该想想回去的事了。`,"Só um quarto do ar! Volte ao barco ou ache um bolsão de ar.":`空气只剩四分之一了！快回到船上，或者找个气穴。`,"Por que o Tuca mergulha":`图卡为什么要潜水`,"Meu neto, sem peixe não tem prato. De dia você desce o poço e traz o pescado; de noite a gente abre o Boca do Poço, e cada noite boa paga um pedaço da dívida do seu avô.":`孙子啊，没有鱼就没有菜。白天你潜进深潭把鱼捞上来；夜里我们开张Boca do Poço，每个好夜晚都能还上你爷爷欠下的一点债。`,"O barco":`船`,"Ande pelo convés com A e D e aperte E em cima de um ponto.":`用 A 和 D 在甲板上走动，站到一个位置上按 E 键。`,"leva o barco pelo rio; de noite, até o Boca do Poço":`驾船沿河而行；夜里驶向Boca do Poço`,"melhora o tanque, o traje, a carga e as armas":`升级气瓶、潜水服、收获容量和武器`,"desce ao poço para pescar":`潜进深潭去捕鱼`,"descansa e deixa o turno passar":`休息，让这一班过去`,"O caderno de bordo":`航海日志`,'Aperte Tab para abrir o caderno. Na aba "Espécies" ficam os peixes que você já pescou e onde cada um vive.':`按 Tab 键打开日志。“物种”页里记着你捕到过的鱼，以及它们各自生活的地方。`,"A primeira noite":`第一个夜晚`,"A e D andam pelo balcão. Os fregueses chegam, pedem, comem e pagam: cada prato servido vira moeda.":`按 A 和 D 在柜台前走动。客人来了，点菜、吃饭、付钱：每上一道菜就变成金币。`,"O pedido":`点单`,"O balão em cima do freguês mostra o prato que ele quer.":`客人头顶的气泡显示他想要的菜。`,"O passa-prato":`出餐口`,"Os pratos saem prontos aqui. Vá até o passa-prato e aperte E para pegar.":`做好的菜都从这里出来。走到出餐口，按 E 键拿起。`,"Entregue o prato":`上菜`,"Leve o prato até quem pediu e aperte E na frente dele.":`把菜端给点菜的人，在他面前按 E 键。`,"A louça":`碗碟`,"Quem comeu deixa a louça no balcão. Aperte E em cima dela para limpar o lugar para o próximo freguês.":`吃完的客人会把碗碟留在柜台上。在碗碟上按 E 键，给下一位客人腾出位子。`,"O tacacá":`tacacá`,"Tacacá se serve na hora: segure E para encher a cuia e solte na marca.":`tacacá现做现上：按住 E 键把葫芦碗盛满，在标记处松手。`,"Quem espera, cansa":`等的人会不耐烦`,"Quem espera demais vai embora sem pagar, e a fama cai. Sirva primeiro quem chegou antes.":`等得太久的客人会不付钱就走，名气也会下降。先招呼先来的人。`,"O caderno do Regatão":`河上商贩的账本`,"Fechada a casa, o Regatão anota a noite: o que vendeu, o que gastou e a fama. O lucro de cada noite boa paga um pedaço da dívida do avô.":`打烊之后，河上商贩会把这一夜记在账上：卖了多少、花了多少，还有名气。每个好夜晚的利润，都能还上爷爷欠下的一点债。`,Pular:`跳过`,Raso:`浅水区`,Abismo:`深渊`,Espaço:`空格`,"{distancia} m":`{distancia} m`,"Liga e desliga o som (tecla M)":`开关声音（M键）`,Volume:`音量`,"Ar no tanque":`气罐余量`,"{metros} m · {faixa}":`{metros} m · {faixa}`,"pressão!":`水压！`,"{peso}/{capacidade} kg":`{peso}/{capacidade} kg`,"Ver o que você pegou (tecla C)":`查看收获（C键）`,Carga:`收获`,"{peso} kg · {valor} moedas":`{peso} kg · {valor}金币`,Arpão:`鱼叉`,"Mouse 1":`鼠标左键`,"Tarrafa: traz vivos os peixes pequenos":`抛网：活捉小鱼`,Faca:`潜水刀`,"Lanterna (acende sozinha no escuro)":`手电（黑暗中自动亮起）`,"<kbd>Tab</kbd> troca":`<kbd>Tab</kbd> 切换`,"<kbd>WASD</kbd> nada · <kbd>Shift</kbd> arrancada · <kbd>Mouse 1</kbd> segure para mirar, solte para atirar · <kbd>Tab</kbd> troca a arma · <kbd>F</kbd> faca · <kbd>C</kbd> carga · <kbd>Q</kbd> apetrecho":`<kbd>WASD</kbd> 游动 · <kbd>Shift</kbd> 冲刺 · <kbd>鼠标左键</kbd> 按住瞄准，松开发射 · <kbd>Tab</kbd> 切换武器 · <kbd>F</kbd> 潜水刀 · <kbd>C</kbd> 收获 · <kbd>Q</kbd> 道具`,"Pular o tutorial":`跳过教程`,pular:`跳过`,"Nada pescado ainda":`还没有收获`,"{peso} kg":`{peso} kg`,"Soltar um (libera o peso)":`放掉一个（减轻重量）`,"Arpão · {ponta}":`鱼叉 · {ponta}`,"{arma} (achada num caixote: vale só neste mergulho)":`{arma}（木箱里找到的：仅限本次潜水）`,"Arpão sem ponta":`鱼叉（无叉头）`,"{ponta} · tarrafa {lances} · boias {boias} · {arma} {municao}":`{ponta} · 抛网{lances} · 浮标{boias} · {arma} {municao}`,"{ponta} · tarrafa {lances} · boias {boias}":`{ponta} · 抛网{lances} · 浮标{boias}`,Baixo:`低`,"Para computador fraco: sem brilho nas luzes e menos partículas.":`适合配置较低的电脑：灯光没有光晕，粒子更少。`,Médio:`中`,"Resolução um pouco menor, brilho mais leve e menos partículas.":`分辨率稍低，光晕更柔和，粒子更少。`,Alto:`高`,"O rio com tudo o que ele tem.":`完整的河，什么都不少。`,"Opções (Esc)":`选项（Esc）`,Opções:`选项`,"Fechar (Esc)":`关闭（Esc）`,Som:`声音`,"Volume geral":`总音量`,Música:`音乐`,Efeitos:`音效`,"Interface e voz":`界面与语音`,Mudo:`静音`,Gráficos:`画面`,Interface:`界面`,Tamanho:`大小`,"Tamanho da interface":`界面大小`,Idioma:`语言`,"Trocar de idioma recarrega o jogo. O progresso fica salvo.":`切换语言会重新载入游戏，进度已保存。`,Continuar:`继续`,"Sem som":`无声`,"Som ligado":`声音已开启`,"Voltar mesmo? O que não foi guardado se perde.":`真的要返回吗？没保存的内容会丢失。`,"Voltar ao título":`返回标题`,"<kbd>A</kbd><kbd>D</kbd> andar pelo convés · <kbd>E</kbd> usar · <kbd>Tab</kbd> caderno de bordo":`<kbd>A</kbd><kbd>D</kbd> 在甲板上走动 · <kbd>E</kbd> 使用 · <kbd>Tab</kbd> 航海日志`,"<kbd>A</kbd><kbd>D</kbd> escolher o lugar · <kbd>E</kbd> navegar até lá · <kbd>Esc</kbd> voltar ao convés":`<kbd>A</kbd><kbd>D</kbd> 选择地点 · <kbd>E</kbd> 开船前往 · <kbd>Esc</kbd> 回到甲板`,"Dia {dia}":`第{dia}天`,"Caderno de bordo (Tab)":`航海日志（Tab）`,Caderno:`日志`,Tab:`Tab`,"Caderno de bordo":`航海日志`,"Dia {dia} · {turno}":`第{dia}天 · {turno}`,"O que fazer":`要做什么`,"Como jogar":`玩法`,Espécies:`物种`,"O progresso fica salvo.":`你的进度已保存。`,"Sair do jogo":`退出游戏`,"O dia":`一天`,"<b>Manhã e tarde</b>um mergulho em cada turno":`<b>上午和下午</b>每个时段潜一次水`,"<b>No barco</b>o peixe que sobe vai para a despensa":`<b>在船上</b>带上来的鱼进储藏室`,"<b>Noite</b>o Boca do Poço abre e você serve no balcão":`<b>晚上</b>Boca do Poço开门，你在柜台招呼客人`,"<b>Com o ouro</b>mais ar, mais carga e mais fundo":`<b>用金币</b>换更多空气、更大载重、潜得更深`,"No mergulho":`潜水时`,"<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> arrancada":`<kbd>WASD</kbd> 游动 · <kbd>Shift</kbd> 冲刺`,"<kbd>Mouse</kbd> segure para mirar, solte para atirar":`<kbd>鼠标</kbd> 按住瞄准，松开发射`,"<kbd>F</kbd> faca: abre caixote, pega achado":`<kbd>F</kbd> 潜水刀：开木箱、捡宝物`,"<kbd>Tab</kbd> troca a arma · <kbd>C</kbd> carga":`<kbd>Tab</kbd> 切换武器 · <kbd>C</kbd> 收获`,"<kbd>E</kbd> subir no barco ou pela boia":`<kbd>E</kbd> 上船或从浮标上去`,"No restaurante":`在餐馆`,"<kbd>A</kbd><kbd>D</kbd> andar pelo balcão":`<kbd>A</kbd><kbd>D</kbd> 沿柜台走动`,"<kbd>E</kbd> pegar, servir, limpar e socar":`<kbd>E</kbd> 取菜、上菜、清理、捣臼`,"segure <kbd>E</kbd> para encher a cuia de tacacá":`按住<kbd>E</kbd>往葫芦碗里盛tacacá`,Lembranças:`回忆`,"<kbd>A</kbd><kbd>D</kbd> escolher · <kbd>E</kbd> ou <kbd>Enter</kbd> fazer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> ou <kbd>Esc</kbd> fechar":`<kbd>A</kbd><kbd>D</kbd> 选择 · <kbd>E</kbd>或<kbd>Enter</kbd> 执行 · <kbd>C</kbd> 翻页 · <kbd>Tab</kbd>或<kbd>Esc</kbd> 关闭`,"Fama <b>{fama}</b>":`名气 <b>{fama}</b>`,"Despensa <b>{n}</b> peixe":{other:`储藏室 <b>{n}</b> 条鱼`},"<b>{n}</b> de {total} espécies no caderno":`图鉴已收录<b>{n}</b>/{total}种`,"{n} pescado":{other:`已捕{n}条`},"maior: {peso} kg":`最大：{peso}公斤`,"Vive entre {min} e {max} m":`栖息于{min}至{max}米`,"3★ rende {corte}":`3★可得{corte}`,"Encontro anotado":`已记下这次相遇`,"Fama no rio · {grau}":`河上名气 · {grau}`,Canoa:`独木舟`,farinha:`木薯粉`,"<kbd>A</kbd><kbd>D</kbd> andar · <kbd>E</kbd> ou <kbd>espaço</kbd> pegar, servir, limpar e socar · segure para encher a cuia":`<kbd>A</kbd><kbd>D</kbd> 走动 · <kbd>E</kbd>或<kbd>空格</kbd> 取菜、上菜、清理、捣臼 · 按住盛满葫芦碗`,limpar:`清理`,"{n} moeda":{other:`{n}金币`},"hora de abrir o Boca do Poço":`该开Boca do Poço了`,"descer no escuro ou dormir até de manhã":`摸黑下潜，或睡到早上`,"dois mergulhos até a noite":`天黑前还能潜两次`,"último mergulho antes da noite":`天黑前最后一次潜水`,"Primeiro mergulho":`第一次潜水`,"{n} mergulho":{other:`{n}次潜水`},"Melhor mergulho: {moedas} · {vezes}":`最佳潜水：{moedas} · {vezes}`,"no máximo":`已满级`,"Ache esta arma nos caixotes para liberar o projeto: {achadas} de {precisa}.":`在木箱里找到这把武器即可解锁图纸：{achadas}/{precisa}。`,"✓ Levando":`✓ 已携带`,Levar:`携带`,"{n} peça · −{desconto}% de ouro":{other:`{n}个零件 · 金币−{desconto}%`},"O rio está acordando":`河流正在苏醒`,"Ainda dá um mergulho":`还能再潜一次`,"A noite é do Boca do Poço":`夜晚属于Boca do Poço`,"De dia, o poço · de noite, o balcão":`白天下深潭 · 夜里守柜台`,"O Tuca pesca no fundo do poço para abastecer o balcão do <strong>restaurante flutuante</strong> da Dona Naná.":`图卡在深潭底捕鱼，供应娜娜奶奶的<strong>水上餐馆</strong>。`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa enche o balcão da Dona Naná.":`图卡从河里带回的鱼变成夜晚的菜肴，每个好夜晚都让娜娜奶奶的柜台热闹起来。`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa paga um pedaço da dívida do avô.":`图卡从河里带回的鱼就是当晚的菜，每个好夜晚都能还上爷爷的一部分欠债。`,"No barco":`在船上`,Começar:`开始`,"Como o jogo funciona":`游戏流程`,"<b>Mergulhe</b>Pesque e junte achados enquanto o ar durar.":`<b>潜水</b>趁空气还够，捕鱼、捡宝物。`,"<b>Volte ao barco</b>O peixe que sobe vai para a despensa do restaurante.":`<b>回到船上</b>带上来的鱼会进餐馆的储藏室。`,"<b>À noite, abra o Boca do Poço</b>Monte o cardápio e sirva os fregueses no balcão.":`<b>晚上，打开Boca do Poço</b>定好菜单，在柜台招呼客人。`,"<b>Melhore o barco</b>Com o ouro, mais ar, mais carga e mais fundo.":`<b>升级船只</b>用金币换更多空气、更大载重、潜得更深。`,"O dia tem dois mergulhos, um de manhã e um de tarde; à noite o restaurante abre com o que você pescou. A nota da noite e a fama crescem com o capricho no serviço.":`每天潜两次水，上午一次，下午一次；晚上餐馆用你捕到的鱼开张。服务越用心，当晚评分和名气涨得越多。`,"<kbd>WASD</kbd> nadar":`<kbd>WASD</kbd> 游动`,"<kbd>Mouse 1</kbd> segure para mirar, solte para atirar":`<kbd>鼠标左键</kbd> 按住瞄准，松开发射`,"<kbd>Shift</kbd> arrancada (gasta mais ar)":`<kbd>Shift</kbd> 冲刺（更耗气）`,"<kbd>Tab</kbd> arpão · arma · tarrafa · faca":`<kbd>Tab</kbd> 鱼叉 · 武器 · 抛网 · 潜水刀`,"<kbd>F</kbd> faca: abre caixote e caixa de munição, pega achado e arranca minério":`<kbd>F</kbd> 潜水刀：开木箱和弹药箱、捡宝物、撬矿石`,"<kbd>Espaço</kbd> contra peixe forte":`<kbd>空格</kbd> 对付大力鱼`,"<kbd>C</kbd> carga":`<kbd>C</kbd> 收获`,"<kbd>E</kbd> subir (barco ou boia)":`<kbd>E</kbd> 上船（或浮标）`,"<kbd>Q</kbd> apetrecho de defesa: nuvem de urucum ou chamariz de pano":`<kbd>Q</kbd> 防身道具：胭脂树红雾或布偶诱饵`,"<kbd>M</kbd> som":`<kbd>M</kbd> 声音`,"Volte ao barco antes que o ar acabe: o peixe que sobe vai para a cozinha.":`在空气耗尽前回到船上：带上来的鱼会送进厨房。`,"<kbd>E</kbd> ou <kbd>Espaço</kbd> pegar o prato, servir, limpar e socar o pilão":`<kbd>E</kbd>或<kbd>空格</kbd> 取菜、上菜、清理、捣臼`,"Sirva a cada freguês o prato que ele pediu antes que a paciência acabe.":`在客人失去耐心前，把他点的菜端给他。`,"Com controle":`使用手柄`,"<kbd>Analógico esquerdo</kbd> nadar e andar · <kbd>LT</kbd> arrancada":`<kbd>左摇杆</kbd> 游泳和行走 · <kbd>LT</kbd> 冲刺`,"<kbd>RT</kbd> segure para mirar com o <kbd>analógico direito</kbd>, solte para atirar":`<kbd>RT</kbd> 按住并用<kbd>右摇杆</kbd>瞄准，松开发射`,"<kbd>A</kbd> usar · <kbd>B</kbd> voltar · <kbd>X</kbd> faca · <kbd>Y</kbd> troca a arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> apetrecho":`<kbd>A</kbd> 使用 · <kbd>B</kbd> 返回 · <kbd>X</kbd> 潜水刀 · <kbd>Y</kbd> 切换武器 · <kbd>LB</kbd> 收获 · <kbd>R3</kbd> 道具`,Entendi:`明白了`,"Fim do mergulho":`潜水结束`,"Você desmaiou":`你昏过去了`,"Subiu pela boia":`从浮标上来了`,"Você foi puxado para o barco às pressas e só conseguiu segurar a metade mais leve da carga.":`你被匆忙拉回船上，只抓住了较轻的那一半收获。`,"Você voltou de mãos vazias. O rio continua lá.":`你空手而归。河还在那儿。`,"Tudo o que você pescou e achou chegou ao barco.":`你捕到和找到的东西都送上船了。`,"Ficou para trás":`落下的`,"Guardado no barco para construir armas: {itens}":`存到船上用来造武器：{itens}`,"Para a despensa do Boca do Poço (não entra no total): {porcoes}":`送进Boca do Poço储藏室（不计入总计）：{porcoes}`,"<b>{n}</b> porção de {peixe}":{other:`<b>{n}</b>份{peixe}`},"Cortes nobres para a cozinha: {cortes}":`送进厨房的上等部位：{cortes}`,"<b>{n}</b> porção de {corte}":{other:`<b>{n}</b>份{corte}`},'Seu Agenor levou <b>{n}</b> peixe doente: +{ouro}. "Não pergunto de onde veio."':{other:`阿热诺尔收走了 <b>{n}</b> 条病鱼：+{ouro}。“我不问是从哪儿来的。”`},"Novas no caderno de espécies: {peixes}":`物种图鉴新收录：{peixes}`,"Encomendas do flutuante":`水上餐馆的订单`,"Total com encomendas":`含订单总计`,Total:`总计`,"Novo recorde!":`新纪录！`,"Voltar ao barco":`回船上`,"{preco} o prato · {n} porção na despensa":{other:`每份{preco} · 储藏室{n}份`},"Boca do Poço · fama {grau}":`Boca do Poço · 名气 {grau}`,"O cardápio da noite":`今晚的菜单`,"Escolha até {vagas} pratos. Hoje vêm {fregueses} fregueses; o que sobrar volta para a despensa.":`最多选{vagas}道菜。今晚会来{fregueses}位客人；剩下的放回储藏室。`,"Abrir com {n} porção":{other:`带{n}份开张`},"Abrir só com cafezinho":`只卖咖啡开张`,"Equipe · {equipe}":`员工 · {equipe}`,Equipe:`员工`,"A casa":`店面`,"Vender a despensa ao Regatão · {moedas}":`把储藏卖给河上商贩 · {moedas}`,Voltar:`返回`,"Você achou":`你找到了`,"Guardar e continuar":`收好，继续`,"<strong>{ouro}</strong> moedas":`<strong>{ouro}</strong>金币`,"Cada melhoria aparece no flutuante e vale em todas as noites.":`每项改进都会出现在水上餐馆，每晚都生效。`,"Voltar ao cardápio":`回到菜单`,"Contratar · {preco}":`雇用 · {preco}`,"Na noite ✓":`今晚上岗 ✓`,"Pôr na noite":`安排上岗`,"Sem vaga":`没空位`,"diária de {valor}":`日薪{valor}`,"Com a fama {grau} ainda não cabe ajudante atrás do balcão.":`名气为{grau}时，柜台后还站不下帮手。`,"Com a fama {grau} cabe {n} ajudante por noite.":{other:`名气为{grau}时，每晚可安排{n}名帮手。`},"Na fama {grau} abre a primeira vaga.":{other:`名气达到{grau}时，可安排{n}名。`},"A equipe":`员工`,"O contrato se paga uma vez; a diária sai do lucro da noite.":`雇用费只付一次；日薪从当晚的利润里扣。`,"Na noite: <b>{escalados} de {vagas}</b> · diárias de {moedas}":`今晚：<b>{escalados}/{vagas}</b> · 日薪共{moedas}`,"Na noite: <b>{escalados} de {vagas}</b>":`今晚：<b>{escalados}/{vagas}</b>`,hoje:`今天`,"dia {dia}":`第{dia}天`,"De tirar o chapéu":`令人叫绝`,"Casa elogiada":`好评如潮`,"Deu para o gasto":`还过得去`,"Noite atrapalhada":`手忙脚乱`,"Noite para esquecer":`不堪回首`,"{n} freguês foi embora sem comer":{other:`{n}位客人没吃饭就走了`},"{n} prato foi parar na banqueta errada":{other:`{n}道菜上错了座位`},"os pratos demoraram a chegar":`上菜太慢`,"As lamparinas se apagam. Seu Agenor abre o caderno só para somar o que a casa fez.":`油灯熄了。阿热诺尔大叔翻开账本，只是为了算一算店里这一晚的收成。`,"As lamparinas se apagam. Seu Agenor abre o caderno e faz as contas da casa.":`油灯熄了。阿热诺尔大叔翻开账本，算起店里的账。`,"Caderno da casa":`店里的账本`,"Caderno do Regatão":`河上商贩的账本`,"Noite do dia {dia}":`第{dia}天夜里`,"Saiu da cozinha":`出菜`,"{n} prato":{other:`{n}道菜`},"O mais pedido foi o <b>{prato}</b>: {fatia}% do que entrou.":`点得最多的是<b>{prato}</b>：占收入的{fatia}%。`,"Nenhum prato saiu hoje.":`今天一道菜也没卖出。`,"As últimas noites":`最近几晚`,"o que ficou em caixa":`结余`,"A melhor noite que este caderno já viu!":`这本账本见过的最好的一晚！`,"Fama no rio: <b>{grau}</b> <em>subiu!</em>":`河上名气：<b>{grau}</b> <em>提升了！</em>`,"Fama no rio: <b>{grau}</b>":`河上名气：<b>{grau}</b>`,"{ganho} nesta noite, com +{premio} pelo capricho":`今晚{ganho}，其中用心服务奖励+{premio}`,"{ganho} nesta noite":`今晚{ganho}`,"faltam {faltam} para {grau}":`距{grau}还差{faltam}`,"Contas da noite":`今晚账目`,"{n} freguês servido":{other:`服务了{n}位客人`},Pratos:`菜品`,Gorjetas:`小费`,"Despesa da casa":`店面开支`,"Diárias da equipe":`员工日薪`,"Faltou no caixa":`亏空`,"Ficou em caixa":`结余`,"conceito da noite":`今晚评分`,"{nota} de 5":`{nota}/5`,"Ninguém saiu reclamando.":`没有人抱怨着离开。`,"Conferido por <b>Seu Agenor, o Regatão</b>":`核账人：<b>河上商贩阿热诺尔大叔</b>`,"Dormir · amanhã é dia {dia}":`睡觉 · 明天是第{dia}天`,Barco:`船`,Armas:`武器`,"Achar a mesma arma duas vezes nos caixotes libera o projeto. O material do poço fica guardado aqui, e a arma construída desce com você em todo mergulho.":`在木箱里找到同一种武器两次，就能解锁图纸。深潭里的材料存放在这里，造好的武器每次潜水都会跟你下水。`,Zarabatana:`吹箭筒`,"6 dardos com timbó: o peixe dorme e vem vivo":`6支鱼藤毒镖：鱼会睡着，活捉`,"Espingarda de pressão":`气枪`,"6 tiros de três chumbos, para perto":`6发三弹丸霰弹，近距离用`,Balestra:`弩`,"4 setas pesadas, que atravessam":`4支重箭，可穿透`,"A noite da cheia":`涨水的那一夜`,"Na boca do poço mais fundo do rio há um flutuante. Seu Raimundo mergulhava, Dona Naná cozinhava, e não passava barco que não encostasse.":`在河里最深的那口深潭边，有一座水上餐馆。雷蒙多爷爷下水，娜娜奶奶掌勺，路过的船没有一条不靠过来的。`,"Tuca, o neto, voltou da cidade com uma mala e o fôlego do avô. De dia ele desce o poço. De noite, o Boca do Poço abre.":`孙子图卡从城里回来了，带着一只箱子，还有爷爷那样的一口长气。白天他下深潭，晚上Boca do Poço开门。`,"O dia tem dois mergulhos, um de manhã e um de tarde. O peixe que sobe ao barco vira o prato da noite, e cada noite bem servida paga um pedaço da dívida. O rio está esperando.":`每天潜两次水，上午一次，下午一次。捞上船的鱼就是当晚的菜，每招待好一晚，就能还上一部分债。河在等着呢。`,"O Tição":`火炭`,"A volta do avô":`爷爷回来了`,"Cobra-Grande":`大蛇`,"Escama da Cobra-Grande":`大蛇鳞片`,Tuca:`图卡`,"Dona Naná":`娜娜奶奶`,"Seu Agenor, o Regatão":`河上商贩阿热诺尔大叔`,Curimatã:`库里马塔`,Jaci:`雅西`,"Seu Bené":`贝内大叔`,Piaba:`皮亚巴`,"Seu Raimundo":`雷蒙多`,"Seu Takeshi":`武志大叔`,Kauê:`考埃`,"Dona Zefa":`泽法大婶`,"Seu Juvenal":`茹韦纳尔大叔`,Ingrid:`英格丽德`,Tião:`蒂昂`,"Seu Dico":`迪科大叔`,"Dois tucunarés":`两条孔雀鲈`,"Um tambaqui":`一条坦巴基鱼`,"Três piranhas":`三条食人鱼`,"Dois pacus vivos":`两条活帕库鱼`,"Uma arraia":`一条魟鱼`,"Um poraquê":`一条电鳗`,"Um pirarucu":`一条巨骨舌鱼`,"Cinco jaraquis":`五条雅拉基鱼`,"Duas matrinxãs":`两条马特林克鱼`,"Três frutos da mata":`三个野果`,"Dois minérios":`两块矿石`,"Duas conchas":`两枚贝壳`,Pacu:`帕库鱼`,Aracu:`阿拉库鱼`,"Acará-disco":`七彩神仙鱼`,Piranha:`食人鱼`,Tucunaré:`孔雀鲈`,Tambaqui:`坦巴基鱼`,Arraia:`魟鱼`,Traíra:`特拉伊拉鱼`,Sucuri:`森蚺`,Surubim:`虎皮鸭嘴鱼`,Pirarara:`红尾鲶`,Candiru:`牙签鱼`,Poraquê:`电鳗`,"Peixe-cachorro":`吸血鬼鱼`,Pirarucu:`巨骨舌鱼`,Jaú:`雅乌鲶`,Piraíba:`皮拉伊巴鲶`,Aruanã:`银龙鱼`,Jaraqui:`雅拉基鱼`,Matrinxã:`马特林克鱼`,Tamuatá:`塔穆阿塔甲鲶`,"Peixe-boi":`海牛`,Acari:`阿卡里甲鲶`,Mandi:`曼迪鲶`,Ituí:`伊图伊刀鱼`,Jacaré:`凯门鳄`,"A volta":`归来`,"Tu cresceu, menino. E voltou magro. Senta, que conversa de barriga vazia não presta.":`长高了啊，孩子。可也瘦了。坐下，饿着肚子说不了正事。`,"Vó, que caderno é esse em cima do balcão?":`奶奶，柜台上那本账本是什么？`,"É do Seu Agenor, o Regatão. Teu avô comprou fiado nele a vida toda. Agora ele diz que a conta é do tamanho do flutuante.":`是河上商贩阿热诺尔大叔的。你爷爷一辈子都在他那儿赊账。现在他说，这笔账跟整座水上餐馆一样大。`,"Do tamanho do flutuante e mais a canoa, Dona Naná. Mas eu sou homem de paciência: pagando a parcela, eu espero.":`餐馆再搭上那条小船，娜娜奶奶。不过我这人有耐心：按期还款，我就等着。`,"Então a gente paga. Eu trago o peixe do poço, a senhora cozinha.":`那咱们就还。我从深潭里抓鱼，您来做菜。`,"Teu avô dizia a mesma coisa, com essa mesma cara. Anda, abre a casa.":`你爷爷当年也这么说，就是这副表情。去吧，开门营业。`,"O arpão do avô":`爷爷的鱼叉`,"Primeira parcela, contadinha. Quem diria: o balcão voltou a encher.":`第一期，一分不少。谁能想到，柜台又坐满了。`,"Anota aí que pagou, Agenor. De caneta, que lápis teu apaga sozinho.":`记上，我们还了，阿热诺尔。用钢笔记，你的铅笔字会自己没了。`,"Tuca, teu avô perdeu o arpão dele no raso, na última cheia. Ele amarrava as receitas no cabo, para não molhar na canoa.":`图卡，上次涨水时，你爷爷把鱼叉丢在浅水区了。他把菜谱绑在叉柄上，免得在船里弄湿。`,"Receita amarrada em arpão?":`菜谱绑在鱼叉上？`,"Ele pescava pensando no prato. Se tu achar, traz. Tem coisa naquele caderno que nem eu sei fazer.":`他捕鱼时心里就想着做菜。你要是找到了，就带回来。那本子里有些菜连我都不会做。`,"O arpão do avô está em algum canto do raso, fincado no chão.":`爷爷的鱼叉插在浅水区某处的河底。`,"Arraia não se pesca com pressa nem se cozinha com pressa. Leite de coco, coentro do quintal e fogo baixo. Naná diz que não gosta. Naná repete o prato.":`魟鱼急不得：抓不能急，煮也不能急。椰奶、院子里的香菜、小火慢炖。娜娜说她不爱吃。娜娜又添了一盘。`,"Receita nova no Boca do Poço: moqueca de arraia. As arraias que você pescar agora vão para a despensa.":`Boca do Poço新菜谱：魟鱼莫克卡。从现在起，你捕的魟鱼会送进储藏室。`,"As luzes do fundo":`水底的光`,"Parcela paga, Dona Naná. Casa cheia, caderno em dia: assim que eu gosto.":`这期还上了，娜娜奶奶。客满，账也清：我就喜欢这样。`,"Anota e vai embora, Agenor.":`记上就走吧，阿热诺尔。`,"Já vou. Só um aviso de amigo: subiu uma draga pelo rio. Gente de fora, gente de dinheiro. Andam perguntando do poço.":`这就走。就提醒一句：有艘采金船沿河上来了。外地人，有钱人。他们在打听这口深潭。`,"Perguntando o quê?":`打听什么？`,"Quanto ele tem de fundo. E de quem é este flutuante.":`潭有多深。还有这座水上屋是谁的。`,"Teu avô descia de madrugada, sabia? Depois de fechar a casa. Levava a lamparina e dizia que, no escuro, o fundo do poço acendia.":`你爷爷总在凌晨下水，知道吗？等店打烊以后。他提着油灯，说黑暗里潭底会亮起来。`,"Eu achava que era cachaça. Na noite da cheia ele desceu com ela e não voltou.":`我还以为是他喝多了。涨水那晚，他提着灯下去，就再没回来。`,"Então hoje, quando a casa fechar, eu desço.":`那今晚打烊后，我下去。`,"Leva o casaco. E volta, que eu não tenho mais idade para esperar ninguém na beira.":`带上外套。还有，一定要回来，我这把年纪，等不起谁了。`,"A lamparina do avô":`爷爷的油灯`,"A lamparina do avô está no fundo, onde ele descia de madrugada.":`爷爷的油灯在潭底，就在他凌晨下潜的地方。`,"Eles cantam lá embaixo, Naná. Tu não acredita, mas eu vi as luzes. O jacaré velho fugiu do igarapé: a draga revirou o fundo de lá e ele veio parar no nosso poço, com raiva. A draga vem vindo. Hoje eu desço para avisar os do fundo. Se eu demorar, guarda a brasa acesa.":`娜娜，他们在下面唱歌。你不信，可我看见那些光了。那条老凯门鳄逃出了小河：采金船把那里的河底翻了个遍，它一肚子火，跑到我们潭里来了。采金船要来了。今晚我下去提醒水底的那些人。要是我回来晚了，别让炭火熄了。`,"A lamparina agora é tua: a lanterna alcança mais longe. E no caderno, duas receitas novas: acari assado e caldo de mandi.":`油灯现在是你的了：手电照得更远。笔记本里还多了两道菜：烤阿卡里和曼迪鱼汤。`,"O homem da draga":`采金船的人`,"Dona Naná, trouxe uma visita. Gente importante, de fora.":`娜娜奶奶，我带了位客人来。外地来的大人物。`,"Doutor Brandão, minha senhora. Bonito o seu flutuante. Bem na boca do poço.":`布兰当博士，夫人。您这水上屋真漂亮，正好在深潭口上。`,"Se veio comer, senta. Se veio olhar, a vista é de graça.":`来吃饭就坐下。来看看的话，风景不要钱。`,"Vim fazer negócio. Pago o dobro da dívida, à vista. A senhora descansa e eu ancoro a minha draga aqui.":`我是来谈生意的。我付两倍的债，现钱。您歇着，我把采金船停在这儿。`,"Este flutuante não está à venda. Nem pelo dobro, nem pelo triplo.":`这座水上屋不卖。两倍不卖，三倍也不卖。`,"Tudo no rio tem preço, minha senhora. Às vezes quem cobra é o rio.":`河上的一切都有价钱，夫人。有时候，来收账的是河。`,"Vó, de madrugada tem um jacaré enorme rondando a tona. Os olhos parecem brasa.":`奶奶，凌晨有条巨大的凯门鳄在水面附近转悠。眼睛像炭火一样。`,"É o Tição. Teu avô falava dele. Desce com a faca na mão, menino.":`那是火炭。你爷爷说起过它。下去的时候刀别离手，孩子。`,"A faca do avô":`爷爷的刀`,"A faca do avô ficou no meio do poço, onde ele brigou com o Tição.":`爷爷的刀落在深潭中层，就在他和火炭搏斗的地方。`,'Riscado no cabo, com a ponta da própria faca: "O Tição veio da draga. Bati nele três vezes e ele não largou. Se tu achar esta faca, Tuca, é tua. Não vai atrás dele: deixa ele vir, e bate na hora do bote."':`刀柄上用刀尖刻着：“火炭是跟着采金船来的。我砍了它三下，它还是不松口。图卡，要是你找到这把刀，它就是你的了。别去追它：让它来，等它扑过来时再出手。”`,"A faca do avô é tua: o rebate fica mais fácil e o golpe, mais forte.":`爷爷的刀归你了：格挡更容易，出刀也更狠。`,"A porta":`那扇门`,"Dona Naná... preciso contar uma coisa antes que a senhora saiba por outro.":`娜娜奶奶……有件事，我得在您从别人那儿听说之前告诉您。`,"Fala, Agenor. Mas fala de pé, que sentado tu mente melhor.":`说吧，阿热诺尔。站着说，你坐着撒谎更顺口。`,"Eu vendi a dívida do Raimundo para o Doutor Brandão. Ele quer o poço. A draga desce na próxima cheia.":`我把雷蒙多的债卖给了布兰当博士。他要这口深潭。下次涨水，采金船就会下来。`,"O senhor vendeu a gente.":`你把我们卖了。`,"Vendi papel. Achei que era só papel. O Raimundo dizia que no fundo tinha uma porta, e eu ri dele.":`我卖的是一张纸。我以为不过是一张纸。雷蒙多说过潭底有扇门，我还笑他。`,"Sai do meu balcão, Agenor. A despensa tu ainda compra, que eu não sou boba. Mas cafezinho aqui tu não toma mais.":`离开我的柜台，阿热诺尔。存货你照样可以买，我又不傻。但你别想再在这儿喝咖啡了。`,"Uma porta no fundo do poço, vó?":`潭底有扇门，奶奶？`,"Teu avô usava uma pedra verde no pescoço, um sapinho. Dizia que era a chave. Sumiu no dia da cheia, junto com ele.":`你爷爷脖子上挂着一块绿石头，是只小青蛙。他说那是钥匙。涨水那天，它和他一起不见了。`,"O muiraquitã do avô":`爷爷的护身石`,"O muiraquitã do avô está no fundo mais fundo, onde só se chega de madrugada.":`爷爷的护身石在最深的潭底，只有凌晨才去得了。`,'Amarrado no cordão do muiraquitã, um papel dobrado: "A Cobra-Grande guarda o caminho e não deixa a draga passar. A porta abre para quem leva o sapinho. Se a draga descer, os do fundo vão lutar. Eu vou com eles."':`系在护身石绳上的一张折好的纸条：“大蛇守着那条路，不让采金船过去。谁带着小青蛙，门就为谁打开。要是采金船下来，水底的人会去拼。我跟他们一起去。”`,"O muiraquitã é teu. No fundo, a porta dos encantados já te espera.":`护身石归你了。潭底，那扇通往“被施法者”的门正等着你。`,"A cheia":`涨水`,"O rio subiu dois palmos desde ontem. A cheia chegou.":`河水从昨天起涨了两拃。涨水来了。`,"Recado do Doutor Brandão: a draga desce amanhã. Quem estiver no caminho, que saia.":`布兰当博士捎话：采金船明天下来。挡路的，自己让开。`,"Hoje de madrugada eu abro a porta, vó. O Tição vai estar lá.":`今天凌晨我去开那扇门，奶奶。火炭会在那儿。`,"Teu avô disse a mesma coisa, nesta mesma noite. Volta, Tuca. Volta com ele.":`你爷爷就在这样一个晚上，说过一模一样的话。回来，图卡。带着他回来。`,"Tuca! Tem um homem subindo a escada do flutuante. Molhado, de barba branca.":`图卡！有个人正爬上水上屋的梯子。浑身湿透，白胡子。`,"Naná. A brasa ainda está acesa?":`娜娜。炭火还亮着吗？`,"Nunca apagou, velho teimoso. Nunca.":`从来没灭过，你这倔老头。从来没有。`,"Os do fundo me guardaram até alguém abrir a porta. Não imaginei que ia ser o menino.":`水底的人一直护着我，等有人来开门。没想到会是这孩子。`,"A draga afundou, vô. O Tição não volta.":`采金船沉了，爷爷。火炭不会回来了。`,"E o Doutor Brandão sumiu rio abaixo. Com ele, o contrato. A dívida... a dívida não existe mais.":`布兰当博士顺流跑了，合同也跟他一起没了。那笔债……那笔债不存在了。`,"Então senta, Raimundo. E tu também, Agenor. Hoje o cafezinho é por conta da casa.":`那就坐下吧，雷蒙多。你也坐，阿热诺尔。今天的咖啡算店里请。`,"Doutor Brandão":`布兰当博士`,"Cilindro de ar":`气瓶`,"Caixa de munição":`弹药箱`,"Anel de ouro":`金戒指`,Muiraquitã:`蛙形玉符`,"Baú perdido":`失落的宝箱`,"Cuia de prata":`银葫芦碗`,"Brinco de esmeralda":`祖母绿耳环`,"Garrafa antiga":`古董瓶`,"Moeda antiga":`古钱币`,"Pérola de rio":`河珍珠`,Diamante:`钻石`,Opala:`蛋白石`,Ametista:`紫水晶`,Estanho:`锡`,Ferro:`铁`,Cobre:`铜`,"Cacho de açaí":`巴西莓串`,"Ouriço de castanha":`巴西栗果壳`,"Concha de mexilhão":`贻贝壳`,"Casca de caramujo":`螺壳`,"Fragmento de arpão":`鱼叉碎片`,Sucata:`废铁`,"Caco de vidro":`碎玻璃`,Corda:`绳子`,Madeira:`木头`,"Tanque de ar":`气罐`,"Mais ar para ficar mais tempo lá embaixo.":`更多空气，在水下待得更久。`,"de ar":`空气`,Traje:`潜水服`,"Aguenta a pressão até mais fundo. Passou do limite, o ar acaba bem mais rápido.":`能承受更深处的水压。超过极限，空气会消耗得快得多。`,m:`m`,Samburá:`鱼篓`,"Cabe mais peixe e mais achado antes de pesar.":`能装更多鱼和宝物，不嫌重。`,kg:`kg`,"Tiro mais forte: peixe resistente vem com menos disparos.":`射击更有力：耐打的鱼少几发就能拿下。`,"de dano":`伤害`,"Golpe mais forte, para o que chega perto demais.":`挥刀更有力，对付靠得太近的家伙。`,Tarrafa:`抛网`,"Mais lances de rede por mergulho. Peixe de tarrafa vem vivo e vale mais.":`每次潜水能多撒几网。网到的鱼是活的，更值钱。`,lances:`网`,"Boia de resgate":`救援浮标`,"Leva o peixe grande direto para o barco, sem pesar no samburá.":`把大鱼直接送上船，不占鱼篓的重量。`,"por mergulho":`每次潜水`,"Ponta de aço":`钢叉头`,"+1 de dano":`伤害+1`,"Ponta farpada":`倒钩叉头`,"não solta: aperte Espaço na hora certa":`不脱钩：看准时机按空格`,"Ponta elétrica":`电击叉头`,"+1 de dano · atordoa o peixe · alterne A e D":`伤害+1 · 电晕鱼 · 交替按A和D`,"Ponta de timbó":`鱼藤叉头`,"adormece o peixe: ele vem vivo · siga as setas":`让鱼睡着：活捉 · 按方向键提示`,"Ponta de curare":`箭毒叉头`,"veneno: tira vida aos poucos · aperte bem rápido":`毒：慢慢扣血 · 快速连按`,"O que tem de bom hoje?":`今天有啥好吃的？`,"Estou varado de fome...":`饿得前胸贴后背……`,"Hum, que cheiro!":`嗯，真香！`,"Capricha aí!":`做好点儿啊！`,"Isso é que é comida!":`这才叫吃饭！`,"Hum... que beleza.":`嗯……太棒了。`,"Égua, que tá bom demais!":`哇，这也太好吃了吧！`,"Cheirou, chegou!":`闻着香就来了！`,"Ô garçom!":`喂，服务员！`,"Vai demorar?":`还要多久？`,"Esqueceram de mim?":`把我忘了吗？`,"Faz tempo que eu não comia um {prato} assim. Volto amanhã e trago a família.":`好久没吃过这么地道的{prato}了。明天我带全家来。`,"Mal sentei e o prato já estava na minha frente. Isso é que é casa bem tocada!":`刚坐下菜就上来了。这店经营得真好！`,"O {prato} da Dona Naná continua o melhor deste rio. Podem escrever.":`娜娜奶奶的{prato}还是这条河上最好的。我敢打包票。`,"Vim de longe só pelo {prato}. Valeu cada remada.":`我大老远就为这口{prato}来的。每一桨都值了。`,"A comida é boa, mas hoje a espera foi comprida.":`菜是好吃，可今天等得太久了。`,"Gostei do {prato}. Só achei o balcão meio atrapalhado.":`{prato}不错。就是柜台有点手忙脚乱。`,"Dá para voltar. Com mais ligeireza no serviço, eu voltava toda noite.":`还会再来。上菜再快点的话，我天天晚上都来。`,"Esperei, esperei e fui embora de barriga vazia. Assim não dá.":`等了又等，最后饿着肚子走了。这可不行。`,"Vi gente levantando sem comer. A casa precisa de mais braço no balcão.":`看见有人没吃就起身走了。柜台得多添人手。`,"Me trouxeram o prato do vizinho. Hoje não foi a noite de vocês.":`给我上了邻座的菜。今晚你们状态不行啊。`,"Calado e atento: limpa a banqueta antes de você notar que sujou.":`话少眼尖：你还没发现凳子脏，他就擦好了。`,"Soca o pilão cantando: a farinha não acaba mais.":`边唱边捣臼：木薯粉永远用不完。`,"Devagar e certeiro: nunca erra a marca da cuia.":`慢而准：葫芦碗从不盛错线。`,"Ligeira no balcão: pega o prato pronto e leva a quem pediu.":`柜台上手脚麻利：取了菜就送到点菜的人面前。`,"Fogão de duas bocas":`双灶炉`,"A cozinha prepara cada prato mais rápido.":`厨房做每道菜都更快。`,"s por prato":`秒/道`,"Banquetas estofadas":`软垫高凳`,"Sentado no macio, o freguês espera mais antes de desistir.":`坐得舒服，客人能多等一会儿。`,"s de paciência":`秒耐心`,"Pilão grande":`大捣臼`,"Cabe mais farinha antes de precisar socar de novo.":`能装更多木薯粉，不用老是重捣。`,"de farinha":`木薯粉`,"Lamparinas e flores":`油灯和鲜花`,"Casa bonita: mais fregueses deixam gorjeta.":`店面漂亮：更多客人留小费。`,"% dão gorjeta":`%给小费`,"Placa iluminada":`灯光招牌`,"A casa se vê de longe: vêm mais fregueses por noite.":`远远就能看见店：每晚来的客人更多。`,"fregueses a mais":`位额外客人`,Cafezinho:`小杯咖啡`,"Costela de tambaqui":`坦巴基鱼排骨`,"Filé de tucunaré":`孔雀鲈鱼排`,"Ventrecha de pirarucu":`巨骨舌鱼腹肉`,Rabeta:`长尾船`,Voadeira:`快艇`,Batelão:`驳船`,Recreio:`客船`,Gaiola:`大客轮`,"Peixe frito":`炸鱼`,"Caldo de piranha":`食人鱼汤`,"Tucunaré na brasa":`炭烤孔雀鲈`,"Tambaqui assado":`烤坦巴基鱼`,Caldeirada:`卡尔代拉达鱼锅`,"Pirarucu de casaca":`卡萨卡巨骨舌鱼`,"Aruanã assada na folha":`叶包烤银龙鱼`,"Moqueca de arraia":`魟鱼莫克卡`,"Acari assado":`烤阿卡里`,"Caldo de mandi":`曼迪鱼汤`,"Costela de tambaqui assada":`烤坦巴基鱼排骨`,"Filé de tucunaré no tucupi":`图库皮酱孔雀鲈鱼排`},a={"Na boca do poço mais fundo do rio tem um flutuante. É o Boca do Poço, a nossa casa e o nosso restaurante.":`У самого глубокого омута на реке стоит плавучий ресторан. Это Boca do Poço — наш дом и наш ресторан.`,"O meu Raimundo mergulhava e trazia o peixe. Eu cozinhava. De noite, não passava barco que não encostasse.":`Мой Раймундо нырял и приносил рыбу. Я готовила. А по ночам ни одна лодка не проплывала мимо, не причалив.`,"Ele dizia que, de madrugada, o fundo do poço acendia. Eu achava que era conversa de pescador.":`Он говорил, что перед рассветом дно омута светится. Я думала, это рыбацкие байки.`,"Numa noite de cheia, ele desceu com a lamparina e não voltou.":`В одну паводковую ночь он спустился с лампой и не вернулся.`,"Ficaram a brasa acesa, o balcão vazio e uma dívida no caderno do Seu Agenor, o Regatão. Do tamanho do flutuante.":`Остались тлеющие угли, пустой прилавок и долг в тетради Агенора, речного торговца. Величиной с весь наш ресторан.`,"Foi aí que o Tuca, nosso neto, voltou da cidade. Veio me ajudar a tocar o restaurante.":`Тогда-то наш внук Тука и вернулся из города. Приехал помогать мне вести ресторан.`,"Sem peixe não tem prato. Então, todo dia, ele desce o poço e traz o pescado. De noite, eu cozinho e ele serve. Cada noite boa paga um pedaço da dívida.":`Нет рыбы — нет блюда. Поэтому каждый день он ныряет в омут и приносит улов. Ночью я готовлю, а он подаёт. Каждая добрая ночь гасит кусочек долга.`,"E lá embaixo, o rio ainda guarda o que aconteceu com o Raimundo.":`А там, на глубине, река всё ещё хранит то, что случилось с Раймундо.`,"Saco de urucum":`Мешочек уруку`,"Chamariz de pano":`Тряпичная приманка`,"Rondando você":`Кружит рядом`,"Vai dar o bote: rebata com a faca!":`Сейчас бросится: отбей ножом!`,"Rebata agora!":`Отбивай!`,"Tonto: arpão e faca agora!":`Оглушён: гарпун и нож — сейчас!`,"Ela está acordando…":`Змей просыпается…`,"Vai dar o bote: saia da frente!":`Сейчас бросится: уйди с дороги!`,"Saia da frente!":`Уйди с дороги!`,"Boca aberta: atire agora!":`Пасть открыта: стреляй!`,"Cuidado com a cauda!":`Берегись хвоста!`,"Ela desistiu de você":`Змей отступил`,"Amanheceu: dia {dia}":`Рассвет: день {dia}`,"A tarde chegou":`Уже полдень`,"Anoiteceu: o Boca do Poço pode abrir":`Стемнело: Boca do Poço можно открывать`,"Peixe forte! Aperte espaço (ou clique) bem rápido para cansá-lo.":`Сильная рыба! Жми Пробел (или кликай) очень быстро, чтобы её измотать.`,"Peixe forte! Alterne A e D bem rápido.":`Сильная рыба! Быстро чередуй A и D.`,"Peixe forte! Aperte as setas na ordem, antes que o tempo acabe.":`Сильная рыба! Жми стрелки по порядку, пока не вышло время.`,"Peixe forte! Aperte espaço quando o marcador passar no verde.":`Сильная рыба! Жми Пробел, когда метка на зелёном.`,"Levar o barco até o Boca do Poço, que abre agora.":`Плыть к Boca do Poço — он открывается.`,"na escada":`у трапа`,"Levar o barco pelo rio. O Boca do Poço abre à noite.":`Плыть по реке. Boca do Poço открывается ночью.`,"no leme":`у штурвала`,"Melhorar o tanque, o traje, a carga e as armas.":`Улучшить баллон, костюм, груз и оружие.`,"na bancada":`у верстака`,"Deixar o turno passar sem mergulhar.":`Пропустить смену без погружения.`,"no banco da proa":`на скамье у носа`,"Antes do primeiro mergulho":`Перед первым погружением`,"De volta ao barco":`Снова в лодке`,"Barco ancorado no igapó. O mergulho daqui é entre as árvores.":`Лодка стоит в игапо. Отсюда ныряют среди деревьев.`,"Barco ancorado no poço.":`Лодка стоит у омута.`,"{destino}: {motivo}":`{destino}: {motivo}`,"{destino} · {rotulo}":`{destino} · {rotulo}`,Final:`Финал`,"Capítulo {numero}":`Глава {numero}`,"Abrir o cardápio":`Открыть меню`,"{escalados} de {vagas} na noite":`{escalados} из {vagas} на смене`,limpeza:`уборка`,pilão:`ступа`,tacacá:`такака`,"serve os pratos":`подаёт блюда`,"Um freguês":`Гость`,"Primeira noite":`Первая ночь`,"Primeira noite · {numero} de {total}":`Первая ночь · {numero} из {total}`,"Cansei de esperar!":`Надоело ждать!`,"Um freguês cansou de esperar e foi embora":`Гость устал ждать и ушёл`,"{prato} acabou":`Закончилось: {prato}`,"Um prato":`Блюдо`,"Tacacá na marca: ele paga 30% a mais":`Такака точно до отметки: гость платит на 30% больше`,"Passou da marca: derramou o tacacá":`Перелил: такака пролилась`,"Faltou tacacá na cuia":`Недолил такаку в калебасу`,"Acabou a farinha: a cozinha parou. Soque o pilão!":`Мука кончилась: кухня встала. Толки в ступе!`,"Um peixe-boi! Ele deixou você chegar perto. Presente do igapó: {ouro} moedas.":`Ламантин! Он подпустил тебя близко. Подарок игапо: {ouro} монет.`,"Encomenda do flutuante: {encomendas}":`Заказ ресторана: {encomendas}`,"A porta dos encantados te espera no fundo. O Tição também.":`Внизу тебя ждёт дверь заколдованных. И Головешка тоже.`,"Tutorial concluído. Agora abra o Boca do Poço e sirva o que pescou!":`Обучение пройдено. Теперь открывай Boca do Poço и подавай свой улов!`,"Primeiro mergulho · {numero} de {total}":`Первое погружение · {numero} из {total}`,"Carga cheia! Volte ao barco.":`Груз полон! Возвращайся в лодку.`,"Encomenda cumprida: {encomenda} (+{premio})":`Заказ выполнен: {encomenda} (+{premio})`,"Soltou {nome}":`Выброшено: {nome}`,"Espécie nova! {peixe}":`Новый вид! {peixe}`,"Espécie nova no caderno: {peixe} · +{moedas} moedas":`Новый вид в тетради: {peixe} · +{moedas} монет`,"Abatido!":`Готово!`,"Falta {n}":{one:`Осталось {n}`,few:`Осталось {n}`,many:`Осталось {n}`,other:`Осталось {n}`},"Rebateu!":`Отбил!`,"O Tição está tonto: agora o arpão e a faca ferem!":`Головешка оглушён: теперь гарпун и нож его ранят!`,"A porta dos encantados":`Дверь заколдованных`,"O Tição afunda na escuridão e não volta. A porta se abre devagar, e a água do fundo acende como o avô dizia: luzes que cantam. Lá em cima, um estrondo: a draga do Doutor Brandão adernou e foi ao fundo, longe do poço. Uma voz conhecida chama o teu nome.":`Головешка уходит во тьму и не возвращается. Дверь медленно открывается, и вода на дне загорается, как говорил дед: огни, которые поют. Наверху грохот: драга Доктора Брандана накренилась и пошла ко дну, далеко от омута. Знакомый голос зовёт тебя по имени.`,"Presente dos encantados: {ouro} moedas. Volte ao balcão: tem alguém esperando.":`Подарок заколдованных: {ouro} монет. Возвращайся к стойке: тебя кое-кто ждёт.`,"Boia de resgate: {peixe} {marca} a caminho do barco":`Спасательный буй: {peixe} {marca} плывёт к лодке`,"{peixe} {marca} · {peso} kg":`{peixe} {marca} · {peso} кг`,"Este {peixe} está doente: Dona Naná não vai cozinhar.":`Этот {peixe} больной: Дона Нана не станет его готовить.`,"O couro do jacaré não fura. Só o rebate de faca o afasta.":`Шкуру каймана не пробить. Отогнать его можно только отбивом ножом.`,"O couro dela não fura. Espere o bote: cansada, ela abre a boca.":`Его шкуру не пробить. Дождись броска: устав, он открывает пасть.`,"A Cobra-Grande se recolheu e deixou uma escama: +{valor}":`Великий Змей ушёл в глубину и оставил чешую: +{valor}`,"Uma posta de {peixe} · +{valor}":{one:`{n} кусок ({peixe}) · +{valor}`,few:`{n} куска ({peixe}) · +{valor}`,many:`{n} кусков ({peixe}) · +{valor}`,other:`{n} куска ({peixe}) · +{valor}`},"Tanque cheio: o cilindro fica aí para quando faltar ar.":`Баллон полон: запасной пусть лежит, пока не кончится воздух.`,"+{ar} de ar":`Воздух +{ar}`,"Já leva {caixas} caixas de munição guardadas: esta fica para depois.":`Коробок с зарядами в запасе уже: {caixas}. Эта подождёт.`,"{arma}: +{tiros} de munição":`{arma}: заряды +{tiros}`,"+{tiros} munição":`Заряды +{tiros}`,"Caixa de munição guardada ({caixas}): entra quando a arma esvaziar.":`Коробка зарядов в запасе ({caixas}): пойдёт в ход, когда оружие опустеет.`,"Caixa de munição guardada ({caixas}): serve para a arma que você achar num caixote.":`Коробка зарядов в запасе ({caixas}): для оружия, которое найдёшь в ящике.`,"Caixa guardada":`Коробка в запасе`,"{item} para o barco":`{item} — в лодку`,"Peças de {arma} para o Barco (+1)":`Детали: {arma} — на лодку (+1)`,"Projeto liberado: {arma}. Dá para construir no Barco.":`Чертёж открыт: {arma}. Собрать можно в «Лодке».`,"{apetrecho} no cinto · {tecla} para usar":`{apetrecho} на поясе · {tecla} — использовать`,"Tarrafa: +{lances} lances":`Накидная сеть: броски +{lances}`,"+{lances} lances":`Броски +{lances}`,"Punhado de moedas":`Горсть монет`,"Moedas +{valor}":`Монеты +{valor}`,"Boia de resgate: leva um peixe grande direto para o barco":`Спасательный буй: отправляет крупную рыбу прямо в лодку`,"+1 boia":`+1 буй`,"Nuvem de urucum: os bichos perderam você de vista":`Облако уруку: звери потеряли тебя из виду`,"Chamariz solto: os bichos vão atrás dele":`Приманка выпущена: звери плывут к ней`,"O Tição levou {peixe} da sua carga!":`Головешка утащил из улова: {peixe}!`,"{bicho} enrolou você! Aperte espaço bem rápido para se soltar.":`{bicho} держит тебя! Быстро жми Пробел, чтобы вырваться.`,"{bicho} investiu!":`{bicho} атакует!`,"O veneno derrubou o peixe: ele fica boiando e vale 1 estrela.":`Яд свалил рыбу: она всплывает и стоит 1 звезду.`,"{bicho} bateu na pedra e ficou tonta!":`{bicho} врезалась в камень и оглушена!`,"Ferroada de arraia!":`Укол ската!`,"A Cobra-Grande acordou!":`Великий Змей проснулся!`,"O bote da Cobra-Grande pegou você!":`Великий Змей достал тебя броском!`,"A cauda dela pegou você!":`Тебя задело хвостом!`,"Ela cansou e abriu a boca: atire na cabeça agora!":`Змей устал и открыл пасть: стреляй в голову!`,"A Cobra-Grande voltou a dormir. O que ela perdeu de vida, continua perdido.":`Великий Змей снова уснул. Потерянное здоровье он не вернёт.`,"O Tição saiu da porta!":`Головешка вышел из двери!`,"O bote do Tição pegou você!":`Бросок Головешки достал тебя!`,"O Tição voltou para a porta. O que ele perdeu de vida, continua perdido.":`Головешка вернулся к двери. Потерянное здоровье он не вернёт.`,"O boto achou um caixote: vá atrás dele!":`Речной дельфин нашёл ящик: плыви за ним!`,"Dormiu!":`Спит!`,"Peixe grande demais para a linha: chegue perto para mandá-lo de boia ao barco.":`Рыба слишком крупная для линя: подплыви и отправь её буем в лодку.`,"Peixe grande demais para a linha: chegue perto para recolher.":`Рыба слишком крупная для линя: подплыви и забери.`,"Fisgou!":`Зацепил!`,"Atordoado!":`Оглушение!`,Envenenado:`Отравление`,"Cansou!":`Без сил!`,"A linha cedeu — o peixe escapou!":`Линь не выдержал — рыба ушла!`,"Você se soltou!":`Ты вырвался!`,"{bicho} cansou e soltou você.":`{bicho} выдыхается и отпускает тебя.`,"{arma}: a caixa guardada entrou, +{tiros} de munição":`{arma}: в ход пошла запасная коробка, заряды +{tiros}`,"{arma} sem munição: ficou para trás.":`{arma}: заряды кончились, оружие брошено.`,"Adormecido, o peixe fica parado: chegue perto para recolher. Vem vivo, com 3 estrelas.":`Уснувшая рыба не двигается: подплыви и забери. Она живая — 3 звезды.`,"Grogue! Mais um dardo":`Шатается! Ещё дротик`,"Abatido a tiro, o peixe fica boiando: chegue perto para recolher. Vale 1 estrela.":`Подстреленная рыба всплывает: подплыви и забери. Стоит 1 звезду.`,"{presos} na rede!":`В сети: {presos}!`,"Forte demais para a tarrafa: esse é no arpão.":`Сеть такую не удержит: тут нужен гарпун.`,Zzz:`Zzz`,"Choque do poraquê!":`Разряд электрического угря!`,"Bolsão de ar: tanque cheio":`Воздушный карман: баллон полон`,"Tem alguma coisa brilhando no chão, aqui perto.":`Где-то рядом на дне что-то блестит.`,Tição:`Головешка`,"Pouco ar! Volte ao barco.":`Мало воздуха! Возвращайся в лодку.`,"Fundo demais para este traje ({limite} m): o ar acaba {fator}× mais rápido. No barco tem um melhor.":`Слишком глубоко для этого костюма ({limite} м): расход воздуха ×{fator}. В лодке есть получше.`,"Subir no barco":`Подняться в лодку`,"Subir pela boia":`Подняться по бую`,"Abrir o caixote":`Открыть ящик`,"Arrancar o minério com a faca":`Отбить руду ножом`,"Tirar postas com a faca":`Нарезать куски ножом`,"Boca do Poço":`Boca do Poço`,"PEIXE NA BRASA  •  TACACÁ":`РЫБА НА УГЛЯХ  •  ТАКАКА`,HOJE:`СЕГОДНЯ`,"peixe fresco":`свежая рыба`,"{nome} (doente)":`{nome} (больной)`,"Posta de {peixe}":`Кусок: {peixe}`,Leme:`Штурвал`,Bancada:`Верстак`,Escada:`Трап`,"Banco da proa":`Скамья на носу`,"Mapa do rio":`Карта реки`,Equipamento:`Снаряжение`,"Descer de madrugada":`Нырнуть до рассвета`,Mergulhar:`Нырнуть`,"O rio descansa à noite":`Ночью река спит`,"Dormir sem abrir a casa":`Спать, не открывая ресторан`,"Dormir até de manhã":`Спать до утра`,"Descansar até a tarde":`Отдохнуть до полудня`,"Descansar até a noite":`Отдохнуть до ночи`,Madrugada:`Предрассветный час`,Manhã:`Утро`,Tarde:`День`,Noite:`Ночь`,"Pasta devagar entre as raízes do igapó. Deixou o Tuca chegar perto e não teve medo.":`Неторопливо пасётся среди корней игапо. Подпустил Туку близко и не испугался.`,peixe:`рыба`,"Descer ao igapó e pescar. Gasta este turno.":`Нырнуть в игапо и рыбачить. Займёт эту смену.`,"Madrugada do dia {dia}: o igapó está escuro":`День {dia}, до рассвета: в игапо темно`,Galhada:`Коряги`,"Ar preso entre as raízes: entre nele para encher o tanque.":`Воздух между корнями: заплыви туда, чтобы наполнить баллон.`,"Você no igapó · barco no alto · pontos claros: bolsões de ar":`Ты в игапо · лодка наверху · светлые точки: воздушные карманы`,"Descer ao poço e pescar. Gasta este turno.":`Нырнуть в омут и рыбачить. Займёт эту смену.`,"Madrugada do dia {dia}: o poço está escuro":`День {dia}, до рассвета: в омуте темно`,Paredões:`Скалы`,"Ar preso no teto da gruta: entre nele para encher o tanque.":`Воздух под сводом пещеры: заплыви туда, чтобы наполнить баллон.`,"Você no poço · barco no alto · pontos claros: bolsões de ar":`Ты в омуте · лодка наверху · светлые точки: воздушные карманы`,"Poço do Raimundo":`Омут Раймундо`,Igapó:`Игапо (затопленный лес)`,"Voltar ao convés":`На палубу`,"Ancorar no poço":`Встать на якорь у омута`,"Ancorar no igapó":`Встать на якорь в игапо`,"Abrir o Boca do Poço":`Открыть Boca do Poço`,"Abre à noite":`Открыт ночью`,"Nade para o fundo":`Плыви на глубину`,"Desça alguns metros. Segure Shift para arrancar, mas gasta mais ar.":`Опустись на несколько метров. Зажми Shift для рывка, но так уходит больше воздуха.`,"O ar é a sua vida":`Воздух — это жизнь`,"Este medidor é o ar do tanque. Ele cai com o tempo, mais rápido no fundo e a cada ferida.":`Этот датчик — воздух в баллоне. Он убывает со временем, быстрее на глубине и с каждой раной.`,"Se o ar acabar, você desmaia, é puxado de volta ao barco e perde metade do pescado. Volte antes!":`Если воздух кончится, ты потеряешь сознание, тебя вытащат на лодку, и половина улова пропадёт. Возвращайся заранее!`,"Pesque um peixe":`Поймай рыбу`,Mouse:`Мышь`,"Segure o botão do mouse para mirar e solte para atirar. Peixe forte: aperte Espaço para cansá-lo.":`Удерживай кнопку мыши, чтобы целиться, и отпусти, чтобы выстрелить. Сильная рыба: нажми Пробел, чтобы утомить её.`,"O peso da carga":`Вес груза`,"A barra mostra o peso que você leva e o máximo que aguenta. Cheia, não cabe mais nada.":`Полоса показывает, сколько ты несёшь и сколько можешь унести. Когда она полна, больше ничего не влезет.`,"Aperte C para ver a carga e solte o peixe que vale menos. Na bancada do barco dá para aumentar a capacidade.":`Нажми C, чтобы увидеть груз, и выбрось рыбу подешевле. На верстаке лодки можно увеличить вместимость.`,"Abra e pegue com a faca":`Открывай и бери ножом`,"Perto de um caixote, de uma caixa ou de um achado, aperte F.":`Рядом с ящиком, коробкой или находкой жми F.`,"Volte ao barco":`Вернись в лодку`,"Suba até o barco (ou uma boia) e aperte E. O peixe que sobe vai para a cozinha.":`Всплыви к лодке (или к бую) и жми E. Поднятая рыба идёт на кухню.`,"Metade do ar. Vá pensando na volta.":`Половина воздуха. Пора думать о возвращении.`,"Só um quarto do ar! Volte ao barco ou ache um bolsão de ar.":`Осталась всего четверть воздуха! Вернись на лодку или найди воздушный карман.`,"Por que o Tuca mergulha":`Почему Тука ныряет`,"Meu neto, sem peixe não tem prato. De dia você desce o poço e traz o pescado; de noite a gente abre o Boca do Poço, e cada noite boa paga um pedaço da dívida do seu avô.":`Внучок, нет рыбы — нет блюда. Днём ты ныряешь в омут и приносишь улов; ночью мы открываем Boca do Poço, и каждая добрая ночь гасит кусочек долга твоего деда.`,"O barco":`Лодка`,"Ande pelo convés com A e D e aperte E em cima de um ponto.":`Ходи по палубе клавишами A и D и нажимай E на нужном месте.`,"leva o barco pelo rio; de noite, até o Boca do Poço":`ведёт лодку по реке; ночью — до Boca do Poço`,"melhora o tanque, o traje, a carga e as armas":`улучшает баллон, костюм, груз и оружие`,"desce ao poço para pescar":`спускается в омут за рыбой`,"descansa e deixa o turno passar":`отдыхает и пропускает смену`,"O caderno de bordo":`Бортовой журнал`,'Aperte Tab para abrir o caderno. Na aba "Espécies" ficam os peixes que você já pescou e onde cada um vive.':`Нажми Tab, чтобы открыть журнал. На вкладке «Виды» — рыбы, которых ты уже поймал, и где каждая живёт.`,"A primeira noite":`Первая ночь`,"A e D andam pelo balcão. Os fregueses chegam, pedem, comem e pagam: cada prato servido vira moeda.":`A и D двигают тебя вдоль прилавка. Гости приходят, заказывают, едят и платят: каждое поданное блюдо превращается в монеты.`,"O pedido":`Заказ`,"O balão em cima do freguês mostra o prato que ele quer.":`Пузырь над гостем показывает блюдо, которое он хочет.`,"O passa-prato":`Раздача`,"Os pratos saem prontos aqui. Vá até o passa-prato e aperte E para pegar.":`Готовые блюда выходят здесь. Подойди к раздаче и нажми E, чтобы взять.`,"Entregue o prato":`Подай блюдо`,"Leve o prato até quem pediu e aperte E na frente dele.":`Отнеси блюдо тому, кто заказал, и нажми E перед ним.`,"A louça":`Посуда`,"Quem comeu deixa a louça no balcão. Aperte E em cima dela para limpar o lugar para o próximo freguês.":`Поевший гость оставляет посуду на прилавке. Нажми E на ней, чтобы освободить место для следующего гостя.`,"O tacacá":`Такака`,"Tacacá se serve na hora: segure E para encher a cuia e solte na marca.":`Такака подают сразу: удерживай E, чтобы наполнить калебасу, и отпусти на отметке.`,"Quem espera, cansa":`Кто ждёт — устаёт`,"Quem espera demais vai embora sem pagar, e a fama cai. Sirva primeiro quem chegou antes.":`Кто ждёт слишком долго, уходит, не заплатив, и слава падает. Сначала обслужи тех, кто пришёл раньше.`,"O caderno do Regatão":`Тетрадь речного торговца`,"Fechada a casa, o Regatão anota a noite: o que vendeu, o que gastou e a fama. O lucro de cada noite boa paga um pedaço da dívida do avô.":`Когда дом закрыт, речной торговец записывает ночь: что продано, что потрачено и какая слава. Прибыль каждой доброй ночи гасит кусочек дедова долга.`,Pular:`Пропустить`,Raso:`Отмель`,Abismo:`Бездна`,Espaço:`Пробел`,"{distancia} m":`{distancia} м`,"Liga e desliga o som (tecla M)":`Вкл./выкл. звук (клавиша M)`,Volume:`Громкость`,"Ar no tanque":`Воздух в баллоне`,"{metros} m · {faixa}":`{metros} м · {faixa}`,"pressão!":`давление!`,"{peso}/{capacidade} kg":`{peso}/{capacidade} кг`,"Ver o que você pegou (tecla C)":`Что у тебя с собой (клавиша C)`,Carga:`Груз`,"{peso} kg · {valor} moedas":`{peso} кг · монет: {valor}`,Arpão:`Гарпун`,"Mouse 1":`ЛКМ`,"Tarrafa: traz vivos os peixes pequenos":`Накидная сеть: ловит мелкую рыбу живьём`,Faca:`Нож`,"Lanterna (acende sozinha no escuro)":`Фонарь (сам включается в темноте)`,"<kbd>Tab</kbd> troca":`<kbd>Tab</kbd> смена`,"<kbd>WASD</kbd> nada · <kbd>Shift</kbd> arrancada · <kbd>Mouse 1</kbd> segure para mirar, solte para atirar · <kbd>Tab</kbd> troca a arma · <kbd>F</kbd> faca · <kbd>C</kbd> carga · <kbd>Q</kbd> apetrecho":`<kbd>WASD</kbd> плыть · <kbd>Shift</kbd> рывок · <kbd>ЛКМ</kbd> зажми — прицел, отпусти — выстрел · <kbd>Tab</kbd> смена оружия · <kbd>F</kbd> нож · <kbd>C</kbd> груз · <kbd>Q</kbd> снаряжение`,"Pular o tutorial":`Пропустить обучение`,pular:`пропустить`,"Nada pescado ainda":`Пока ничего не поймано`,"{peso} kg":`{peso} кг`,"Soltar um (libera o peso)":`Выбросить (освободит вес)`,"Arpão · {ponta}":`Гарпун · {ponta}`,"{arma} (achada num caixote: vale só neste mergulho)":`{arma} (из ящика: только на это погружение)`,"Arpão sem ponta":`Гарпун без наконечника`,"{ponta} · tarrafa {lances} · boias {boias} · {arma} {municao}":`{ponta} · сеть {lances} · буи {boias} · {arma} {municao}`,"{ponta} · tarrafa {lances} · boias {boias}":`{ponta} · сеть {lances} · буи {boias}`,Baixo:`Низкое`,"Para computador fraco: sem brilho nas luzes e menos partículas.":`Для слабых компьютеров: без свечения у огней и с меньшим числом частиц.`,Médio:`Среднее`,"Resolução um pouco menor, brilho mais leve e menos partículas.":`Разрешение чуть ниже, свечение мягче, частиц меньше.`,Alto:`Высокое`,"O rio com tudo o que ele tem.":`Река со всем, что в ней есть.`,"Opções (Esc)":`Настройки (Esc)`,Opções:`Настройки`,"Fechar (Esc)":`Закрыть (Esc)`,Som:`Звук`,"Volume geral":`Общая громкость`,Música:`Музыка`,Efeitos:`Эффекты`,"Interface e voz":`Интерфейс и голос`,Mudo:`Без звука`,Gráficos:`Графика`,Interface:`Интерфейс`,Tamanho:`Размер`,"Tamanho da interface":`Размер интерфейса`,Idioma:`Язык`,"Trocar de idioma recarrega o jogo. O progresso fica salvo.":`Смена языка перезапускает игру. Прогресс сохранён.`,Continuar:`Продолжить`,"Sem som":`Звука нет`,"Som ligado":`Звук включён`,"Voltar mesmo? O que não foi guardado se perde.":`Точно вернуться? Несохранённое будет потеряно.`,"Voltar ao título":`На титульный экран`,"<kbd>A</kbd><kbd>D</kbd> andar pelo convés · <kbd>E</kbd> usar · <kbd>Tab</kbd> caderno de bordo":`<kbd>A</kbd><kbd>D</kbd> ходить по палубе · <kbd>E</kbd> действие · <kbd>Tab</kbd> бортовой журнал`,"<kbd>A</kbd><kbd>D</kbd> escolher o lugar · <kbd>E</kbd> navegar até lá · <kbd>Esc</kbd> voltar ao convés":`<kbd>A</kbd><kbd>D</kbd> выбрать место · <kbd>E</kbd> плыть туда · <kbd>Esc</kbd> на палубу`,"Dia {dia}":`День {dia}`,"Caderno de bordo (Tab)":`Бортовой журнал (Tab)`,Caderno:`Журнал`,Tab:`Tab`,"Caderno de bordo":`Бортовой журнал`,"Dia {dia} · {turno}":`День {dia} · {turno}`,"O que fazer":`Что делать`,"Como jogar":`Как играть`,Espécies:`Виды`,"O progresso fica salvo.":`Твой прогресс сохранён.`,"Sair do jogo":`Выйти из игры`,"O dia":`День`,"<b>Manhã e tarde</b>um mergulho em cada turno":`<b>Утро и день</b>по одному погружению`,"<b>No barco</b>o peixe que sobe vai para a despensa":`<b>В лодке</b>поднятая рыба идёт в кладовую`,"<b>Noite</b>o Boca do Poço abre e você serve no balcão":`<b>Ночь</b>Boca do Poço открыт, ты за стойкой`,"<b>Com o ouro</b>mais ar, mais carga e mais fundo":`<b>На золото</b>больше воздуха, груза и глубины`,"No mergulho":`Под водой`,"<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> arrancada":`<kbd>WASD</kbd> плыть · <kbd>Shift</kbd> рывок`,"<kbd>Mouse</kbd> segure para mirar, solte para atirar":`<kbd>Мышь</kbd> зажми — прицел, отпусти — выстрел`,"<kbd>F</kbd> faca: abre caixote, pega achado":`<kbd>F</kbd> нож: открыть ящик, взять находку`,"<kbd>Tab</kbd> troca a arma · <kbd>C</kbd> carga":`<kbd>Tab</kbd> смена оружия · <kbd>C</kbd> груз`,"<kbd>E</kbd> subir no barco ou pela boia":`<kbd>E</kbd> подняться в лодку или по бую`,"No restaurante":`В ресторане`,"<kbd>A</kbd><kbd>D</kbd> andar pelo balcão":`<kbd>A</kbd><kbd>D</kbd> ходить вдоль стойки`,"<kbd>E</kbd> pegar, servir, limpar e socar":`<kbd>E</kbd> взять, подать, убрать, толочь`,"segure <kbd>E</kbd> para encher a cuia de tacacá":`держи <kbd>E</kbd>, чтобы налить такаку в калебасу`,Lembranças:`Воспоминания`,"<kbd>A</kbd><kbd>D</kbd> escolher · <kbd>E</kbd> ou <kbd>Enter</kbd> fazer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> ou <kbd>Esc</kbd> fechar":`<kbd>A</kbd><kbd>D</kbd> выбор · <kbd>E</kbd> или <kbd>Enter</kbd> выполнить · <kbd>C</kbd> страницы · <kbd>Tab</kbd> или <kbd>Esc</kbd> закрыть`,"Fama <b>{fama}</b>":`Слава <b>{fama}</b>`,"Despensa <b>{n}</b> peixe":{one:`В кладовой <b>{n}</b> рыба`,few:`В кладовой <b>{n}</b> рыбы`,many:`В кладовой <b>{n}</b> рыб`,other:`В кладовой <b>{n}</b> рыбы`},"<b>{n}</b> de {total} espécies no caderno":`В тетради <b>{n}</b> из {total} видов`,"{n} pescado":{one:`поймана {n}`,few:`поймано {n}`,many:`поймано {n}`,other:`поймано {n}`},"maior: {peso} kg":`крупнейший: {peso} кг`,"Vive entre {min} e {max} m":`Живёт на {min}–{max} м`,"3★ rende {corte}":`3★ даёт: {corte}`,"Encontro anotado":`Встреча записана`,"Fama no rio · {grau}":`Слава на реке · {grau}`,Canoa:`Каноэ`,farinha:`мука`,"<kbd>A</kbd><kbd>D</kbd> andar · <kbd>E</kbd> ou <kbd>espaço</kbd> pegar, servir, limpar e socar · segure para encher a cuia":`<kbd>A</kbd><kbd>D</kbd> ходить · <kbd>E</kbd> или <kbd>Пробел</kbd> взять, подать, убрать, толочь · держи, чтобы наполнить калебасу`,limpar:`убрать`,"{n} moeda":{one:`{n} монета`,few:`{n} монеты`,many:`{n} монет`,other:`{n} монеты`},"hora de abrir o Boca do Poço":`пора открывать Boca do Poço`,"descer no escuro ou dormir até de manhã":`нырнуть в темноте или спать до утра`,"dois mergulhos até a noite":`два погружения до ночи`,"último mergulho antes da noite":`последнее погружение до ночи`,"Primeiro mergulho":`Первое погружение`,"{n} mergulho":{one:`{n} погружение`,few:`{n} погружения`,many:`{n} погружений`,other:`{n} погружения`},"Melhor mergulho: {moedas} · {vezes}":`Лучшее погружение: {moedas} · всего {vezes}`,"no máximo":`максимум`,"Ache esta arma nos caixotes para liberar o projeto: {achadas} de {precisa}.":`Найди это оружие в ящиках, чтобы открыть чертёж: {achadas} из {precisa}.`,"✓ Levando":`✓ Беру`,Levar:`Взять`,"{n} peça · −{desconto}% de ouro":{one:`{n} деталь · −{desconto}% монет`,few:`{n} детали · −{desconto}% монет`,many:`{n} деталей · −{desconto}% монет`,other:`{n} детали · −{desconto}% монет`},"O rio está acordando":`Река просыпается`,"Ainda dá um mergulho":`Ещё можно нырнуть`,"A noite é do Boca do Poço":`Ночь — время Boca do Poço`,"De dia, o poço · de noite, o balcão":`Днём — омут · ночью — стойка`,"O Tuca pesca no fundo do poço para abastecer o balcão do <strong>restaurante flutuante</strong> da Dona Naná.":`Тука рыбачит на дне омута, чтобы кормить гостей <strong>плавучего ресторана</strong> бабушки Наны.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa enche o balcão da Dona Naná.":`Что Тука добудет в реке, то ночью станет блюдом, а каждая удачная ночь наполняет стойку бабушки Наны.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa paga um pedaço da dívida do avô.":`Что Тука добудет в реке, то ночью станет блюдом, а каждая удачная ночь гасит часть дедова долга.`,"No barco":`В лодке`,Começar:`Начать`,"Como o jogo funciona":`Как устроена игра`,"<b>Mergulhe</b>Pesque e junte achados enquanto o ar durar.":`<b>Ныряй</b>Лови рыбу и собирай находки, пока есть воздух.`,"<b>Volte ao barco</b>O peixe que sobe vai para a despensa do restaurante.":`<b>Вернись в лодку</b>Поднятая рыба идёт в кладовую ресторана.`,"<b>À noite, abra o Boca do Poço</b>Monte o cardápio e sirva os fregueses no balcão.":`<b>Ночью открывай Boca do Poço</b>Составь меню и обслуживай гостей за стойкой.`,"<b>Melhore o barco</b>Com o ouro, mais ar, mais carga e mais fundo.":`<b>Улучшай лодку</b>На золото — больше воздуха, груза и глубины.`,"O dia tem dois mergulhos, um de manhã e um de tarde; à noite o restaurante abre com o que você pescou. A nota da noite e a fama crescem com o capricho no serviço.":`В день два погружения, утром и днём; ночью ресторан открывается с тем, что ты поймал. Оценка за ночь и слава растут, если стараться в обслуживании.`,"<kbd>WASD</kbd> nadar":`<kbd>WASD</kbd> плыть`,"<kbd>Mouse 1</kbd> segure para mirar, solte para atirar":`<kbd>ЛКМ</kbd> зажми — прицел, отпусти — выстрел`,"<kbd>Shift</kbd> arrancada (gasta mais ar)":`<kbd>Shift</kbd> рывок (тратит больше воздуха)`,"<kbd>Tab</kbd> arpão · arma · tarrafa · faca":`<kbd>Tab</kbd> гарпун · оружие · сеть · нож`,"<kbd>F</kbd> faca: abre caixote e caixa de munição, pega achado e arranca minério":`<kbd>F</kbd> нож: открыть ящик и коробку зарядов, взять находку, отбить руду`,"<kbd>Espaço</kbd> contra peixe forte":`<kbd>Пробел</kbd> против сильной рыбы`,"<kbd>C</kbd> carga":`<kbd>C</kbd> груз`,"<kbd>E</kbd> subir (barco ou boia)":`<kbd>E</kbd> подъём (лодка или буй)`,"<kbd>Q</kbd> apetrecho de defesa: nuvem de urucum ou chamariz de pano":`<kbd>Q</kbd> защита: облако уруку или тряпичная приманка`,"<kbd>M</kbd> som":`<kbd>M</kbd> звук`,"Volte ao barco antes que o ar acabe: o peixe que sobe vai para a cozinha.":`Вернись в лодку, пока не кончился воздух: поднятая рыба идёт на кухню.`,"<kbd>E</kbd> ou <kbd>Espaço</kbd> pegar o prato, servir, limpar e socar o pilão":`<kbd>E</kbd> или <kbd>Пробел</kbd> взять блюдо, подать, убрать, толочь в ступе`,"Sirva a cada freguês o prato que ele pediu antes que a paciência acabe.":`Подай каждому гостю его заказ, пока не лопнуло терпение.`,"Com controle":`С геймпадом`,"<kbd>Analógico esquerdo</kbd> nadar e andar · <kbd>LT</kbd> arrancada":`<kbd>Левый стик</kbd> плыть и ходить · <kbd>LT</kbd> рывок`,"<kbd>RT</kbd> segure para mirar com o <kbd>analógico direito</kbd>, solte para atirar":`<kbd>RT</kbd> зажми и целься <kbd>правым стиком</kbd>, отпусти — выстрел`,"<kbd>A</kbd> usar · <kbd>B</kbd> voltar · <kbd>X</kbd> faca · <kbd>Y</kbd> troca a arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> apetrecho":`<kbd>A</kbd> действие · <kbd>B</kbd> назад · <kbd>X</kbd> нож · <kbd>Y</kbd> смена оружия · <kbd>LB</kbd> груз · <kbd>R3</kbd> снаряжение`,Entendi:`Понятно`,"Fim do mergulho":`Погружение окончено`,"Você desmaiou":`Ты потерял сознание`,"Subiu pela boia":`Подъём по бую`,"Você foi puxado para o barco às pressas e só conseguiu segurar a metade mais leve da carga.":`Тебя наспех втащили в лодку, и удалось удержать только более лёгкую половину груза.`,"Você voltou de mãos vazias. O rio continua lá.":`Ты вернулся с пустыми руками. Река никуда не денется.`,"Tudo o que você pescou e achou chegou ao barco.":`Всё, что ты поймал и нашёл, — в лодке.`,"Ficou para trás":`Осталось внизу`,"Guardado no barco para construir armas: {itens}":`В лодке, для сборки оружия: {itens}`,"Para a despensa do Boca do Poço (não entra no total): {porcoes}":`В кладовую Boca do Poço (не входит в итог): {porcoes}`,"<b>{n}</b> porção de {peixe}":{one:`{peixe} — <b>{n}</b> порция`,few:`{peixe} — <b>{n}</b> порции`,many:`{peixe} — <b>{n}</b> порций`,other:`{peixe} — <b>{n}</b> порции`},"Cortes nobres para a cozinha: {cortes}":`Лучшие куски для кухни: {cortes}`,"<b>{n}</b> porção de {corte}":{one:`{corte} — <b>{n}</b> порция`,few:`{corte} — <b>{n}</b> порции`,many:`{corte} — <b>{n}</b> порций`,other:`{corte} — <b>{n}</b> порции`},'Seu Agenor levou <b>{n}</b> peixe doente: +{ouro}. "Não pergunto de onde veio."':{one:`Агенор забрал <b>{n}</b> больную рыбу: +{ouro}. «Не спрашиваю, откуда».`,few:`Агенор забрал <b>{n}</b> больные рыбы: +{ouro}. «Не спрашиваю, откуда».`,many:`Агенор забрал <b>{n}</b> больных рыб: +{ouro}. «Не спрашиваю, откуда».`,other:`Агенор забрал <b>{n}</b> больной рыбы: +{ouro}. «Не спрашиваю, откуда».`},"Novas no caderno de espécies: {peixes}":`Новое в тетради видов: {peixes}`,"Encomendas do flutuante":`Заказы ресторана`,"Total com encomendas":`Итого с заказами`,Total:`Итого`,"Novo recorde!":`Новый рекорд!`,"Voltar ao barco":`Вернуться в лодку`,"{preco} o prato · {n} porção na despensa":{one:`{preco} за блюдо · в кладовой {n} порция`,few:`{preco} за блюдо · в кладовой {n} порции`,many:`{preco} за блюдо · в кладовой {n} порций`,other:`{preco} за блюдо · в кладовой {n} порции`},"Boca do Poço · fama {grau}":`Boca do Poço · слава: {grau}`,"O cardápio da noite":`Меню на ночь`,"Escolha até {vagas} pratos. Hoje vêm {fregueses} fregueses; o que sobrar volta para a despensa.":`Выбери блюда (не больше {vagas}). Гостей сегодня: {fregueses}; остатки вернутся в кладовую.`,"Abrir com {n} porção":{one:`Открыть с {n} порцией`,few:`Открыть с {n} порциями`,many:`Открыть с {n} порциями`,other:`Открыть с {n} порциями`},"Abrir só com cafezinho":`Открыть только с кофейком`,"Equipe · {equipe}":`Команда · {equipe}`,Equipe:`Команда`,"A casa":`Заведение`,"Vender a despensa ao Regatão · {moedas}":`Продать запасы торговцу · {moedas}`,Voltar:`Назад`,"Você achou":`Твоя находка`,"Guardar e continuar":`Забрать и продолжить`,"<strong>{ouro}</strong> moedas":`Монеты: <strong>{ouro}</strong>`,"Cada melhoria aparece no flutuante e vale em todas as noites.":`Каждое улучшение видно на плавучем ресторане и действует каждую ночь.`,"Voltar ao cardápio":`Назад к меню`,"Contratar · {preco}":`Нанять · {preco}`,"Na noite ✓":`На смене ✓`,"Pôr na noite":`На смену`,"Sem vaga":`Мест нет`,"diária de {valor}":`{valor} за ночь`,"Com a fama {grau} ainda não cabe ajudante atrás do balcão.":`При славе «{grau}» помощнику за стойкой пока нет места.`,"Com a fama {grau} cabe {n} ajudante por noite.":{one:`При славе «{grau}» — {n} помощник за ночь.`,few:`При славе «{grau}» — {n} помощника за ночь.`,many:`При славе «{grau}» — {n} помощников за ночь.`,other:`При славе «{grau}» — {n} помощника за ночь.`},"Na fama {grau} abre a primeira vaga.":{one:`При славе «{grau}» откроется первое место.`,few:`При славе «{grau}» мест станет {n}.`,many:`При славе «{grau}» мест станет {n}.`,other:`При славе «{grau}» мест станет {n}.`},"A equipe":`Команда`,"O contrato se paga uma vez; a diária sai do lucro da noite.":`Наём оплачивается один раз; плата за смену — из выручки за ночь.`,"Na noite: <b>{escalados} de {vagas}</b> · diárias de {moedas}":`На смене: <b>{escalados} из {vagas}</b> · оплата {moedas}`,"Na noite: <b>{escalados} de {vagas}</b>":`На смене: <b>{escalados} из {vagas}</b>`,hoje:`сегодня`,"dia {dia}":`день {dia}`,"De tirar o chapéu":`Высший класс`,"Casa elogiada":`Гости довольны`,"Deu para o gasto":`Сойдёт`,"Noite atrapalhada":`Суматошная ночь`,"Noite para esquecer":`Ночь, которую лучше забыть`,"{n} freguês foi embora sem comer":{one:`{n} гость ушёл голодным`,few:`{n} гостя ушли голодными`,many:`{n} гостей ушли голодными`,other:`{n} гостя ушли голодными`},"{n} prato foi parar na banqueta errada":{one:`{n} блюдо ушло не тому гостю`,few:`{n} блюда ушли не тем гостям`,many:`{n} блюд ушли не тем гостям`,other:`{n} блюда ушли не тем гостям`},"os pratos demoraram a chegar":`блюда долго несли`,"As lamparinas se apagam. Seu Agenor abre o caderno só para somar o que a casa fez.":`Гаснут лампы. Агенор открывает тетрадь, только чтобы сложить, что сделал дом.`,"As lamparinas se apagam. Seu Agenor abre o caderno e faz as contas da casa.":`Гаснут лампы. Агенор открывает тетрадь и подводит счёт.`,"Caderno da casa":`Тетрадь дома`,"Caderno do Regatão":`Тетрадь речного торговца`,"Noite do dia {dia}":`Ночь, день {dia}`,"Saiu da cozinha":`С кухни ушло`,"{n} prato":{one:`{n} блюдо`,few:`{n} блюда`,many:`{n} блюд`,other:`{n} блюда`},"O mais pedido foi o <b>{prato}</b>: {fatia}% do que entrou.":`Хит вечера — <b>{prato}</b>: {fatia}% выручки.`,"Nenhum prato saiu hoje.":`Сегодня не продано ни одного блюда.`,"As últimas noites":`Последние ночи`,"o que ficou em caixa":`что осталось в кассе`,"A melhor noite que este caderno já viu!":`Лучшая ночь на памяти этой тетради!`,"Fama no rio: <b>{grau}</b> <em>subiu!</em>":`Слава на реке: <b>{grau}</b> <em>выросла!</em>`,"Fama no rio: <b>{grau}</b>":`Слава на реке: <b>{grau}</b>`,"{ganho} nesta noite, com +{premio} pelo capricho":`{ganho} за ночь, из них +{premio} за старание`,"{ganho} nesta noite":`{ganho} за ночь`,"faltam {faltam} para {grau}":`до «{grau}» ещё {faltam}`,"Contas da noite":`Счёт за ночь`,"{n} freguês servido":{one:`{n} гость обслужен`,few:`{n} гостя обслужено`,many:`{n} гостей обслужено`,other:`{n} гостя обслужено`},Pratos:`Блюда`,Gorjetas:`Чаевые`,"Despesa da casa":`Расходы заведения`,"Diárias da equipe":`Оплата команды`,"Faltou no caixa":`Недостача`,"Ficou em caixa":`Осталось в кассе`,"conceito da noite":`оценка ночи`,"{nota} de 5":`{nota} из 5`,"Ninguém saiu reclamando.":`Никто не ушёл недовольным.`,"Conferido por <b>Seu Agenor, o Regatão</b>":`Проверил <b>Агенор, речной торговец</b>`,"Dormir · amanhã é dia {dia}":`Спать · завтра день {dia}`,Barco:`Лодка`,Armas:`Оружие`,"Achar a mesma arma duas vezes nos caixotes libera o projeto. O material do poço fica guardado aqui, e a arma construída desce com você em todo mergulho.":`Найди одно и то же оружие в ящиках дважды — откроется чертёж. Материалы из омута хранятся здесь, а собранное оружие идёт с тобой в каждое погружение.`,Zarabatana:`Духовая трубка`,"6 dardos com timbó: o peixe dorme e vem vivo":`6 дротиков с тимбо: рыба засыпает и достаётся живой`,"Espingarda de pressão":`Пневморужьё`,"6 tiros de três chumbos, para perto":`6 выстрелов по три дробины, вблизи`,Balestra:`Арбалет`,"4 setas pesadas, que atravessam":`4 тяжёлых болта, бьют насквозь`,"A noite da cheia":`Ночь разлива`,"Na boca do poço mais fundo do rio há um flutuante. Seu Raimundo mergulhava, Dona Naná cozinhava, e não passava barco que não encostasse.":`У самого глубокого омута на реке стоит плавучий ресторан. Дядюшка Раймундо нырял, бабушка Нана готовила, и ни одна лодка не проплывала мимо.`,"Tuca, o neto, voltou da cidade com uma mala e o fôlego do avô. De dia ele desce o poço. De noite, o Boca do Poço abre.":`Внук Тука вернулся из города с одним чемоданом и дедовым дыханием. Днём он ныряет в омут. Ночью открывается Boca do Poço.`,"O dia tem dois mergulhos, um de manhã e um de tarde. O peixe que sobe ao barco vira o prato da noite, e cada noite bem servida paga um pedaço da dívida. O rio está esperando.":`В день два погружения: утром и днём. Рыба, поднятая в лодку, становится ночным блюдом, а каждая удачная ночь гасит часть долга. Река ждёт.`,"O Tição":`Головешка`,"A volta do avô":`Возвращение деда`,"Cobra-Grande":`Великий Змей`,"Escama da Cobra-Grande":`Чешуя Великого Змея`,Tuca:`Тука`,"Dona Naná":`Бабушка Нана`,"Seu Agenor, o Regatão":`Агенор, речной торговец`,Curimatã:`Куриматан`,Jaci:`Жаси`,"Seu Bené":`Дядюшка Бене`,Piaba:`Пиаба`,"Seu Raimundo":`Раймундо`,"Seu Takeshi":`Дядюшка Такеши`,Kauê:`Кауэ`,"Dona Zefa":`Тётушка Зефа`,"Seu Juvenal":`Дядюшка Жувенал`,Ingrid:`Ингрид`,Tião:`Тиан`,"Seu Dico":`Дядюшка Дико`,"Dois tucunarés":`Два тукунаре`,"Um tambaqui":`Один тамбаки`,"Três piranhas":`Три пираньи`,"Dois pacus vivos":`Два живых паку`,"Uma arraia":`Один скат`,"Um poraquê":`Один электрический угорь`,"Um pirarucu":`Один пираруку`,"Cinco jaraquis":`Пять жараки`,"Duas matrinxãs":`Две матриншан`,"Três frutos da mata":`Три лесных плода`,"Dois minérios":`Два куска руды`,"Duas conchas":`Две ракушки`,Pacu:`Паку`,Aracu:`Араку`,"Acará-disco":`Дискус`,Piranha:`Пиранья`,Tucunaré:`Тукунаре`,Tambaqui:`Тамбаки`,Arraia:`Скат`,Traíra:`Траира`,Sucuri:`Анаконда`,Surubim:`Сурубим`,Pirarara:`Пирарара`,Candiru:`Кандиру`,Poraquê:`Электрический угорь`,"Peixe-cachorro":`Пайяра`,Pirarucu:`Пираруку`,Jaú:`Жау`,Piraíba:`Пираиба`,Aruanã:`Аравана`,Jaraqui:`Жараки`,Matrinxã:`Матриншан`,Tamuatá:`Тамуата`,"Peixe-boi":`Ламантин`,Acari:`Акари`,Mandi:`Манди`,Ituí:`Итуи`,Jacaré:`Кайман`,"A volta":`Возвращение`,"Tu cresceu, menino. E voltou magro. Senta, que conversa de barriga vazia não presta.":`Вырос-то как, малой. А худющий какой! Садись, на пустой желудок разговоры не ведут.`,"Vó, que caderno é esse em cima do balcão?":`Ба, а что это за тетрадь на стойке?`,"É do Seu Agenor, o Regatão. Teu avô comprou fiado nele a vida toda. Agora ele diz que a conta é do tamanho do flutuante.":`Это Агенора, речного торговца. Твой дед всю жизнь брал у него в долг. Теперь он говорит, что долг размером с весь наш ресторан.`,"Do tamanho do flutuante e mais a canoa, Dona Naná. Mas eu sou homem de paciência: pagando a parcela, eu espero.":`С ресторан, да ещё и с лодку в придачу, бабушка Нана. Но я человек терпеливый: платите по частям — подожду.`,"Então a gente paga. Eu trago o peixe do poço, a senhora cozinha.":`Значит, заплатим. Я ловлю рыбу в омуте, ты готовишь.`,"Teu avô dizia a mesma coisa, com essa mesma cara. Anda, abre a casa.":`Твой дед говорил то же самое, и с тем же лицом. Давай, открывай заведение.`,"O arpão do avô":`Дедов гарпун`,"Primeira parcela, contadinha. Quem diria: o balcão voltou a encher.":`Первый взнос, копеечка в копеечку. Кто бы мог подумать: у стойки снова людно.`,"Anota aí que pagou, Agenor. De caneta, que lápis teu apaga sozinho.":`Запиши, что уплачено, Агенор. Ручкой, а то твой карандаш сам стирается.`,"Tuca, teu avô perdeu o arpão dele no raso, na última cheia. Ele amarrava as receitas no cabo, para não molhar na canoa.":`Тука, твой дед потерял свой гарпун на отмели в последнее половодье. Он привязывал к древку рецепты, чтобы не намокли в лодке.`,"Receita amarrada em arpão?":`Рецепты на гарпуне?`,"Ele pescava pensando no prato. Se tu achar, traz. Tem coisa naquele caderno que nem eu sei fazer.":`Он рыбачил и уже думал о блюде. Найдёшь — неси. Там есть такое, чего даже я готовить не умею.`,"O arpão do avô está em algum canto do raso, fincado no chão.":`Дедов гарпун торчит где-то на отмели, воткнутый в дно.`,"Arraia não se pesca com pressa nem se cozinha com pressa. Leite de coco, coentro do quintal e fogo baixo. Naná diz que não gosta. Naná repete o prato.":`Ската не ловят второпях и не готовят второпях. Кокосовое молоко, кинза с огорода и слабый огонь. Нана говорит, что не любит. Нана просит добавки.`,"Receita nova no Boca do Poço: moqueca de arraia. As arraias que você pescar agora vão para a despensa.":`Новый рецепт в Boca do Poço: мокека из ската. Теперь пойманные скаты идут в кладовую.`,"As luzes do fundo":`Огни на дне`,"Parcela paga, Dona Naná. Casa cheia, caderno em dia: assim que eu gosto.":`Взнос уплачен, дона Нана. Дом полон, тетрадь в порядке — люблю, когда так.`,"Anota e vai embora, Agenor.":`Запиши и ступай, Агенор.`,"Já vou. Só um aviso de amigo: subiu uma draga pelo rio. Gente de fora, gente de dinheiro. Andam perguntando do poço.":`Ухожу. Просто дружеский совет: вверх по реке пришла драга. Чужие люди, денежные. Расспрашивают про омут.`,"Perguntando o quê?":`Расспрашивают о чём?`,"Quanto ele tem de fundo. E de quem é este flutuante.":`Насколько он глубокий. И чей этот плавучий дом.`,"Teu avô descia de madrugada, sabia? Depois de fechar a casa. Levava a lamparina e dizia que, no escuro, o fundo do poço acendia.":`Твой дед нырял до рассвета, знаешь? После того как закрывал заведение. Брал керосиновую лампу и говорил, что в темноте дно омута светится.`,"Eu achava que era cachaça. Na noite da cheia ele desceu com ela e não voltou.":`Я думала, это кашаса в нём говорит. В ночь паводка он спустился с ней и не вернулся.`,"Então hoje, quando a casa fechar, eu desço.":`Тогда сегодня, когда закроемся, я спущусь.`,"Leva o casaco. E volta, que eu não tenho mais idade para esperar ninguém na beira.":`Возьми куртку. И возвращайся: я уже не в том возрасте, чтобы снова ждать кого-то на берегу.`,"A lamparina do avô":`Дедова лампа`,"A lamparina do avô está no fundo, onde ele descia de madrugada.":`Дедова лампа лежит на дне, там, где он нырял до рассвета.`,"Eles cantam lá embaixo, Naná. Tu não acredita, mas eu vi as luzes. O jacaré velho fugiu do igarapé: a draga revirou o fundo de lá e ele veio parar no nosso poço, com raiva. A draga vem vindo. Hoje eu desço para avisar os do fundo. Se eu demorar, guarda a brasa acesa.":`Они поют там, внизу, Нана. Ты не веришь, но я видел огни. Старый кайман сбежал из протоки: драга перерыла там дно, и он, злой, перебрался в наш омут. Драга идёт сюда. Сегодня я спущусь предупредить тех, кто внизу. Если задержусь — не дай углям погаснуть.`,"A lamparina agora é tua: a lanterna alcança mais longe. E no caderno, duas receitas novas: acari assado e caldo de mandi.":`Теперь лампа твоя: фонарь светит дальше. А в тетради — два новых рецепта: печёный акари и уха из манди.`,"O homem da draga":`Человек с драги`,"Dona Naná, trouxe uma visita. Gente importante, de fora.":`Дона Нана, я привёл гостя. Важный человек, приезжий.`,"Doutor Brandão, minha senhora. Bonito o seu flutuante. Bem na boca do poço.":`Доктор Брандан, сеньора. Красивый у вас плавучий дом. Прямо у входа в омут.`,"Se veio comer, senta. Se veio olhar, a vista é de graça.":`Пришли поесть — садитесь. Пришли поглазеть — вид бесплатный.`,"Vim fazer negócio. Pago o dobro da dívida, à vista. A senhora descansa e eu ancoro a minha draga aqui.":`Я пришёл по делу. Плачу вдвое больше долга, наличными. Вы отдыхаете, а я ставлю здесь свою драгу.`,"Este flutuante não está à venda. Nem pelo dobro, nem pelo triplo.":`Этот дом не продаётся. Ни за двойную цену, ни за тройную.`,"Tudo no rio tem preço, minha senhora. Às vezes quem cobra é o rio.":`На реке у всего есть цена, сеньора. Иногда по счетам взыскивает сама река.`,"Vó, de madrugada tem um jacaré enorme rondando a tona. Os olhos parecem brasa.":`Бабушка, до рассвета у поверхности рыщет огромный кайман. Глаза как угли.`,"É o Tição. Teu avô falava dele. Desce com a faca na mão, menino.":`Это Головешка. Твой дед про него рассказывал. Спускайся с ножом в руке, мальчик.`,"A faca do avô":`Дедов нож`,"A faca do avô ficou no meio do poço, onde ele brigou com o Tição.":`Дедов нож остался на середине омута, там, где он бился с Головешкой.`,'Riscado no cabo, com a ponta da própria faca: "O Tição veio da draga. Bati nele três vezes e ele não largou. Se tu achar esta faca, Tuca, é tua. Não vai atrás dele: deixa ele vir, e bate na hora do bote."':`Нацарапано на рукояти остриём самого ножа: «Головешка пришёл с драгой. Я ударил его трижды, а он не отпустил. Если найдёшь этот нож, Тука, он твой. Не гонись за ним: дай ему подойти и бей, когда он бросится».`,"A faca do avô é tua: o rebate fica mais fácil e o golpe, mais forte.":`Дедов нож теперь твой: отбивать легче, а удар сильнее.`,"A porta":`Дверь`,"Dona Naná... preciso contar uma coisa antes que a senhora saiba por outro.":`Дона Нана... я должен кое-что сказать, пока вы не узнали от других.`,"Fala, Agenor. Mas fala de pé, que sentado tu mente melhor.":`Говори, Агенор. Только стоя: сидя ты врёшь складнее.`,"Eu vendi a dívida do Raimundo para o Doutor Brandão. Ele quer o poço. A draga desce na próxima cheia.":`Я продал долг Раймундо Доктору Брандану. Ему нужен омут. Драга спустится с ближайшим паводком.`,"O senhor vendeu a gente.":`Вы нас продали.`,"Vendi papel. Achei que era só papel. O Raimundo dizia que no fundo tinha uma porta, e eu ri dele.":`Я продал бумагу. Думал, это просто бумага. Раймундо говорил, что на дне есть дверь, а я смеялся над ним.`,"Sai do meu balcão, Agenor. A despensa tu ainda compra, que eu não sou boba. Mas cafezinho aqui tu não toma mais.":`Прочь от моей стойки, Агенор. Кладовую ты ещё покупаешь — я не дура. Но кофе тебе здесь больше не пить.`,"Uma porta no fundo do poço, vó?":`Дверь на дне омута, бабушка?`,"Teu avô usava uma pedra verde no pescoço, um sapinho. Dizia que era a chave. Sumiu no dia da cheia, junto com ele.":`Твой дед носил на шее зелёный камень — лягушонка. Говорил, что это ключ. Он пропал в день паводка вместе с ним.`,"O muiraquitã do avô":`Дедов муиракитан`,"O muiraquitã do avô está no fundo mais fundo, onde só se chega de madrugada.":`Дедов муиракитан лежит в самой глубине, куда добираются только до рассвета.`,'Amarrado no cordão do muiraquitã, um papel dobrado: "A Cobra-Grande guarda o caminho e não deixa a draga passar. A porta abre para quem leva o sapinho. Se a draga descer, os do fundo vão lutar. Eu vou com eles."':`К шнурку муиракитана привязана сложенная записка: «Большой Змей стережёт путь и не пропустит драгу. Дверь открывается тому, кто несёт лягушонка. Если драга спустится, те, кто внизу, будут биться. Я пойду с ними».`,"O muiraquitã é teu. No fundo, a porta dos encantados já te espera.":`Муиракитан твой. Внизу тебя уже ждёт дверь заколдованных.`,"A cheia":`Паводок`,"O rio subiu dois palmos desde ontem. A cheia chegou.":`Река поднялась на две ладони со вчерашнего дня. Паводок пришёл.`,"Recado do Doutor Brandão: a draga desce amanhã. Quem estiver no caminho, que saia.":`Передаю от Доктора Брандана: драга спустится завтра. Кто на пути — пусть уходит.`,"Hoje de madrugada eu abro a porta, vó. O Tição vai estar lá.":`Сегодня до рассвета я открою дверь, бабушка. Головешка будет там.`,"Teu avô disse a mesma coisa, nesta mesma noite. Volta, Tuca. Volta com ele.":`Твой дед говорил то же самое, в такую же ночь. Вернись, Тука. Вернись с ним.`,"Tuca! Tem um homem subindo a escada do flutuante. Molhado, de barba branca.":`Тука! По лестнице плавучего дома поднимается человек. Мокрый, с белой бородой.`,"Naná. A brasa ainda está acesa?":`Нана. Угли ещё горят?`,"Nunca apagou, velho teimoso. Nunca.":`Никогда не гасли, упрямый ты старик. Никогда.`,"Os do fundo me guardaram até alguém abrir a porta. Não imaginei que ia ser o menino.":`Те, кто внизу, берегли меня, пока кто-нибудь не откроет дверь. Не думал, что это будет мальчик.`,"A draga afundou, vô. O Tição não volta.":`Драга утонула, дед. Головешка не вернётся.`,"E o Doutor Brandão sumiu rio abaixo. Com ele, o contrato. A dívida... a dívida não existe mais.":`А Доктор Брандан исчез вниз по реке. С ним и договор. Долг... долга больше нет.`,"Então senta, Raimundo. E tu também, Agenor. Hoje o cafezinho é por conta da casa.":`Тогда садись, Раймундо. И ты тоже, Агенор. Сегодня кофе за счёт заведения.`,"Doutor Brandão":`Доктор Брандан`,"Cilindro de ar":`Баллон с воздухом`,"Caixa de munição":`Коробка зарядов`,"Anel de ouro":`Золотое кольцо`,Muiraquitã:`Муиракитан`,"Baú perdido":`Потерянный сундук`,"Cuia de prata":`Серебряная калебаса`,"Brinco de esmeralda":`Изумрудная серьга`,"Garrafa antiga":`Старинная бутылка`,"Moeda antiga":`Старинная монета`,"Pérola de rio":`Речной жемчуг`,Diamante:`Алмаз`,Opala:`Опал`,Ametista:`Аметист`,Estanho:`Олово`,Ferro:`Железо`,Cobre:`Медь`,"Cacho de açaí":`Гроздь асаи`,"Ouriço de castanha":`Плод бразильского ореха`,"Concha de mexilhão":`Раковина мидии`,"Casca de caramujo":`Раковина улитки`,"Fragmento de arpão":`Обломок гарпуна`,Sucata:`Металлолом`,"Caco de vidro":`Осколок стекла`,Corda:`Верёвка`,Madeira:`Древесина`,"Tanque de ar":`Баллон`,"Mais ar para ficar mais tempo lá embaixo.":`Больше воздуха — дольше под водой.`,"de ar":`воздуха`,Traje:`Костюм`,"Aguenta a pressão até mais fundo. Passou do limite, o ar acaba bem mais rápido.":`Держит давление глубже. За пределом воздух уходит куда быстрее.`,m:`м`,Samburá:`Корзина`,"Cabe mais peixe e mais achado antes de pesar.":`Влезает больше рыбы и находок, прежде чем станет тяжело.`,kg:`кг`,"Tiro mais forte: peixe resistente vem com menos disparos.":`Выстрел мощнее: крепкая рыба сдаётся быстрее.`,"de dano":`урона`,"Golpe mais forte, para o que chega perto demais.":`Удар сильнее — для тех, кто подплыл слишком близко.`,Tarrafa:`Накидная сеть`,"Mais lances de rede por mergulho. Peixe de tarrafa vem vivo e vale mais.":`Больше бросков сети за погружение. Рыба из сети живая и стоит дороже.`,lances:`за погружение`,"Boia de resgate":`Спасательный буй`,"Leva o peixe grande direto para o barco, sem pesar no samburá.":`Отправляет крупную рыбу прямо в лодку, не нагружая корзину.`,"por mergulho":`за погружение`,"Ponta de aço":`Стальной наконечник`,"+1 de dano":`+1 урона`,"Ponta farpada":`Зазубренный наконечник`,"não solta: aperte Espaço na hora certa":`не срывается: жми Пробел вовремя`,"Ponta elétrica":`Электронаконечник`,"+1 de dano · atordoa o peixe · alterne A e D":`+1 урона · оглушает рыбу · чередуй A и D`,"Ponta de timbó":`Наконечник с тимбо`,"adormece o peixe: ele vem vivo · siga as setas":`усыпляет рыбу: она достаётся живой · жми стрелки`,"Ponta de curare":`Наконечник с кураре`,"veneno: tira vida aos poucos · aperte bem rápido":`яд: понемногу отнимает здоровье · жми очень быстро`,"O que tem de bom hoje?":`Что сегодня вкусного?`,"Estou varado de fome...":`Я голодный как волк...`,"Hum, que cheiro!":`М-м, как пахнет!`,"Capricha aí!":`Уж постарайся!`,"Isso é que é comida!":`Вот это еда!`,"Hum... que beleza.":`М-м... красота.`,"Égua, que tá bom demais!":`Ух ты, вкуснотища какая!`,"Cheirou, chegou!":`Запахло — значит, несут!`,"Ô garçom!":`Эй, официант!`,"Vai demorar?":`Долго ещё?`,"Esqueceram de mim?":`Про меня забыли?`,"Faz tempo que eu não comia um {prato} assim. Volto amanhã e trago a família.":`Вот это {prato}! Давно такого не ел. Завтра приду всей семьёй.`,"Mal sentei e o prato já estava na minha frente. Isso é que é casa bem tocada!":`Только сел — а блюдо уже передо мной. Вот это порядок в заведении!`,"O {prato} da Dona Naná continua o melhor deste rio. Podem escrever.":`У бабушки Наны {prato} — по-прежнему лучшее на всей реке. Так и запишите.`,"Vim de longe só pelo {prato}. Valeu cada remada.":`Плыл издалека ради одного — {prato}. Каждый взмах весла того стоил.`,"A comida é boa, mas hoje a espera foi comprida.":`Еда хорошая, но ждать сегодня пришлось долго.`,"Gostei do {prato}. Só achei o balcão meio atrapalhado.":`Понравилось: {prato} что надо. Только за стойкой суматоха.`,"Dá para voltar. Com mais ligeireza no serviço, eu voltava toda noite.":`Можно и вернуться. Обслуживали бы пошустрее — ходил бы каждый вечер.`,"Esperei, esperei e fui embora de barriga vazia. Assim não dá.":`Ждал, ждал и ушёл голодным. Так не пойдёт.`,"Vi gente levantando sem comer. A casa precisa de mais braço no balcão.":`Видел, как люди уходили не поев. За стойкой не хватает рук.`,"Me trouxeram o prato do vizinho. Hoje não foi a noite de vocês.":`Мне принесли блюдо соседа. Сегодня не ваш вечер.`,"Calado e atento: limpa a banqueta antes de você notar que sujou.":`Молчаливый и внимательный: уберёт место раньше, чем ты заметишь грязь.`,"Soca o pilão cantando: a farinha não acaba mais.":`Толчёт в ступе с песней: мука больше не кончается.`,"Devagar e certeiro: nunca erra a marca da cuia.":`Неспешно, зато точно: всегда наливает до отметки.`,"Ligeira no balcão: pega o prato pronto e leva a quem pediu.":`Шустрая за стойкой: берёт готовое блюдо и несёт тому, кто заказал.`,"Fogão de duas bocas":`Плита на две конфорки`,"A cozinha prepara cada prato mais rápido.":`Кухня готовит каждое блюдо быстрее.`,"s por prato":`с на блюдо`,"Banquetas estofadas":`Мягкие табуреты`,"Sentado no macio, o freguês espera mais antes de desistir.":`Сидя на мягком, гость готов ждать дольше.`,"s de paciência":`с терпения`,"Pilão grande":`Большая ступа`,"Cabe mais farinha antes de precisar socar de novo.":`Вмещает больше муки — толочь приходится реже.`,"de farinha":`муки`,"Lamparinas e flores":`Лампы и цветы`,"Casa bonita: mais fregueses deixam gorjeta.":`Красиво — и больше гостей оставляют чаевые.`,"% dão gorjeta":`% дают чаевые`,"Placa iluminada":`Световая вывеска`,"A casa se vê de longe: vêm mais fregueses por noite.":`Заведение видно издалека: за ночь приходит больше гостей.`,"fregueses a mais":`к числу гостей`,Cafezinho:`Кофеёк`,"Costela de tambaqui":`Рёбрышки тамбаки`,"Filé de tucunaré":`Филе тукунаре`,"Ventrecha de pirarucu":`Брюшко пираруку`,Rabeta:`Моторка`,Voadeira:`Катер`,Batelão:`Баржа`,Recreio:`Теплоход`,Gaiola:`Лайнер`,"Peixe frito":`Жареная рыба`,"Caldo de piranha":`Уха из пираньи`,"Tucunaré na brasa":`Тукунаре на углях`,"Tambaqui assado":`Запечённый тамбаки`,Caldeirada:`Калдейрада`,"Pirarucu de casaca":`Пираруку де казака`,"Aruanã assada na folha":`Аравана, запечённая в листе`,"Moqueca de arraia":`Мокека из ската`,"Acari assado":`Печёный акари`,"Caldo de mandi":`Уха из манди`,"Costela de tambaqui assada":`Запечённые рёбрышки тамбаки`,"Filé de tucunaré no tucupi":`Филе тукунаре в тукупи`},o={"Na boca do poço mais fundo do rio tem um flutuante. É o Boca do Poço, a nossa casa e o nosso restaurante.":`Am Rand des tiefsten Kolks im Fluss liegt ein schwimmendes Lokal. Das ist das Boca do Poço, unser Zuhause und unser Restaurant.`,"O meu Raimundo mergulhava e trazia o peixe. Eu cozinhava. De noite, não passava barco que não encostasse.":`Mein Raimundo tauchte und brachte den Fisch. Ich kochte. Abends fuhr kein Boot vorbei, ohne anzulegen.`,"Ele dizia que, de madrugada, o fundo do poço acendia. Eu achava que era conversa de pescador.":`Er sagte, kurz vor Morgengrauen leuchte der Grund des Kolks. Ich hielt das für Anglergarn.`,"Numa noite de cheia, ele desceu com a lamparina e não voltou.":`In einer Nacht bei Hochwasser tauchte er mit der Lampe hinab und kam nicht zurück.`,"Ficaram a brasa acesa, o balcão vazio e uma dívida no caderno do Seu Agenor, o Regatão. Do tamanho do flutuante.":`Geblieben sind die glimmende Glut, die leere Theke und eine Schuld im Buch von Seu Agenor, dem Flusshändler. So groß wie das Lokal selbst.`,"Foi aí que o Tuca, nosso neto, voltou da cidade. Veio me ajudar a tocar o restaurante.":`Da kam Tuca, unser Enkel, aus der Stadt zurück. Er kam, um mir zu helfen, das Restaurant zu führen.`,"Sem peixe não tem prato. Então, todo dia, ele desce o poço e traz o pescado. De noite, eu cozinho e ele serve. Cada noite boa paga um pedaço da dívida.":`Ohne Fisch kein Gericht. Also taucht er jeden Tag in den Kolk hinab und holt den Fang herauf. Abends koche ich, und er serviert. Jeder gute Abend tilgt ein Stück der Schuld.`,"E lá embaixo, o rio ainda guarda o que aconteceu com o Raimundo.":`Und dort unten bewahrt der Fluss noch immer, was mit Raimundo geschehen ist.`,"Saco de urucum":`Urucum-Beutel`,"Chamariz de pano":`Stoffköder`,"Rondando você":`Sie umkreist dich`,"Vai dar o bote: rebata com a faca!":`Gleich schnappt er zu: wehr ihn mit dem Messer ab!`,"Rebata agora!":`Jetzt abwehren!`,"Tonto: arpão e faca agora!":`Benommen: jetzt Harpune und Messer!`,"Ela está acordando…":`Sie wacht auf…`,"Vai dar o bote: saia da frente!":`Sie setzt zum Biss an: weg da!`,"Saia da frente!":`Weg da!`,"Boca aberta: atire agora!":`Maul offen: jetzt schießen!`,"Cuidado com a cauda!":`Vorsicht, der Schwanz!`,"Ela desistiu de você":`Sie lässt von dir ab`,"Amanheceu: dia {dia}":`Neuer Morgen: Tag {dia}`,"A tarde chegou":`Es ist Nachmittag`,"Anoiteceu: o Boca do Poço pode abrir":`Es ist Abend: Das Boca do Poço kann öffnen`,"Peixe forte! Aperte espaço (ou clique) bem rápido para cansá-lo.":`Starker Fisch! Drück schnell Leertaste (oder klick), um ihn zu ermüden.`,"Peixe forte! Alterne A e D bem rápido.":`Starker Fisch! Drück schnell abwechselnd A und D.`,"Peixe forte! Aperte as setas na ordem, antes que o tempo acabe.":`Starker Fisch! Drück die Pfeile der Reihe nach, bevor die Zeit abläuft.`,"Peixe forte! Aperte espaço quando o marcador passar no verde.":`Starker Fisch! Drück Leertaste, wenn der Zeiger im Grünen ist.`,"Levar o barco até o Boca do Poço, que abre agora.":`Mit dem Boot zum Boca do Poço, es öffnet jetzt.`,"na escada":`an der Leiter`,"Levar o barco pelo rio. O Boca do Poço abre à noite.":`Mit dem Boot über den Fluss. Das Boca do Poço öffnet abends.`,"no leme":`am Steuer`,"Melhorar o tanque, o traje, a carga e as armas.":`Tank, Anzug, Ladung und Waffen verbessern.`,"na bancada":`an der Werkbank`,"Deixar o turno passar sem mergulhar.":`Die Tageszeit ohne Tauchen verstreichen lassen.`,"no banco da proa":`auf der Bugbank`,"Antes do primeiro mergulho":`Vor dem ersten Tauchgang`,"De volta ao barco":`Zurück im Boot`,"Barco ancorado no igapó. O mergulho daqui é entre as árvores.":`Boot im Igapó verankert. Von hier taucht man zwischen den Bäumen.`,"Barco ancorado no poço.":`Boot am Strudelloch verankert.`,"{destino}: {motivo}":`{destino}: {motivo}`,"{destino} · {rotulo}":`{destino} · {rotulo}`,Final:`Finale`,"Capítulo {numero}":`Kapitel {numero}`,"Abrir o cardápio":`Speisekarte öffnen`,"{escalados} de {vagas} na noite":`{escalados} von {vagas} im Dienst`,limpeza:`Putzen`,pilão:`Mörser`,tacacá:`Tacacá`,"serve os pratos":`Servieren`,"Um freguês":`Ein Gast`,"Primeira noite":`Erste Nacht`,"Primeira noite · {numero} de {total}":`Erste Nacht · {numero} von {total}`,"Cansei de esperar!":`Ich warte nicht länger!`,"Um freguês cansou de esperar e foi embora":`Ein Gast hatte genug vom Warten und ging`,"{prato} acabou":`{prato} ist aus`,"Um prato":`Ein Gericht`,"Tacacá na marca: ele paga 30% a mais":`Tacacá auf den Punkt: Er zahlt 30 % mehr`,"Passou da marca: derramou o tacacá":`Zu voll: Tacacá verschüttet`,"Faltou tacacá na cuia":`Zu wenig Tacacá in der Kalebasse`,"Acabou a farinha: a cozinha parou. Soque o pilão!":`Kein Mehl mehr: Die Küche steht. Stampf im Mörser!`,"Um peixe-boi! Ele deixou você chegar perto. Presente do igapó: {ouro} moedas.":`Eine Seekuh! Sie hat dich nah herankommen lassen. Ein Geschenk des Igapó: {ouro} Münzen.`,"Encomenda do flutuante: {encomendas}":`Bestellung fürs Lokal: {encomendas}`,"A porta dos encantados te espera no fundo. O Tição também.":`Die Tür der Verzauberten wartet unten auf dich. Glutauge auch.`,"Tutorial concluído. Agora abra o Boca do Poço e sirva o que pescou!":`Tutorial geschafft. Jetzt öffne das Boca do Poço und servier deinen Fang!`,"Primeiro mergulho · {numero} de {total}":`Erster Tauchgang · {numero} von {total}`,"Carga cheia! Volte ao barco.":`Ladung voll! Zurück zum Boot.`,"Encomenda cumprida: {encomenda} (+{premio})":`Bestellung erfüllt: {encomenda} (+{premio})`,"Soltou {nome}":`{nome} losgelassen`,"Espécie nova! {peixe}":`Neue Art! {peixe}`,"Espécie nova no caderno: {peixe} · +{moedas} moedas":`Neue Art im Heft: {peixe} · +{moedas} Münzen`,"Abatido!":`Erlegt!`,"Falta {n}":{one:`Noch {n}`,other:`Noch {n}`},"Rebateu!":`Abgewehrt!`,"O Tição está tonto: agora o arpão e a faca ferem!":`Glutauge ist benommen: Jetzt verletzen ihn Harpune und Messer!`,"A porta dos encantados":`Die Tür der Verzauberten`,"O Tição afunda na escuridão e não volta. A porta se abre devagar, e a água do fundo acende como o avô dizia: luzes que cantam. Lá em cima, um estrondo: a draga do Doutor Brandão adernou e foi ao fundo, longe do poço. Uma voz conhecida chama o teu nome.":`Glutauge versinkt in der Dunkelheit und kommt nicht zurück. Die Tür öffnet sich langsam, und das Wasser in der Tiefe leuchtet auf, wie Großvater gesagt hat: Lichter, die singen. Oben ein Krachen: Doktor Brandãos Bagger ist gekentert und gesunken, weit weg vom Strudelloch. Eine vertraute Stimme ruft deinen Namen.`,"Presente dos encantados: {ouro} moedas. Volte ao balcão: tem alguém esperando.":`Ein Geschenk der Verzauberten: {ouro} Münzen. Geh zurück an die Theke: Dort wartet jemand.`,"Boia de resgate: {peixe} {marca} a caminho do barco":`Rettungsboje: {peixe} {marca} unterwegs zum Boot`,"{peixe} {marca} · {peso} kg":`{peixe} {marca} · {peso} kg`,"Este {peixe} está doente: Dona Naná não vai cozinhar.":`Dieser {peixe} ist krank: Dona Naná kocht ihn nicht.`,"O couro do jacaré não fura. Só o rebate de faca o afasta.":`Die Haut des Kaimans ist nicht zu durchbohren. Nur ein Messerkonter vertreibt ihn.`,"O couro dela não fura. Espere o bote: cansada, ela abre a boca.":`Ihre Haut ist undurchdringlich. Warte den Biss ab: Erschöpft öffnet sie das Maul.`,"A Cobra-Grande se recolheu e deixou uma escama: +{valor}":`Die Große Schlange zieht sich zurück und lässt eine Schuppe da: +{valor}`,"Uma posta de {peixe} · +{valor}":{one:`Ein Stück {peixe} · +{valor}`,other:`{n} Stück {peixe} · +{valor}`},"Tanque cheio: o cilindro fica aí para quando faltar ar.":`Tank voll: Die Flasche bleibt hier, falls dir die Luft ausgeht.`,"+{ar} de ar":`+{ar} Luft`,"Já leva {caixas} caixas de munição guardadas: esta fica para depois.":`Du hast schon {caixas} Munitionskästen dabei: Dieser bleibt für später.`,"{arma}: +{tiros} de munição":`{arma}: +{tiros} Munition`,"+{tiros} munição":`+{tiros} Munition`,"Caixa de munição guardada ({caixas}): entra quando a arma esvaziar.":`Munitionskasten verstaut ({caixas}): kommt dran, wenn die Waffe leer ist.`,"Caixa de munição guardada ({caixas}): serve para a arma que você achar num caixote.":`Munitionskasten verstaut ({caixas}): für die Waffe, die du in einer Kiste findest.`,"Caixa guardada":`Kasten verstaut`,"{item} para o barco":`{item} fürs Boot`,"Peças de {arma} para o Barco (+1)":`Teile von {arma} fürs Boot (+1)`,"Projeto liberado: {arma}. Dá para construir no Barco.":`Bauplan frei: {arma}. Jetzt im Boot baubar.`,"{apetrecho} no cinto · {tecla} para usar":`{apetrecho} am Gürtel · {tecla} zum Benutzen`,"Tarrafa: +{lances} lances":`Wurfnetz: +{lances} Würfe`,"+{lances} lances":`+{lances} Würfe`,"Punhado de moedas":`Handvoll Münzen`,"Moedas +{valor}":`Münzen +{valor}`,"Boia de resgate: leva um peixe grande direto para o barco":`Rettungsboje: bringt einen großen Fisch direkt zum Boot`,"+1 boia":`+1 Boje`,"Nuvem de urucum: os bichos perderam você de vista":`Urucum-Wolke: die Tiere haben dich aus den Augen verloren`,"Chamariz solto: os bichos vão atrás dele":`Köder los: die Tiere jagen ihm nach`,"O Tição levou {peixe} da sua carga!":`Glutauge hat dir {peixe} aus dem Fang geschnappt!`,"{bicho} enrolou você! Aperte espaço bem rápido para se soltar.":`{bicho} umschlingt dich! Drück schnell Leertaste, um loszukommen.`,"{bicho} investiu!":`{bicho} greift an!`,"O veneno derrubou o peixe: ele fica boiando e vale 1 estrela.":`Das Gift hat den Fisch erledigt: Er treibt im Wasser und ist 1 Stern wert.`,"{bicho} bateu na pedra e ficou tonta!":`{bicho} ist gegen den Fels geprallt und benommen!`,"Ferroada de arraia!":`Rochenstich!`,"A Cobra-Grande acordou!":`Die Große Schlange ist erwacht!`,"O bote da Cobra-Grande pegou você!":`Der Biss der Großen Schlange hat dich erwischt!`,"A cauda dela pegou você!":`Ihr Schwanz hat dich erwischt!`,"Ela cansou e abriu a boca: atire na cabeça agora!":`Sie ist erschöpft und öffnet das Maul: jetzt auf den Kopf schießen!`,"A Cobra-Grande voltou a dormir. O que ela perdeu de vida, continua perdido.":`Die Große Schlange schläft wieder. Verlorenes Leben bleibt verloren.`,"O Tição saiu da porta!":`Glutauge ist aus der Tür gekommen!`,"O bote do Tição pegou você!":`Glutauges Zuschnappen hat dich erwischt!`,"O Tição voltou para a porta. O que ele perdeu de vida, continua perdido.":`Glutauge ist zur Tür zurück. Was er an Leben verloren hat, bleibt verloren.`,"O boto achou um caixote: vá atrás dele!":`Der Flussdelfin hat eine Kiste gefunden: folge ihm!`,"Dormiu!":`Eingeschlafen!`,"Peixe grande demais para a linha: chegue perto para mandá-lo de boia ao barco.":`Zu groß für die Leine: Schwimm hin und schick ihn per Boje zum Boot.`,"Peixe grande demais para a linha: chegue perto para recolher.":`Zu groß für die Leine: Schwimm hin, um ihn einzusammeln.`,"Fisgou!":`Am Haken!`,"Atordoado!":`Betäubt!`,Envenenado:`Vergiftet`,"Cansou!":`Erschöpft!`,"A linha cedeu — o peixe escapou!":`Die Leine gab nach — der Fisch ist weg!`,"Você se soltou!":`Du bist frei!`,"{bicho} cansou e soltou você.":`{bicho} ist erschöpft und lässt dich los.`,"{arma}: a caixa guardada entrou, +{tiros} de munição":`{arma}: Reservekasten geladen, +{tiros} Munition`,"{arma} sem munição: ficou para trás.":`{arma} leer: zurückgelassen.`,"Adormecido, o peixe fica parado: chegue perto para recolher. Vem vivo, com 3 estrelas.":`Der Fisch schläft und bleibt stehen: Schwimm hin und sammle ihn ein. Lebend, mit 3 Sternen.`,"Grogue! Mais um dardo":`Benommen! Noch ein Pfeil`,"Abatido a tiro, o peixe fica boiando: chegue perto para recolher. Vale 1 estrela.":`Erlegt treibt der Fisch im Wasser: Schwimm hin und sammle ihn ein. 1 Stern wert.`,"{presos} na rede!":`{presos} im Netz!`,"Forte demais para a tarrafa: esse é no arpão.":`Zu stark fürs Wurfnetz: Der braucht die Harpune.`,Zzz:`Zzz`,"Choque do poraquê!":`Zitteraal-Schock!`,"Bolsão de ar: tanque cheio":`Luftblase: Tank voll`,"Tem alguma coisa brilhando no chão, aqui perto.":`Hier in der Nähe glitzert etwas am Grund.`,Tição:`Glutauge`,"Pouco ar! Volte ao barco.":`Wenig Luft! Zurück zum Boot.`,"Fundo demais para este traje ({limite} m): o ar acaba {fator}× mais rápido. No barco tem um melhor.":`Zu tief für diesen Anzug ({limite} m): Die Luft geht {fator}× schneller aus. Im Boot gibt's einen besseren.`,"Subir no barco":`Ins Boot steigen`,"Subir pela boia":`Per Boje auftauchen`,"Abrir o caixote":`Kiste öffnen`,"Arrancar o minério com a faca":`Erz mit dem Messer lösen`,"Tirar postas com a faca":`Stücke mit dem Messer schneiden`,"Boca do Poço":`Boca do Poço`,"PEIXE NA BRASA  •  TACACÁ":`FISCH VOM GRILL  •  TACACÁ`,HOJE:`HEUTE`,"peixe fresco":`frischer Fisch`,"{nome} (doente)":`{nome} (krank)`,"Posta de {peixe}":`Stück {peixe}`,Leme:`Steuer`,Bancada:`Werkbank`,Escada:`Leiter`,"Banco da proa":`Bugbank`,"Mapa do rio":`Flusskarte`,Equipamento:`Ausrüstung`,"Descer de madrugada":`Vor dem Morgengrauen tauchen`,Mergulhar:`Tauchen`,"O rio descansa à noite":`Abends ruht der Fluss`,"Dormir sem abrir a casa":`Schlafen, ohne zu öffnen`,"Dormir até de manhã":`Bis zum Morgen schlafen`,"Descansar até a tarde":`Bis nachmittags ausruhen`,"Descansar até a noite":`Bis abends ausruhen`,Madrugada:`Vor dem Morgengrauen`,Manhã:`Morgen`,Tarde:`Nachmittag`,Noite:`Abend`,"Pasta devagar entre as raízes do igapó. Deixou o Tuca chegar perto e não teve medo.":`Weidet langsam zwischen den Wurzeln des Igapó. Ließ Tuca nah herankommen und hatte keine Angst.`,peixe:`Fisch`,"Descer ao igapó e pescar. Gasta este turno.":`In den Igapó tauchen und fischen. Kostet die Tageszeit.`,"Madrugada do dia {dia}: o igapó está escuro":`Tag {dia}, vor dem Morgengrauen: der Igapó ist dunkel`,Galhada:`Astgewirr`,"Ar preso entre as raízes: entre nele para encher o tanque.":`Luft zwischen den Wurzeln: Schwimm hinein, um den Tank zu füllen.`,"Você no igapó · barco no alto · pontos claros: bolsões de ar":`Du im Igapó · Boot oben · helle Punkte: Luftblasen`,"Descer ao poço e pescar. Gasta este turno.":`In den Kolk tauchen und fischen. Kostet die Tageszeit.`,"Madrugada do dia {dia}: o poço está escuro":`Tag {dia}, vor dem Morgengrauen: das Strudelloch ist dunkel`,Paredões:`Steilwände`,"Ar preso no teto da gruta: entre nele para encher o tanque.":`Luft unter der Höhlendecke: Schwimm hinein, um den Tank zu füllen.`,"Você no poço · barco no alto · pontos claros: bolsões de ar":`Du im Kolk · Boot oben · helle Punkte: Luftblasen`,"Poço do Raimundo":`Raimundos Kolk`,Igapó:`Igapó (Überschwemmungswald)`,"Voltar ao convés":`Zurück an Deck`,"Ancorar no poço":`Am Strudelloch ankern`,"Ancorar no igapó":`Im Igapó ankern`,"Abrir o Boca do Poço":`Boca do Poço öffnen`,"Abre à noite":`Öffnet abends`,"Nade para o fundo":`Tauch nach unten`,"Desça alguns metros. Segure Shift para arrancar, mas gasta mais ar.":`Tauch ein paar Meter ab. Halte Shift für einen Sprint, das kostet mehr Luft.`,"O ar é a sua vida":`Luft ist dein Leben`,"Este medidor é o ar do tanque. Ele cai com o tempo, mais rápido no fundo e a cada ferida.":`Diese Anzeige ist die Luft im Tank. Sie sinkt mit der Zeit, in der Tiefe schneller und mit jeder Wunde.`,"Se o ar acabar, você desmaia, é puxado de volta ao barco e perde metade do pescado. Volte antes!":`Wenn die Luft ausgeht, wirst du ohnmächtig, ins Boot zurückgezogen und verlierst die Hälfte des Fangs. Kehr rechtzeitig um!`,"Pesque um peixe":`Fang einen Fisch`,Mouse:`Maus`,"Segure o botão do mouse para mirar e solte para atirar. Peixe forte: aperte Espaço para cansá-lo.":`Halte die Maustaste zum Zielen gedrückt und lass los, um zu schießen. Starker Fisch: Drücke die Leertaste, um ihn zu ermüden.`,"O peso da carga":`Das Gewicht der Ladung`,"A barra mostra o peso que você leva e o máximo que aguenta. Cheia, não cabe mais nada.":`Der Balken zeigt, wie viel du trägst und wie viel du höchstens tragen kannst. Ist er voll, passt nichts mehr hinein.`,"Aperte C para ver a carga e solte o peixe que vale menos. Na bancada do barco dá para aumentar a capacidade.":`Drücke C, um die Ladung zu sehen, und wirf den Fisch mit dem geringsten Wert weg. An der Werkbank des Boots kannst du die Kapazität erhöhen.`,"Abra e pegue com a faca":`Mit dem Messer öffnen und nehmen`,"Perto de um caixote, de uma caixa ou de um achado, aperte F.":`Drück F bei einer Kiste, einem Kasten oder einem Fund.`,"Volte ao barco":`Zurück zum Boot`,"Suba até o barco (ou uma boia) e aperte E. O peixe que sobe vai para a cozinha.":`Schwimm hoch zum Boot (oder zu einer Boje) und drück E. Der Fang geht in die Küche.`,"Metade do ar. Vá pensando na volta.":`Halbe Luft. Denk schon an den Rückweg.`,"Só um quarto do ar! Volte ao barco ou ache um bolsão de ar.":`Nur noch ein Viertel der Luft! Zurück zum Boot oder such eine Luftblase.`,"Por que o Tuca mergulha":`Warum Tuca taucht`,"Meu neto, sem peixe não tem prato. De dia você desce o poço e traz o pescado; de noite a gente abre o Boca do Poço, e cada noite boa paga um pedaço da dívida do seu avô.":`Mein Junge, ohne Fisch kein Gericht. Tagsüber tauchst du in den Kolk und holst den Fang herauf; abends öffnen wir das Boca do Poço, und jeder gute Abend tilgt ein Stück der Schuld deines Großvaters.`,"O barco":`Das Boot`,"Ande pelo convés com A e D e aperte E em cima de um ponto.":`Geh mit A und D über das Deck und drücke E auf einem Punkt.`,"leva o barco pelo rio; de noite, até o Boca do Poço":`fährt das Boot den Fluss entlang; abends bis zum Boca do Poço`,"melhora o tanque, o traje, a carga e as armas":`verbessert Tank, Anzug, Ladung und Waffen`,"desce ao poço para pescar":`taucht in den Kolk zum Fischen`,"descansa e deixa o turno passar":`ruht sich aus und lässt die Schicht vergehen`,"O caderno de bordo":`Das Logbuch`,'Aperte Tab para abrir o caderno. Na aba "Espécies" ficam os peixes que você já pescou e onde cada um vive.':`Drücke Tab, um das Logbuch zu öffnen. Im Reiter „Arten“ stehen die Fische, die du schon gefangen hast, und wo jeder lebt.`,"A primeira noite":`Die erste Nacht`,"A e D andam pelo balcão. Os fregueses chegam, pedem, comem e pagam: cada prato servido vira moeda.":`Mit A und D läufst du an der Theke entlang. Die Gäste kommen, bestellen, essen und zahlen: Jedes servierte Gericht wird zu Münzen.`,"O pedido":`Die Bestellung`,"O balão em cima do freguês mostra o prato que ele quer.":`Die Blase über dem Gast zeigt das Gericht, das er möchte.`,"O passa-prato":`Die Durchreiche`,"Os pratos saem prontos aqui. Vá até o passa-prato e aperte E para pegar.":`Die Gerichte kommen hier fertig heraus. Geh zur Durchreiche und drücke E zum Nehmen.`,"Entregue o prato":`Gericht servieren`,"Leve o prato até quem pediu e aperte E na frente dele.":`Bring das Gericht zu dem, der es bestellt hat, und drücke E vor ihm.`,"A louça":`Das Geschirr`,"Quem comeu deixa a louça no balcão. Aperte E em cima dela para limpar o lugar para o próximo freguês.":`Wer gegessen hat, lässt das Geschirr auf der Theke stehen. Drücke E darauf, um den Platz für den nächsten Gast frei zu machen.`,"O tacacá":`Der Tacacá`,"Tacacá se serve na hora: segure E para encher a cuia e solte na marca.":`Tacacá wird frisch serviert: Halte E gedrückt, um die Kalebasse zu füllen, und lass an der Markierung los.`,"Quem espera, cansa":`Wer wartet, wird müde`,"Quem espera demais vai embora sem pagar, e a fama cai. Sirva primeiro quem chegou antes.":`Wer zu lange wartet, geht ohne zu zahlen, und der Ruf sinkt. Bediene zuerst, wer zuerst kam.`,"O caderno do Regatão":`Das Buch des Flusshändlers`,"Fechada a casa, o Regatão anota a noite: o que vendeu, o que gastou e a fama. O lucro de cada noite boa paga um pedaço da dívida do avô.":`Nach Feierabend notiert der Flusshändler die Nacht: was verkauft wurde, was ausgegeben wurde und den Ruf. Der Gewinn jeder guten Nacht tilgt ein Stück der Schuld des Großvaters.`,Pular:`Überspringen`,Raso:`Flachwasser`,Abismo:`Abgrund`,Espaço:`Leertaste`,"{distancia} m":`{distancia} m`,"Liga e desliga o som (tecla M)":`Ton an/aus (Taste M)`,Volume:`Lautstärke`,"Ar no tanque":`Luft im Tank`,"{metros} m · {faixa}":`{metros} m · {faixa}`,"pressão!":`Druck!`,"{peso}/{capacidade} kg":`{peso}/{capacidade} kg`,"Ver o que você pegou (tecla C)":`Deinen Fang ansehen (Taste C)`,Carga:`Ladung`,"{peso} kg · {valor} moedas":`{peso} kg · {valor} Münzen`,Arpão:`Harpune`,"Mouse 1":`Maus 1`,"Tarrafa: traz vivos os peixes pequenos":`Wurfnetz: fängt kleine Fische lebend`,Faca:`Messer`,"Lanterna (acende sozinha no escuro)":`Lampe (geht im Dunkeln von selbst an)`,"<kbd>Tab</kbd> troca":`<kbd>Tab</kbd> wechseln`,"<kbd>WASD</kbd> nada · <kbd>Shift</kbd> arrancada · <kbd>Mouse 1</kbd> segure para mirar, solte para atirar · <kbd>Tab</kbd> troca a arma · <kbd>F</kbd> faca · <kbd>C</kbd> carga · <kbd>Q</kbd> apetrecho":`<kbd>WASD</kbd> schwimmen · <kbd>Shift</kbd> Sprint · <kbd>Maus 1</kbd> halten zum Zielen, loslassen zum Schießen · <kbd>Tab</kbd> Waffe wechseln · <kbd>F</kbd> Messer · <kbd>C</kbd> Ladung · <kbd>Q</kbd> Hilfsmittel`,"Pular o tutorial":`Tutorial überspringen`,pular:`überspringen`,"Nada pescado ainda":`Noch nichts gefangen`,"{peso} kg":`{peso} kg`,"Soltar um (libera o peso)":`Einen abwerfen (spart Gewicht)`,"Arpão · {ponta}":`Harpune · {ponta}`,"{arma} (achada num caixote: vale só neste mergulho)":`{arma} (aus einer Kiste: nur für diesen Tauchgang)`,"Arpão sem ponta":`Harpune ohne Spitze`,"{ponta} · tarrafa {lances} · boias {boias} · {arma} {municao}":`{ponta} · Netz {lances} · Bojen {boias} · {arma} {municao}`,"{ponta} · tarrafa {lances} · boias {boias}":`{ponta} · Netz {lances} · Bojen {boias}`,Baixo:`Niedrig`,"Para computador fraco: sem brilho nas luzes e menos partículas.":`Für schwache Computer: kein Leuchten an den Lichtern und weniger Partikel.`,Médio:`Mittel`,"Resolução um pouco menor, brilho mais leve e menos partículas.":`Etwas geringere Auflösung, sanfteres Leuchten und weniger Partikel.`,Alto:`Hoch`,"O rio com tudo o que ele tem.":`Der Fluss mit allem, was er hat.`,"Opções (Esc)":`Optionen (Esc)`,Opções:`Optionen`,"Fechar (Esc)":`Schließen (Esc)`,Som:`Ton`,"Volume geral":`Gesamtlautstärke`,Música:`Musik`,Efeitos:`Effekte`,"Interface e voz":`Oberfläche und Stimme`,Mudo:`Stumm`,Gráficos:`Grafik`,Interface:`Oberfläche`,Tamanho:`Größe`,"Tamanho da interface":`Größe der Oberfläche`,Idioma:`Sprache`,"Trocar de idioma recarrega o jogo. O progresso fica salvo.":`Beim Sprachwechsel wird das Spiel neu geladen. Dein Fortschritt bleibt gespeichert.`,Continuar:`Weiter`,"Sem som":`Ohne Ton`,"Som ligado":`Ton an`,"Voltar mesmo? O que não foi guardado se perde.":`Wirklich zurück? Nicht Gespeichertes geht verloren.`,"Voltar ao título":`Zurück zum Titel`,"<kbd>A</kbd><kbd>D</kbd> andar pelo convés · <kbd>E</kbd> usar · <kbd>Tab</kbd> caderno de bordo":`<kbd>A</kbd><kbd>D</kbd> übers Deck gehen · <kbd>E</kbd> benutzen · <kbd>Tab</kbd> Logbuch`,"<kbd>A</kbd><kbd>D</kbd> escolher o lugar · <kbd>E</kbd> navegar até lá · <kbd>Esc</kbd> voltar ao convés":`<kbd>A</kbd><kbd>D</kbd> Ort wählen · <kbd>E</kbd> hinfahren · <kbd>Esc</kbd> zurück an Deck`,"Dia {dia}":`Tag {dia}`,"Caderno de bordo (Tab)":`Logbuch (Tab)`,Caderno:`Logbuch`,Tab:`Tab`,"Caderno de bordo":`Logbuch`,"Dia {dia} · {turno}":`Tag {dia} · {turno}`,"O que fazer":`Was tun`,"Como jogar":`Anleitung`,Espécies:`Arten`,"O progresso fica salvo.":`Dein Fortschritt bleibt gespeichert.`,"Sair do jogo":`Spiel beenden`,"O dia":`Der Tag`,"<b>Manhã e tarde</b>um mergulho em cada turno":`<b>Morgens und nachmittags</b>je ein Tauchgang`,"<b>No barco</b>o peixe que sobe vai para a despensa":`<b>Im Boot</b>der Fang kommt in den Vorrat`,"<b>Noite</b>o Boca do Poço abre e você serve no balcão":`<b>Abends</b>das Boca do Poço öffnet, du bedienst an der Theke`,"<b>Com o ouro</b>mais ar, mais carga e mais fundo":`<b>Mit dem Gold</b>mehr Luft, mehr Ladung, mehr Tiefe`,"No mergulho":`Beim Tauchen`,"<kbd>WASD</kbd> nadar · <kbd>Shift</kbd> arrancada":`<kbd>WASD</kbd> schwimmen · <kbd>Shift</kbd> Sprint`,"<kbd>Mouse</kbd> segure para mirar, solte para atirar":`<kbd>Maus</kbd> halten zum Zielen, loslassen zum Schießen`,"<kbd>F</kbd> faca: abre caixote, pega achado":`<kbd>F</kbd> Messer: öffnet Kisten, nimmt Funde`,"<kbd>Tab</kbd> troca a arma · <kbd>C</kbd> carga":`<kbd>Tab</kbd> Waffe wechseln · <kbd>C</kbd> Ladung`,"<kbd>E</kbd> subir no barco ou pela boia":`<kbd>E</kbd> ins Boot oder per Boje hoch`,"No restaurante":`Im Restaurant`,"<kbd>A</kbd><kbd>D</kbd> andar pelo balcão":`<kbd>A</kbd><kbd>D</kbd> an der Theke entlang`,"<kbd>E</kbd> pegar, servir, limpar e socar":`<kbd>E</kbd> nehmen, servieren, putzen, stampfen`,"segure <kbd>E</kbd> para encher a cuia de tacacá":`<kbd>E</kbd> halten: Kalebasse mit Tacacá füllen`,Lembranças:`Erinnerungen`,"<kbd>A</kbd><kbd>D</kbd> escolher · <kbd>E</kbd> ou <kbd>Enter</kbd> fazer · <kbd>C</kbd> páginas · <kbd>Tab</kbd> ou <kbd>Esc</kbd> fechar":`<kbd>A</kbd><kbd>D</kbd> wählen · <kbd>E</kbd> oder <kbd>Enter</kbd> ausführen · <kbd>C</kbd> Seiten · <kbd>Tab</kbd> oder <kbd>Esc</kbd> schließen`,"Fama <b>{fama}</b>":`Ruf <b>{fama}</b>`,"Despensa <b>{n}</b> peixe":{one:`Vorrat <b>{n}</b> Fisch`,other:`Vorrat <b>{n}</b> Fische`},"<b>{n}</b> de {total} espécies no caderno":`<b>{n}</b> von {total} Arten im Heft`,"{n} pescado":{one:`{n} gefangen`,other:`{n} gefangen`},"maior: {peso} kg":`größter: {peso} kg`,"Vive entre {min} e {max} m":`Lebt in {min} bis {max} m`,"3★ rende {corte}":`3★ ergibt {corte}`,"Encontro anotado":`Begegnung notiert`,"Fama no rio · {grau}":`Ruf am Fluss · {grau}`,Canoa:`Kanu`,farinha:`Mehl`,"<kbd>A</kbd><kbd>D</kbd> andar · <kbd>E</kbd> ou <kbd>espaço</kbd> pegar, servir, limpar e socar · segure para encher a cuia":`<kbd>A</kbd><kbd>D</kbd> gehen · <kbd>E</kbd> oder <kbd>Leertaste</kbd> nehmen, servieren, putzen, stampfen · halten zum Füllen`,limpar:`putzen`,"{n} moeda":{one:`{n} Münze`,other:`{n} Münzen`},"hora de abrir o Boca do Poço":`Zeit, das Boca do Poço zu öffnen`,"descer no escuro ou dormir até de manhã":`im Dunkeln tauchen oder bis zum Morgen schlafen`,"dois mergulhos até a noite":`zwei Tauchgänge bis zum Abend`,"último mergulho antes da noite":`letzter Tauchgang vor dem Abend`,"Primeiro mergulho":`Erster Tauchgang`,"{n} mergulho":{one:`{n} Tauchgang`,other:`{n} Tauchgänge`},"Melhor mergulho: {moedas} · {vezes}":`Bester Tauchgang: {moedas} · {vezes}`,"no máximo":`Maximum`,"Ache esta arma nos caixotes para liberar o projeto: {achadas} de {precisa}.":`Finde diese Waffe in Kisten, um den Bauplan freizuschalten: {achadas} von {precisa}.`,"✓ Levando":`✓ Dabei`,Levar:`Mitnehmen`,"{n} peça · −{desconto}% de ouro":{one:`{n} Teil · −{desconto}% Münzen`,other:`{n} Teile · −{desconto}% Münzen`},"O rio está acordando":`Der Fluss erwacht`,"Ainda dá um mergulho":`Ein Tauchgang geht noch`,"A noite é do Boca do Poço":`Der Abend gehört dem Boca do Poço`,"De dia, o poço · de noite, o balcão":`Tags der Kolk · abends die Theke`,"O Tuca pesca no fundo do poço para abastecer o balcão do <strong>restaurante flutuante</strong> da Dona Naná.":`Tuca fischt tief im Kolk für die Theke von Dona Nanás <strong>schwimmendem Lokal</strong>.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa enche o balcão da Dona Naná.":`Was Tuca aus dem Fluss holt, wird zum Gericht des Abends, und jede gute Nacht füllt Dona Nanás Theke.`,"O que o Tuca traz do rio vira o prato da noite, e cada noite boa paga um pedaço da dívida do avô.":`Was Tuca aus dem Fluss holt, kommt abends auf den Teller, und jeder gute Abend tilgt ein Stück von Opas Schulden.`,"No barco":`Im Boot`,Começar:`Starten`,"Como o jogo funciona":`So funktioniert's`,"<b>Mergulhe</b>Pesque e junte achados enquanto o ar durar.":`<b>Tauchen</b>Fische fangen und Funde sammeln, solange die Luft reicht.`,"<b>Volte ao barco</b>O peixe que sobe vai para a despensa do restaurante.":`<b>Zurück zum Boot</b>Der Fang kommt in den Vorrat des Restaurants.`,"<b>À noite, abra o Boca do Poço</b>Monte o cardápio e sirva os fregueses no balcão.":`<b>Abends das Boca do Poço öffnen</b>Stell die Karte zusammen und bediene die Gäste an der Theke.`,"<b>Melhore o barco</b>Com o ouro, mais ar, mais carga e mais fundo.":`<b>Boot verbessern</b>Mit dem Gold: mehr Luft, mehr Ladung, mehr Tiefe.`,"O dia tem dois mergulhos, um de manhã e um de tarde; à noite o restaurante abre com o que você pescou. A nota da noite e a fama crescem com o capricho no serviço.":`Jeder Tag hat zwei Tauchgänge, morgens und nachmittags; abends öffnet das Restaurant mit deinem Fang. Guter Service bringt bessere Noten und mehr Ruf.`,"<kbd>WASD</kbd> nadar":`<kbd>WASD</kbd> schwimmen`,"<kbd>Mouse 1</kbd> segure para mirar, solte para atirar":`<kbd>Maus 1</kbd> halten zum Zielen, loslassen zum Schießen`,"<kbd>Shift</kbd> arrancada (gasta mais ar)":`<kbd>Shift</kbd> Sprint (kostet mehr Luft)`,"<kbd>Tab</kbd> arpão · arma · tarrafa · faca":`<kbd>Tab</kbd> Harpune · Waffe · Wurfnetz · Messer`,"<kbd>F</kbd> faca: abre caixote e caixa de munição, pega achado e arranca minério":`<kbd>F</kbd> Messer: öffnet Kisten und Munitionskästen, nimmt Funde, löst Erz`,"<kbd>Espaço</kbd> contra peixe forte":`<kbd>Leertaste</kbd> gegen starke Fische`,"<kbd>C</kbd> carga":`<kbd>C</kbd> Ladung`,"<kbd>E</kbd> subir (barco ou boia)":`<kbd>E</kbd> hoch (Boot oder Boje)`,"<kbd>Q</kbd> apetrecho de defesa: nuvem de urucum ou chamariz de pano":`<kbd>Q</kbd> Abwehrmittel: Urucum-Wolke oder Stoffköder`,"<kbd>M</kbd> som":`<kbd>M</kbd> Ton`,"Volte ao barco antes que o ar acabe: o peixe que sobe vai para a cozinha.":`Zurück zum Boot, bevor die Luft ausgeht: Der Fang geht in die Küche.`,"<kbd>E</kbd> ou <kbd>Espaço</kbd> pegar o prato, servir, limpar e socar o pilão":`<kbd>E</kbd> oder <kbd>Leertaste</kbd> Gericht nehmen, servieren, putzen, im Mörser stampfen`,"Sirva a cada freguês o prato que ele pediu antes que a paciência acabe.":`Bring jedem Gast sein Gericht, bevor ihm die Geduld ausgeht.`,"Com controle":`Mit Controller`,"<kbd>Analógico esquerdo</kbd> nadar e andar · <kbd>LT</kbd> arrancada":`<kbd>Linker Stick</kbd> schwimmen und gehen · <kbd>LT</kbd> Sprint`,"<kbd>RT</kbd> segure para mirar com o <kbd>analógico direito</kbd>, solte para atirar":`<kbd>RT</kbd> halten und mit dem <kbd>rechten Stick</kbd> zielen, loslassen zum Schießen`,"<kbd>A</kbd> usar · <kbd>B</kbd> voltar · <kbd>X</kbd> faca · <kbd>Y</kbd> troca a arma · <kbd>LB</kbd> carga · <kbd>R3</kbd> apetrecho":`<kbd>A</kbd> benutzen · <kbd>B</kbd> zurück · <kbd>X</kbd> Messer · <kbd>Y</kbd> Waffe wechseln · <kbd>LB</kbd> Ladung · <kbd>R3</kbd> Hilfsmittel`,Entendi:`Verstanden`,"Fim do mergulho":`Tauchgang vorbei`,"Você desmaiou":`Du bist ohnmächtig geworden`,"Subiu pela boia":`Per Boje aufgetaucht`,"Você foi puxado para o barco às pressas e só conseguiu segurar a metade mais leve da carga.":`Du wurdest hastig ins Boot gezogen und konntest nur die leichtere Hälfte der Ladung halten.`,"Você voltou de mãos vazias. O rio continua lá.":`Du kommst mit leeren Händen zurück. Der Fluss läuft nicht weg.`,"Tudo o que você pescou e achou chegou ao barco.":`Alles, was du gefangen und gefunden hast, ist im Boot.`,"Ficou para trás":`Zurückgelassen`,"Guardado no barco para construir armas: {itens}":`Im Boot verstaut, für den Waffenbau: {itens}`,"Para a despensa do Boca do Poço (não entra no total): {porcoes}":`Für den Vorrat des Boca do Poço (nicht in der Summe): {porcoes}`,"<b>{n}</b> porção de {peixe}":{one:`<b>{n}</b> Portion {peixe}`,other:`<b>{n}</b> Portionen {peixe}`},"Cortes nobres para a cozinha: {cortes}":`Edle Stücke für die Küche: {cortes}`,"<b>{n}</b> porção de {corte}":{one:`<b>{n}</b> Portion {corte}`,other:`<b>{n}</b> Portionen {corte}`},'Seu Agenor levou <b>{n}</b> peixe doente: +{ouro}. "Não pergunto de onde veio."':{one:`Agenor hat <b>{n}</b> kranken Fisch mitgenommen: +{ouro}. „Ich frage nicht, woher.“`,other:`Agenor hat <b>{n}</b> kranke Fische mitgenommen: +{ouro}. „Ich frage nicht, woher.“`},"Novas no caderno de espécies: {peixes}":`Neu im Artenheft: {peixes}`,"Encomendas do flutuante":`Bestellungen fürs Lokal`,"Total com encomendas":`Summe mit Bestellungen`,Total:`Summe`,"Novo recorde!":`Neuer Rekord!`,"Voltar ao barco":`Zurück zum Boot`,"{preco} o prato · {n} porção na despensa":{one:`{preco} pro Gericht · {n} Portion im Vorrat`,other:`{preco} pro Gericht · {n} Portionen im Vorrat`},"Boca do Poço · fama {grau}":`Boca do Poço · Ruf {grau}`,"O cardápio da noite":`Die Abendkarte`,"Escolha até {vagas} pratos. Hoje vêm {fregueses} fregueses; o que sobrar volta para a despensa.":`Wähle bis zu {vagas} Gerichte. Heute kommen {fregueses} Gäste; Reste gehen zurück in den Vorrat.`,"Abrir com {n} porção":{one:`Mit {n} Portion öffnen`,other:`Mit {n} Portionen öffnen`},"Abrir só com cafezinho":`Nur mit Kaffee öffnen`,"Equipe · {equipe}":`Team · {equipe}`,Equipe:`Team`,"A casa":`Das Lokal`,"Vender a despensa ao Regatão · {moedas}":`Vorrat an den Flusshändler · {moedas}`,Voltar:`Zurück`,"Você achou":`Du hast gefunden`,"Guardar e continuar":`Einstecken und weiter`,"<strong>{ouro}</strong> moedas":`<strong>{ouro}</strong> Münzen`,"Cada melhoria aparece no flutuante e vale em todas as noites.":`Jede Verbesserung sieht man am Lokal, und sie gilt jeden Abend.`,"Voltar ao cardápio":`Zurück zur Karte`,"Contratar · {preco}":`Einstellen · {preco}`,"Na noite ✓":`Im Dienst ✓`,"Pôr na noite":`Einteilen`,"Sem vaga":`Kein Platz`,"diária de {valor}":`Tageslohn {valor}`,"Com a fama {grau} ainda não cabe ajudante atrás do balcão.":`Mit Ruf {grau} passt noch kein Helfer hinter die Theke.`,"Com a fama {grau} cabe {n} ajudante por noite.":{one:`Mit Ruf {grau} passt {n} Helfer pro Abend.`,other:`Mit Ruf {grau} passen {n} Helfer pro Abend.`},"Na fama {grau} abre a primeira vaga.":{one:`Ab Ruf {grau} gibt es den ersten Platz.`,other:`Ab Ruf {grau} passen {n}.`},"A equipe":`Das Team`,"O contrato se paga uma vez; a diária sai do lucro da noite.":`Den Vertrag zahlst du einmal; der Tageslohn geht vom Abendgewinn ab.`,"Na noite: <b>{escalados} de {vagas}</b> · diárias de {moedas}":`Im Dienst: <b>{escalados} von {vagas}</b> · Löhne {moedas}`,"Na noite: <b>{escalados} de {vagas}</b>":`Im Dienst: <b>{escalados} von {vagas}</b>`,hoje:`heute`,"dia {dia}":`Tag {dia}`,"De tirar o chapéu":`Hut ab`,"Casa elogiada":`Viel Lob`,"Deu para o gasto":`Hat gereicht`,"Noite atrapalhada":`Chaotischer Abend`,"Noite para esquecer":`Abend zum Vergessen`,"{n} freguês foi embora sem comer":{one:`{n} Gast ging ohne Essen`,other:`{n} Gäste gingen ohne Essen`},"{n} prato foi parar na banqueta errada":{one:`{n} Gericht landete am falschen Platz`,other:`{n} Gerichte landeten am falschen Platz`},"os pratos demoraram a chegar":`die Gerichte kamen spät`,"As lamparinas se apagam. Seu Agenor abre o caderno só para somar o que a casa fez.":`Die Öllampen gehen aus. Seu Agenor schlägt sein Buch nur auf, um zusammenzuzählen, was das Haus geschafft hat.`,"As lamparinas se apagam. Seu Agenor abre o caderno e faz as contas da casa.":`Die Öllampen gehen aus. Seu Agenor schlägt sein Buch auf und rechnet ab.`,"Caderno da casa":`Buch des Hauses`,"Caderno do Regatão":`Buch des Flusshändlers`,"Noite do dia {dia}":`Abend von Tag {dia}`,"Saiu da cozinha":`Aus der Küche`,"{n} prato":{one:`{n} Gericht`,other:`{n} Gerichte`},"O mais pedido foi o <b>{prato}</b>: {fatia}% do que entrou.":`Am meisten bestellt: <b>{prato}</b>, {fatia} % der Einnahmen.`,"Nenhum prato saiu hoje.":`Heute ging kein Gericht raus.`,"As últimas noites":`Die letzten Abende`,"o que ficou em caixa":`was in der Kasse blieb`,"A melhor noite que este caderno já viu!":`Der beste Abend, den dieses Buch je gesehen hat!`,"Fama no rio: <b>{grau}</b> <em>subiu!</em>":`Ruf am Fluss: <b>{grau}</b> <em>gestiegen!</em>`,"Fama no rio: <b>{grau}</b>":`Ruf am Fluss: <b>{grau}</b>`,"{ganho} nesta noite, com +{premio} pelo capricho":`{ganho} heute Abend, mit +{premio} für Sorgfalt`,"{ganho} nesta noite":`{ganho} heute Abend`,"faltam {faltam} para {grau}":`noch {faltam} bis {grau}`,"Contas da noite":`Abendabrechnung`,"{n} freguês servido":{one:`{n} Gast bedient`,other:`{n} Gäste bedient`},Pratos:`Gerichte`,Gorjetas:`Trinkgeld`,"Despesa da casa":`Hauskosten`,"Diárias da equipe":`Teamlöhne`,"Faltou no caixa":`Fehlbetrag`,"Ficou em caixa":`In der Kasse`,"conceito da noite":`Note des Abends`,"{nota} de 5":`{nota} von 5`,"Ninguém saiu reclamando.":`Niemand ging mit Beschwerden.`,"Conferido por <b>Seu Agenor, o Regatão</b>":`Geprüft von <b>Seu Agenor, dem Flusshändler</b>`,"Dormir · amanhã é dia {dia}":`Schlafen · morgen ist Tag {dia}`,Barco:`Boot`,Armas:`Waffen`,"Achar a mesma arma duas vezes nos caixotes libera o projeto. O material do poço fica guardado aqui, e a arma construída desce com você em todo mergulho.":`Findest du dieselbe Waffe zweimal in Kisten, wird der Bauplan frei. Material aus dem Kolk wird hier gelagert, und die gebaute Waffe ist bei jedem Tauchgang dabei.`,Zarabatana:`Blasrohr`,"6 dardos com timbó: o peixe dorme e vem vivo":`6 Pfeile mit Timbó: Der Fisch schläft und bleibt am Leben`,"Espingarda de pressão":`Luftgewehr`,"6 tiros de três chumbos, para perto":`6 Schuss zu je drei Kugeln, für kurze Distanz`,Balestra:`Armbrust`,"4 setas pesadas, que atravessam":`4 schwere Bolzen, die durchschlagen`,"A noite da cheia":`Die Nacht der Flut`,"Na boca do poço mais fundo do rio há um flutuante. Seu Raimundo mergulhava, Dona Naná cozinhava, e não passava barco que não encostasse.":`Am Rand des tiefsten Kolks im Fluss liegt ein schwimmendes Lokal. Seu Raimundo tauchte, Dona Naná kochte, und kein Boot fuhr vorbei, ohne anzulegen.`,"Tuca, o neto, voltou da cidade com uma mala e o fôlego do avô. De dia ele desce o poço. De noite, o Boca do Poço abre.":`Tuca, der Enkel, kam aus der Stadt zurück, mit einem Koffer und dem langen Atem seines Opas. Tagsüber taucht er in den Kolk. Abends öffnet das Boca do Poço.`,"O dia tem dois mergulhos, um de manhã e um de tarde. O peixe que sobe ao barco vira o prato da noite, e cada noite bem servida paga um pedaço da dívida. O rio está esperando.":`Jeder Tag hat zwei Tauchgänge, morgens und nachmittags. Der Fang im Boot wird zum Abendessen, und jeder gut bediente Abend tilgt ein Stück der Schulden. Der Fluss wartet.`,"O Tição":`Glutauge`,"A volta do avô":`Großvaters Rückkehr`,"Cobra-Grande":`Große Schlange`,"Escama da Cobra-Grande":`Schuppe der Großen Schlange`,Tuca:`Tuca`,"Dona Naná":`Dona Naná`,"Seu Agenor, o Regatão":`Seu Agenor, der Flusshändler`,Curimatã:`Curimatã`,Jaci:`Jaci`,"Seu Bené":`Seu Bené`,Piaba:`Piaba`,"Seu Raimundo":`Raimundo`,"Seu Takeshi":`Seu Takeshi`,Kauê:`Kauê`,"Dona Zefa":`Dona Zefa`,"Seu Juvenal":`Seu Juvenal`,Ingrid:`Ingrid`,Tião:`Tião`,"Seu Dico":`Seu Dico`,"Dois tucunarés":`Zwei Pfauenbarsche`,"Um tambaqui":`Ein Tambaqui`,"Três piranhas":`Drei Piranhas`,"Dois pacus vivos":`Zwei lebende Pacus`,"Uma arraia":`Ein Rochen`,"Um poraquê":`Ein Zitteraal`,"Um pirarucu":`Ein Pirarucu`,"Cinco jaraquis":`Fünf Jaraquis`,"Duas matrinxãs":`Zwei Matrinchãs`,"Três frutos da mata":`Drei Waldfrüchte`,"Dois minérios":`Zwei Erze`,"Duas conchas":`Zwei Muscheln`,Pacu:`Pacu`,Aracu:`Aracu`,"Acará-disco":`Diskus`,Piranha:`Piranha`,Tucunaré:`Pfauenbarsch`,Tambaqui:`Tambaqui`,Arraia:`Rochen`,Traíra:`Traíra`,Sucuri:`Anakonda`,Surubim:`Surubim`,Pirarara:`Pirarara`,Candiru:`Candiru`,Poraquê:`Zitteraal`,"Peixe-cachorro":`Payara`,Pirarucu:`Pirarucu`,Jaú:`Jaú`,Piraíba:`Piraíba`,Aruanã:`Arowana`,Jaraqui:`Jaraqui`,Matrinxã:`Matrinchã`,Tamuatá:`Tamuatá-Wels`,"Peixe-boi":`Seekuh`,Acari:`Acari-Harnischwels`,Mandi:`Mandi-Wels`,Ituí:`Ituí-Messerfisch`,Jacaré:`Kaiman`,"A volta":`Die Rückkehr`,"Tu cresceu, menino. E voltou magro. Senta, que conversa de barriga vazia não presta.":`Groß bist du geworden, Junge. Und dünn. Setz dich, mit leerem Magen redet sich's schlecht.`,"Vó, que caderno é esse em cima do balcão?":`Oma, was ist das für ein Buch auf der Theke?`,"É do Seu Agenor, o Regatão. Teu avô comprou fiado nele a vida toda. Agora ele diz que a conta é do tamanho do flutuante.":`Das gehört Seu Agenor, dem Flusshändler. Dein Opa hat sein Leben lang bei ihm anschreiben lassen. Jetzt sagt er, die Rechnung ist so groß wie das ganze Lokal.`,"Do tamanho do flutuante e mais a canoa, Dona Naná. Mas eu sou homem de paciência: pagando a parcela, eu espero.":`So groß wie das Lokal, und das Kanu dazu, Dona Naná. Aber ich bin ein geduldiger Mann: Solange die Raten kommen, warte ich.`,"Então a gente paga. Eu trago o peixe do poço, a senhora cozinha.":`Dann zahlen wir eben. Ich hol den Fisch aus dem Kolk, du kochst.`,"Teu avô dizia a mesma coisa, com essa mesma cara. Anda, abre a casa.":`Das hat dein Opa auch gesagt, mit genau dem Gesicht. Los, mach den Laden auf.`,"O arpão do avô":`Opas Harpune`,"Primeira parcela, contadinha. Quem diria: o balcão voltou a encher.":`Erste Rate, auf den Cent genau. Wer hätte das gedacht: Die Theke ist wieder voll.`,"Anota aí que pagou, Agenor. De caneta, que lápis teu apaga sozinho.":`Schreib auf, dass bezahlt ist, Agenor. Mit Kuli, dein Bleistift radiert sich ja von selbst.`,"Tuca, teu avô perdeu o arpão dele no raso, na última cheia. Ele amarrava as receitas no cabo, para não molhar na canoa.":`Tuca, dein Opa hat beim letzten Hochwasser seine Harpune im Flachwasser verloren. Er band seine Rezepte an den Schaft, damit sie im Kanu nicht nass wurden.`,"Receita amarrada em arpão?":`Rezepte an einer Harpune?`,"Ele pescava pensando no prato. Se tu achar, traz. Tem coisa naquele caderno que nem eu sei fazer.":`Er hat beim Fischen schon ans Essen gedacht. Wenn du sie findest, bring sie mit. In dem Heft steht Zeug, das nicht mal ich kochen kann.`,"O arpão do avô está em algum canto do raso, fincado no chão.":`Opas Harpune steckt irgendwo im Flachwasser im Boden.`,"Arraia não se pesca com pressa nem se cozinha com pressa. Leite de coco, coentro do quintal e fogo baixo. Naná diz que não gosta. Naná repete o prato.":`Rochen fängt man nicht in Eile und kocht ihn nicht in Eile. Kokosmilch, Koriander aus dem Garten und kleine Flamme. Naná sagt, sie mag das nicht. Naná nimmt Nachschlag.`,"Receita nova no Boca do Poço: moqueca de arraia. As arraias que você pescar agora vão para a despensa.":`Neues Rezept im Boca do Poço: Rochen-Moqueca. Rochen, die du jetzt fängst, kommen in den Vorrat.`,"As luzes do fundo":`Die Lichter in der Tiefe`,"Parcela paga, Dona Naná. Casa cheia, caderno em dia: assim que eu gosto.":`Rate bezahlt, Dona Naná. Volles Haus, Buch auf dem Laufenden: so mag ich das.`,"Anota e vai embora, Agenor.":`Schreib's auf und geh, Agenor.`,"Já vou. Só um aviso de amigo: subiu uma draga pelo rio. Gente de fora, gente de dinheiro. Andam perguntando do poço.":`Ich geh ja. Nur ein Rat unter Freunden: Ein Schwimmbagger ist den Fluss heraufgekommen. Fremde, Leute mit Geld. Sie fragen nach dem Strudelloch.`,"Perguntando o quê?":`Was fragen sie?`,"Quanto ele tem de fundo. E de quem é este flutuante.":`Wie tief es ist. Und wem dieses schwimmende Haus gehört.`,"Teu avô descia de madrugada, sabia? Depois de fechar a casa. Levava a lamparina e dizia que, no escuro, o fundo do poço acendia.":`Dein Großvater ist vor dem Morgengrauen getaucht, wusstest du das? Nach Feierabend. Er nahm die Öllampe mit und sagte, im Dunkeln leuchte der Grund des Strudellochs.`,"Eu achava que era cachaça. Na noite da cheia ele desceu com ela e não voltou.":`Ich dachte, das sei der Cachaça. In der Nacht der Flut ging er damit hinunter und kam nie zurück.`,"Então hoje, quando a casa fechar, eu desço.":`Dann tauche ich heute hinunter, wenn wir zumachen.`,"Leva o casaco. E volta, que eu não tenho mais idade para esperar ninguém na beira.":`Nimm die Jacke mit. Und komm zurück: Ich bin zu alt, um noch einmal am Ufer auf jemanden zu warten.`,"A lamparina do avô":`Großvaters Öllampe`,"A lamparina do avô está no fundo, onde ele descia de madrugada.":`Großvaters Öllampe liegt in der Tiefe, wo er vor dem Morgengrauen tauchte.`,"Eles cantam lá embaixo, Naná. Tu não acredita, mas eu vi as luzes. O jacaré velho fugiu do igarapé: a draga revirou o fundo de lá e ele veio parar no nosso poço, com raiva. A draga vem vindo. Hoje eu desço para avisar os do fundo. Se eu demorar, guarda a brasa acesa.":`Sie singen dort unten, Naná. Du glaubst mir nicht, aber ich habe die Lichter gesehen. Der alte Kaiman ist aus dem Bach geflohen: Der Bagger hat dort den Grund aufgewühlt, und er ist wütend in unserem Strudelloch gelandet. Der Bagger kommt näher. Heute tauche ich hinunter, um die da unten zu warnen. Wenn ich mich verspäte, lass die Glut nicht ausgehen.`,"A lamparina agora é tua: a lanterna alcança mais longe. E no caderno, duas receitas novas: acari assado e caldo de mandi.":`Die Lampe gehört jetzt dir: Deine Taschenlampe reicht weiter. Und im Notizbuch zwei neue Rezepte: gebratener Acari und Mandi-Brühe.`,"O homem da draga":`Der Mann vom Bagger`,"Dona Naná, trouxe uma visita. Gente importante, de fora.":`Dona Naná, ich habe Besuch mitgebracht. Ein wichtiger Mann, von auswärts.`,"Doutor Brandão, minha senhora. Bonito o seu flutuante. Bem na boca do poço.":`Doktor Brandão, gnädige Frau. Schönes schwimmendes Haus. Genau an der Mündung des Strudellochs.`,"Se veio comer, senta. Se veio olhar, a vista é de graça.":`Wenn Sie essen wollen, setzen Sie sich. Wenn Sie schauen wollen, die Aussicht ist umsonst.`,"Vim fazer negócio. Pago o dobro da dívida, à vista. A senhora descansa e eu ancoro a minha draga aqui.":`Ich komme geschäftlich. Ich zahle das Doppelte der Schuld, bar. Sie ruhen sich aus, und ich ankere meinen Bagger hier.`,"Este flutuante não está à venda. Nem pelo dobro, nem pelo triplo.":`Dieses Haus steht nicht zum Verkauf. Nicht fürs Doppelte, nicht fürs Dreifache.`,"Tudo no rio tem preço, minha senhora. Às vezes quem cobra é o rio.":`Alles am Fluss hat seinen Preis, gnädige Frau. Manchmal ist es der Fluss, der kassiert.`,"Vó, de madrugada tem um jacaré enorme rondando a tona. Os olhos parecem brasa.":`Oma, vor dem Morgengrauen streift ein riesiger Kaiman nahe der Oberfläche herum. Seine Augen sehen aus wie Glut.`,"É o Tição. Teu avô falava dele. Desce com a faca na mão, menino.":`Das ist Glutauge. Dein Großvater hat von ihm erzählt. Tauch mit dem Messer in der Hand, Junge.`,"A faca do avô":`Großvaters Messer`,"A faca do avô ficou no meio do poço, onde ele brigou com o Tição.":`Großvaters Messer liegt in der Mitte des Strudellochs, wo er mit Glutauge kämpfte.`,'Riscado no cabo, com a ponta da própria faca: "O Tição veio da draga. Bati nele três vezes e ele não largou. Se tu achar esta faca, Tuca, é tua. Não vai atrás dele: deixa ele vir, e bate na hora do bote."':`In den Griff geritzt, mit der Spitze des Messers selbst: „Glutauge kam mit dem Bagger. Ich habe dreimal zugestochen, und er hat nicht losgelassen. Wenn du dieses Messer findest, Tuca, gehört es dir. Jag ihm nicht nach: Lass ihn kommen und stich zu, wenn er zuschnappt.“`,"A faca do avô é tua: o rebate fica mais fácil e o golpe, mais forte.":`Großvaters Messer gehört dir: Abwehren wird leichter, und dein Stich trifft härter.`,"A porta":`Die Tür`,"Dona Naná... preciso contar uma coisa antes que a senhora saiba por outro.":`Dona Naná... ich muss Ihnen etwas sagen, bevor Sie es von jemand anderem hören.`,"Fala, Agenor. Mas fala de pé, que sentado tu mente melhor.":`Sprich, Agenor. Aber im Stehen: Im Sitzen lügst du besser.`,"Eu vendi a dívida do Raimundo para o Doutor Brandão. Ele quer o poço. A draga desce na próxima cheia.":`Ich habe Raimundos Schuld an Doktor Brandão verkauft. Er will das Strudelloch. Mit der nächsten Flut kommt der Bagger herunter.`,"O senhor vendeu a gente.":`Sie haben uns verkauft.`,"Vendi papel. Achei que era só papel. O Raimundo dizia que no fundo tinha uma porta, e eu ri dele.":`Ich habe Papier verkauft. Ich dachte, es sei nur Papier. Raimundo hat immer gesagt, unten gebe es eine Tür, und ich habe ihn ausgelacht.`,"Sai do meu balcão, Agenor. A despensa tu ainda compra, que eu não sou boba. Mas cafezinho aqui tu não toma mais.":`Weg von meiner Theke, Agenor. Die Vorratskammer kaufst du weiterhin, ich bin ja nicht dumm. Aber Kaffee trinkst du hier nicht mehr.`,"Uma porta no fundo do poço, vó?":`Eine Tür am Grund des Strudellochs, Oma?`,"Teu avô usava uma pedra verde no pescoço, um sapinho. Dizia que era a chave. Sumiu no dia da cheia, junto com ele.":`Dein Großvater trug einen grünen Stein um den Hals, ein Fröschchen. Er sagte, das sei der Schlüssel. Er verschwand am Tag der Flut, zusammen mit ihm.`,"O muiraquitã do avô":`Großvaters Muiraquitã`,"O muiraquitã do avô está no fundo mais fundo, onde só se chega de madrugada.":`Großvaters Muiraquitã liegt ganz tief unten, nur vor dem Morgengrauen erreichbar.`,'Amarrado no cordão do muiraquitã, um papel dobrado: "A Cobra-Grande guarda o caminho e não deixa a draga passar. A porta abre para quem leva o sapinho. Se a draga descer, os do fundo vão lutar. Eu vou com eles."':`An die Schnur des Muiraquitã gebunden, ein gefalteter Zettel: „Die Große Schlange bewacht den Weg und lässt den Bagger nicht durch. Die Tür öffnet sich dem, der das Fröschchen trägt. Wenn der Bagger herunterkommt, kämpfen die da unten. Ich gehe mit ihnen.“`,"O muiraquitã é teu. No fundo, a porta dos encantados já te espera.":`Das Muiraquitã gehört dir. Unten wartet schon die Tür der Verzauberten auf dich.`,"A cheia":`Die Flut`,"O rio subiu dois palmos desde ontem. A cheia chegou.":`Der Fluss ist seit gestern zwei Handbreit gestiegen. Die Flut ist da.`,"Recado do Doutor Brandão: a draga desce amanhã. Quem estiver no caminho, que saia.":`Nachricht von Doktor Brandão: Morgen kommt der Bagger herunter. Wer im Weg ist, soll verschwinden.`,"Hoje de madrugada eu abro a porta, vó. O Tição vai estar lá.":`Heute vor dem Morgengrauen öffne ich die Tür, Oma. Glutauge wird dort sein.`,"Teu avô disse a mesma coisa, nesta mesma noite. Volta, Tuca. Volta com ele.":`Dein Großvater hat genau das gesagt, in genau dieser Nacht. Komm zurück, Tuca. Komm mit ihm zurück.`,"Tuca! Tem um homem subindo a escada do flutuante. Molhado, de barba branca.":`Tuca! Da steigt ein Mann die Leiter zum schwimmenden Haus hoch. Klatschnass, mit weißem Bart.`,"Naná. A brasa ainda está acesa?":`Naná. Brennt die Glut noch?`,"Nunca apagou, velho teimoso. Nunca.":`Sie ist nie ausgegangen, du sturer alter Mann. Nie.`,"Os do fundo me guardaram até alguém abrir a porta. Não imaginei que ia ser o menino.":`Die da unten haben mich behütet, bis jemand die Tür öffnet. Ich hätte nie gedacht, dass es der Junge sein würde.`,"A draga afundou, vô. O Tição não volta.":`Der Bagger ist gesunken, Opa. Glutauge kommt nicht zurück.`,"E o Doutor Brandão sumiu rio abaixo. Com ele, o contrato. A dívida... a dívida não existe mais.":`Und Doktor Brandão ist flussabwärts verschwunden. Mit ihm der Vertrag. Die Schuld... die Schuld gibt es nicht mehr.`,"Então senta, Raimundo. E tu também, Agenor. Hoje o cafezinho é por conta da casa.":`Dann setz dich, Raimundo. Du auch, Agenor. Heute geht der Kaffee aufs Haus.`,"Doutor Brandão":`Doktor Brandão`,"Cilindro de ar":`Luftflasche`,"Caixa de munição":`Munitionskasten`,"Anel de ouro":`Goldring`,Muiraquitã:`Muiraquitã`,"Baú perdido":`Verlorene Truhe`,"Cuia de prata":`Silberkalebasse`,"Brinco de esmeralda":`Smaragdohrring`,"Garrafa antiga":`Alte Flasche`,"Moeda antiga":`Alte Münze`,"Pérola de rio":`Flussperle`,Diamante:`Diamant`,Opala:`Opal`,Ametista:`Amethyst`,Estanho:`Zinn`,Ferro:`Eisen`,Cobre:`Kupfer`,"Cacho de açaí":`Açaí-Traube`,"Ouriço de castanha":`Paranusskapsel`,"Concha de mexilhão":`Muschelschale`,"Casca de caramujo":`Schneckenhaus`,"Fragmento de arpão":`Harpunenteil`,Sucata:`Schrott`,"Caco de vidro":`Glasscherbe`,Corda:`Seil`,Madeira:`Holz`,"Tanque de ar":`Lufttank`,"Mais ar para ficar mais tempo lá embaixo.":`Mehr Luft, um länger unten zu bleiben.`,"de ar":`Luft`,Traje:`Anzug`,"Aguenta a pressão até mais fundo. Passou do limite, o ar acaba bem mais rápido.":`Hält dem Druck tiefer stand. Jenseits der Grenze geht die Luft viel schneller aus.`,m:`m`,Samburá:`Fischkorb`,"Cabe mais peixe e mais achado antes de pesar.":`Mehr Platz für Fisch und Funde, bevor es zu schwer wird.`,kg:`kg`,"Tiro mais forte: peixe resistente vem com menos disparos.":`Stärkerer Schuss: Zähe Fische brauchen weniger Treffer.`,"de dano":`Schaden`,"Golpe mais forte, para o que chega perto demais.":`Stärkerer Stich gegen alles, was zu nah kommt.`,Tarrafa:`Wurfnetz`,"Mais lances de rede por mergulho. Peixe de tarrafa vem vivo e vale mais.":`Mehr Netzwürfe pro Tauchgang. Fische aus dem Netz kommen lebend und bringen mehr.`,lances:`Würfe`,"Boia de resgate":`Rettungsboje`,"Leva o peixe grande direto para o barco, sem pesar no samburá.":`Bringt große Fische direkt zum Boot, ohne den Fischkorb zu belasten.`,"por mergulho":`pro Tauchgang`,"Ponta de aço":`Stahlspitze`,"+1 de dano":`+1 Schaden`,"Ponta farpada":`Widerhakenspitze`,"não solta: aperte Espaço na hora certa":`hält fest: Leertaste im richtigen Moment`,"Ponta elétrica":`Elektrospitze`,"+1 de dano · atordoa o peixe · alterne A e D":`+1 Schaden · betäubt den Fisch · A und D abwechseln`,"Ponta de timbó":`Timbó-Spitze`,"adormece o peixe: ele vem vivo · siga as setas":`schläfert den Fisch ein: er kommt lebend · folge den Pfeilen`,"Ponta de curare":`Curare-Spitze`,"veneno: tira vida aos poucos · aperte bem rápido":`Gift: zieht nach und nach Leben ab · schnell drücken`,"O que tem de bom hoje?":`Was gibt's heute Gutes?`,"Estou varado de fome...":`Ich hab Kohldampf...`,"Hum, que cheiro!":`Mmh, wie das duftet!`,"Capricha aí!":`Gib dir Mühe!`,"Isso é que é comida!":`Das nenn ich Essen!`,"Hum... que beleza.":`Mmh... herrlich.`,"Égua, que tá bom demais!":`Boah, ist das lecker!`,"Cheirou, chegou!":`Der Duft hat mich hergelockt!`,"Ô garçom!":`Hallo, Bedienung!`,"Vai demorar?":`Dauert's noch lange?`,"Esqueceram de mim?":`Habt ihr mich vergessen?`,"Faz tempo que eu não comia um {prato} assim. Volto amanhã e trago a família.":`So gut hab ich {prato} ewig nicht gegessen. Morgen komm ich wieder und bring die Familie mit.`,"Mal sentei e o prato já estava na minha frente. Isso é que é casa bem tocada!":`Kaum saß ich, stand das Essen schon vor mir. So führt man ein Lokal!`,"O {prato} da Dona Naná continua o melhor deste rio. Podem escrever.":`{prato} von Dona Naná ist immer noch das Beste am ganzen Fluss. Das könnt ihr aufschreiben.`,"Vim de longe só pelo {prato}. Valeu cada remada.":`Ich bin von weit her gekommen, nur für {prato}. Jeder Paddelschlag hat sich gelohnt.`,"A comida é boa, mas hoje a espera foi comprida.":`Das Essen ist gut, aber heute hat's echt lange gedauert.`,"Gostei do {prato}. Só achei o balcão meio atrapalhado.":`{prato} war lecker. Nur an der Theke war's etwas chaotisch.`,"Dá para voltar. Com mais ligeireza no serviço, eu voltava toda noite.":`Ich komm wieder. Mit flotterem Service käme ich jeden Abend.`,"Esperei, esperei e fui embora de barriga vazia. Assim não dá.":`Gewartet und gewartet, und mit leerem Magen gegangen. So geht das nicht.`,"Vi gente levantando sem comer. A casa precisa de mais braço no balcão.":`Leute sind ohne Essen aufgestanden. Hinter die Theke gehören mehr Hände.`,"Me trouxeram o prato do vizinho. Hoje não foi a noite de vocês.":`Ich hab das Essen vom Nachbarn bekommen. Heute war nicht euer Abend.`,"Calado e atento: limpa a banqueta antes de você notar que sujou.":`Still und aufmerksam: putzt den Platz, bevor du merkst, dass er schmutzig ist.`,"Soca o pilão cantando: a farinha não acaba mais.":`Stampft singend im Mörser: Das Mehl geht nie aus.`,"Devagar e certeiro: nunca erra a marca da cuia.":`Langsam und sicher: trifft die Markierung der Kalebasse immer.`,"Ligeira no balcão: pega o prato pronto e leva a quem pediu.":`Flink an der Theke: nimmt fertige Gerichte und bringt sie zum Gast.`,"Fogão de duas bocas":`Zweiflammiger Herd`,"A cozinha prepara cada prato mais rápido.":`Die Küche kocht jedes Gericht schneller.`,"s por prato":`s pro Gericht`,"Banquetas estofadas":`Gepolsterte Hocker`,"Sentado no macio, o freguês espera mais antes de desistir.":`Weich gesessen wartet der Gast länger, bevor er aufgibt.`,"s de paciência":`s Geduld`,"Pilão grande":`Großer Mörser`,"Cabe mais farinha antes de precisar socar de novo.":`Mehr Mehl, bevor du wieder stampfen musst.`,"de farinha":`Mehl`,"Lamparinas e flores":`Öllampen und Blumen`,"Casa bonita: mais fregueses deixam gorjeta.":`Schönes Lokal: Mehr Gäste geben Trinkgeld.`,"% dão gorjeta":`% geben Trinkgeld`,"Placa iluminada":`Leuchtschild`,"A casa se vê de longe: vêm mais fregueses por noite.":`Das Lokal sieht man von weitem: mehr Gäste pro Abend.`,"fregueses a mais":`Gäste extra`,Cafezinho:`Kaffee`,"Costela de tambaqui":`Tambaqui-Rippen`,"Filé de tucunaré":`Pfauenbarschfilet`,"Ventrecha de pirarucu":`Pirarucu-Bauchstück`,Rabeta:`Motorkanu`,Voadeira:`Schnellboot`,Batelão:`Lastkahn`,Recreio:`Fähre`,Gaiola:`Flussdampfer`,"Peixe frito":`Bratfisch`,"Caldo de piranha":`Piranhabrühe`,"Tucunaré na brasa":`Pfauenbarsch vom Grill`,"Tambaqui assado":`Tambaqui-Braten`,Caldeirada:`Caldeirada`,"Pirarucu de casaca":`Pirarucu de casaca`,"Aruanã assada na folha":`Im Blatt gebackener Arowana`,"Moqueca de arraia":`Rochen-Moqueca`,"Acari assado":`Gebratener Acari`,"Caldo de mandi":`Mandi-Brühe`,"Costela de tambaqui assada":`Gebratene Tambaqui-Rippen`,"Filé de tucunaré no tucupi":`Pfauenbarschfilet in Tucupi`},s=[{id:`pt`,nome:`Português`,local:`pt-BR`},{id:`en`,nome:`English`,local:`en-US`},{id:`es`,nome:`Español`,local:`es-ES`},{id:`zh`,nome:`简体中文`,local:`zh-CN`},{id:`ru`,nome:`Русский`,local:`ru-RU`},{id:`de`,nome:`Deutsch`,local:`de-DE`}],c={en:n,es:r,zh:i,ru:a,de:o},l=`banzeiro.idioma`;function u(e,t=[]){if(s.some(t=>t.id===e))return e;for(let e of t){let t=String(e).toLowerCase().split(`-`)[0];if(s.some(e=>e.id===t))return t}return`pt`}function d(){try{return globalThis.localStorage?.getItem(l)??null}catch{return null}}var f=globalThis.document?globalThis.navigator?.languages??[]:[],p=u(d(),f),m=s.find(e=>e.id===p).local,h=c[p]??{},g=new Map,_=()=>p,v=()=>m;function y(e){if(s.some(t=>t.id===e)&&e!==p){try{globalThis.localStorage?.setItem(l,e)}catch{}globalThis.location?.reload()}}function b(e,t){return t?e.replace(/\{(\w+)\}/g,(e,n)=>n in t?String(t[n]):e):e}function x(e,t){let n=p===`pt`?e:h[e];return b(typeof n==`string`?n:e,t)}function S(e,t,n,r){let i={n,...r};if(p===`pt`)return b(n===1?e:t,i);let a=h[e];return!a||typeof a!=`object`?b(n===1?e:t,i):(g.has(m)||g.set(m,new Intl.PluralRules(m)),b(a[g.get(m).select(n)]??a.other??t,i))}var C=(e,t)=>Number(e).toLocaleString(m,t);function w(e){return p===`de`||p===`zh`?e:e.toLowerCase()}var T=new S